CREATE OR REPLACE FUNCTION "private"."contract_content_sha256"("p_rendered" "jsonb", "p_commercial" "jsonb", "p_parties" "jsonb", "p_template_version_id" "uuid", "p_template_content_sha256" "text") RETURNS "text"
