SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "event_date" "date" NOT NULL,
    "timezone" "text" DEFAULT 'America/Toronto'::"text" NOT NULL,
    "venue_name" "text",
    "venue_address" "text",
    "lifecycle_status" "text" DEFAULT 'lead'::"text" NOT NULL,
    "booking_confirmed_at" timestamp with time zone,
    "planning_lock_at" timestamp with time zone,
    "planning_override_until" timestamp with time zone,
    "internal_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "active_proposal_id" "uuid",
    "archived_at" timestamp with time zone,
    "planning_client_closed_at" timestamp with time zone,
    "booking_source" "text" DEFAULT 'flux'::"text" NOT NULL,
    "dj_name" "text",
    CONSTRAINT "events_booked_has_confirmation" CHECK ((("lifecycle_status" <> ALL (ARRAY['booked'::"text", 'completed'::"text"])) OR ("booking_confirmed_at" IS NOT NULL))),
    CONSTRAINT "events_booking_source_valid" CHECK (("booking_source" = ANY (ARRAY['flux'::"text", 'external'::"text"]))),
    CONSTRAINT "events_dj_name_length" CHECK ((("dj_name" = "btrim"("dj_name")) AND (("length"("dj_name") >= 1) AND ("length"("dj_name") <= 80)))),
    CONSTRAINT "events_event_type_valid" CHECK (("event_type" ~ '^[a-z][a-z0-9_]{0,39}$'::"text")),
    CONSTRAINT "events_external_not_flux_booked" CHECK ((("booking_source" = 'flux'::"text") OR (("lifecycle_status" = 'lead'::"text") AND ("booking_confirmed_at" IS NULL) AND ("active_proposal_id" IS NULL)))),
    CONSTRAINT "events_internal_notes_length" CHECK (("length"("internal_notes") <= 20000)),
    CONSTRAINT "events_lifecycle_status_valid" CHECK (("lifecycle_status" = ANY (ARRAY['lead'::"text", 'pending_approval'::"text", 'awaiting_signature'::"text", 'awaiting_deposit'::"text", 'booked'::"text", 'completed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "events_timezone_valid" CHECK ("private"."is_valid_timezone"("timezone")),
    CONSTRAINT "events_title_length" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 200))),
    CONSTRAINT "events_venue_address_length" CHECK ((("length"("btrim"("venue_address")) >= 1) AND ("length"("btrim"("venue_address")) <= 500))),
    CONSTRAINT "events_venue_name_length" CHECK ((("length"("btrim"("venue_name")) >= 1) AND ("length"("btrim"("venue_name")) <= 200)))
);


ALTER TABLE "public"."events" OWNER TO "postgres";


COMMENT ON TABLE "public"."events" IS 'Staff-only table. Clients read safe columns via public.my_events(); internal_notes is never exposed to clients.';



COMMENT ON COLUMN "public"."events"."timezone" IS 'IANA timezone; governs planning cutoff and local timeline times.';



COMMENT ON COLUMN "public"."events"."planning_lock_at" IS 'Client planning deadline, set when the plan is set up and changed only by explicit staff actions. Clients can''t edit at or after it.';



COMMENT ON COLUMN "public"."events"."planning_override_until" IS 'Temporary reopening: clients can edit after the deadline until this time. Set and cleared only by staff actions.';



COMMENT ON COLUMN "public"."events"."active_proposal_id" IS 'The proposal clients can act on. Set only by send_proposal; never by staff directly.';



COMMENT ON COLUMN "public"."events"."archived_at" IS 'Set by set_event_archived. Hidden from default staff lists; blocks sends, approvals, contract generation and client sessions. Not a lifecycle status.';



COMMENT ON COLUMN "public"."events"."planning_client_closed_at" IS 'Client planning edits closed by staff at this time, whatever the deadline. Set and cleared only by the planning editing functions.';



COMMENT ON COLUMN "public"."events"."booking_source" IS 'flux: booked through Flux DJ (proposal, contract, booking policy). external: staff affirmed at creation that it is booked elsewhere; planning only. Set on insert, never changed.';



COMMENT ON COLUMN "public"."events"."dj_name" IS 'Optional name of the DJ handling this event; overrides tenants.dj_name in planning and the run sheet.';



CREATE OR REPLACE FUNCTION "private"."event_booked_for_planning"("p_event" "public"."events") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_event.booking_source
    when 'external' then true
    when 'flux' then p_event.booking_confirmed_at is not null and p_event.lifecycle_status in ('booked', 'completed')
    else false
  end;
$$;


ALTER FUNCTION "private"."event_booked_for_planning"("p_event" "public"."events") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."event_booked_for_planning"("p_event" "public"."events") IS 'Whether the event is booked for client planning: by Flux (confirmed booking) or affirmed by staff as booked elsewhere. Archive, access and setup are checked by callers.';



CREATE OR REPLACE FUNCTION "private"."event_finances_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.events e where e.tenant_id = new.tenant_id and e.id = new.event_id and e.booking_source = 'external') then
    perform private.payment_error('this event was booked outside Flux DJ, so Flux DJ doesn''t record its payments or invoice');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."event_finances_guard"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."event_finances_guard"() IS 'Refuses payment and invoice rows for events booked outside Flux DJ (events.booking_source = external), for every role.';



CREATE OR REPLACE FUNCTION "private"."event_payment_summary"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  t public.tenants%rowtype;
  c public.contracts%rowtype;
  v_has_terms boolean;
  v_currency text;
  v_received bigint;
  v_valid int;
  v_other_currency int;
begin
  select * into e from public.events where id = p_event_id;
  select * into t from public.tenants where id = e.tenant_id;
  -- The authoritative contract: signed, else currently sent (at most one of
  -- either exists per event).
  select * into c from public.contracts k
  where k.tenant_id = e.tenant_id and k.event_id = e.id and k.status in ('signed', 'sent')
  order by (k.status = 'signed') desc, k.sent_at desc
  limit 1;
  v_has_terms := found;
  v_currency := case when v_has_terms then c.currency else t.currency end;
  select coalesce(sum(p.amount_cents) filter (where p.currency = v_currency), 0),
         count(*) filter (where p.currency = v_currency),
         count(*) filter (where p.currency <> v_currency)
    into v_received, v_valid, v_other_currency
  from public.event_payments p
  where p.tenant_id = e.tenant_id and p.event_id = e.id and p.invalidated_at is null;

  return jsonb_build_object(
    'currency', v_currency,
    'terms', case when v_has_terms then jsonb_build_object(
        'status', c.status, 'contract_id', c.id,
        'total_cents', c.total_cents, 'deposit_percent', c.deposit_percent, 'deposit_cents', c.deposit_cents,
        'balance_cents', c.balance_cents, 'balance_due_date', c.balance_due_date) end,
    'received_cents', v_received,
    'valid_payments', v_valid,
    'other_currency_payments', v_other_currency,
    'deposit_outstanding_cents', case when v_has_terms then greatest(c.deposit_cents - v_received, 0) end,
    'remaining_balance_cents', case when v_has_terms then greatest(c.total_cents - v_received, 0) end,
    'credit_cents', case when v_has_terms then greatest(v_received - c.total_cents, 0) end,
    'invoice_url', (select b.invoice_url from public.event_billing b where b.event_id = e.id),
    'booking', jsonb_build_object(
      'lifecycle_status', e.lifecycle_status,
      'booking_confirmed_at', e.booking_confirmed_at,
      -- The signed contract's frozen policy; null for contracts generated
      -- before policies existed (staff check those explicitly).
      'policy', case when v_has_terms and c.status = 'signed' then c.booking_policy end,
      'legacy_signed', v_has_terms and c.status = 'signed' and c.booking_policy is null,
      -- Booked under the deposit policy but valid payments no longer cover
      -- the deposit (a payment was invalidated). The booking stands.
      'deposit_no_longer_met', e.lifecycle_status = 'booked' and v_has_terms and c.status = 'signed'
        and coalesce(c.booking_policy, 'on_deposit') = 'on_deposit' and v_received < c.deposit_cents)
  );
end;
$$;


ALTER FUNCTION "private"."event_payment_summary"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."event_payments_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (new.id, new.tenant_id, new.event_id, new.amount_cents, new.currency, new.paid_on, new.reference, new.note, new.idempotency_key,
      new.recorded_by_user_id, new.recorded_by_email, new.created_at)
     is distinct from
     (old.id, old.tenant_id, old.event_id, old.amount_cents, old.currency, old.paid_on, old.reference, old.note, old.idempotency_key,
      old.recorded_by_user_id, old.recorded_by_email, old.created_at) then
    raise exception 'recorded payments are immutable; invalidate the entry and record a new one' using errcode = 'check_violation';
  end if;
  if old.invalidated_at is not null
     and (new.invalidated_at, new.invalidated_by_user_id, new.invalidated_by_email, new.invalidation_reason)
         is distinct from (old.invalidated_at, old.invalidated_by_user_id, old.invalidated_by_email, old.invalidation_reason) then
    raise exception 'an invalidated payment cannot change' using errcode = 'check_violation';
  end if;
  if old.invalidated_at is null and new.invalidated_at is not null
     and current_setting('flux.invalidating_payment', true) is distinct from new.id::text then
    raise exception 'payments are invalidated only through invalidate_event_payment' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."event_payments_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."events_active_proposal_matches"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.active_proposal_id is not null and not exists (
    select 1 from public.proposals p
    where p.tenant_id = new.tenant_id and p.id = new.active_proposal_id and p.event_id = new.id
  ) then
    raise exception 'active proposal must belong to the event' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


