CREATE OR REPLACE FUNCTION "private"."events_booking_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.booking_confirmed_at is not null and new.booking_confirmed_at is distinct from old.booking_confirmed_at then
    raise exception 'booking_confirmed_at is set once' using errcode = 'check_violation';
  end if;
  if old.lifecycle_status = 'booked' and new.lifecycle_status not in ('booked', 'completed', 'cancelled') then
    raise exception 'a booked event cannot go back to %', new.lifecycle_status using errcode = 'check_violation';
  end if;
  if new.lifecycle_status = 'booked' and old.lifecycle_status <> 'booked'
     and current_setting('flux.booking_event', true) is distinct from new.id::text then
    raise exception 'events are booked only through evaluate_booking' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."events_booking_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."events_initialize_planning"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.booking_confirmed_at is not null and old.booking_confirmed_at is null then
    perform private.ensure_event_plan(new.id, null, 'booking');
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."events_initialize_planning"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."events_planning_cutoff_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (tg_op = 'INSERT' and (new.planning_lock_at is not null or new.planning_override_until is not null or new.planning_client_closed_at is not null))
     or (tg_op = 'UPDATE' and (new.planning_lock_at is distinct from old.planning_lock_at
                               or new.planning_override_until is distinct from old.planning_override_until
                               or new.planning_client_closed_at is distinct from old.planning_client_closed_at)) then
    if current_setting('flux.planning_cutoff_event', true) is distinct from new.id::text then
      raise exception 'the planning deadline changes only through the planning cutoff functions' using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."events_planning_cutoff_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."forbid_column_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  col text;
begin
  foreach col in array tg_argv loop
    if (to_jsonb(new) -> col) is distinct from (to_jsonb(old) -> col) then
      raise exception 'column %.% is immutable', tg_table_name, col
        using errcode = 'check_violation';
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "private"."forbid_column_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."forbid_duplicate_logistics_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not new.active then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('flux:logistics-rule:' || new.question_id::text, 0));
  if exists (
    select 1 from public.logistics_rules r
    where r.tenant_id = new.tenant_id
      and r.question_id = new.question_id
      and r.id <> new.id
      and r.active
      and r.gear_item_id = new.gear_item_id
      and r.required_quantity = new.required_quantity
      and r.reason = new.reason
      and private.rule_condition_key(r.condition) = private.rule_condition_key(new.condition)
  ) then
    raise exception 'rule_duplicate: an identical active rule already exists for this question'
      using errcode = 'unique_violation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."forbid_duplicate_logistics_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."format_cents"("p_cents" bigint, "p_currency" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select case when p_cents < 0 then '-' else '' end
      || to_char(abs(p_cents) / 100, 'FM999,999,999,999,990')
      || '.' || lpad((abs(p_cents) % 100)::text, 2, '0')
      || ' ' || p_currency;
$$;


ALTER FUNCTION "private"."format_cents"("p_cents" bigint, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."format_rate_ppm"("p_ppm" bigint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
