CREATE OR REPLACE FUNCTION "private"."gear_media_extension_matches"("object_name" "text", "content_type" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select case content_type
    when 'image/jpeg' then object_name ~ '\.(jpg|jpeg)$'
    when 'image/png'  then object_name ~ '\.png$'
    when 'image/webp' then object_name ~ '\.webp$'
    when 'image/avif' then object_name ~ '\.avif$'
    when 'video/mp4'  then object_name ~ '\.mp4$'
    when 'video/webm' then object_name ~ '\.webm$'
    else false
  end;
$_$;


ALTER FUNCTION "private"."gear_media_extension_matches"("object_name" "text", "content_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."gear_media_type_kind"("content_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select case content_type
    when 'image/jpeg' then 'image'
    when 'image/png'  then 'image'
    when 'image/webp' then 'image'
    when 'image/avif' then 'image'
    when 'video/mp4'  then 'video'
    when 'video/webm' then 'video'
  end;
$$;


ALTER FUNCTION "private"."gear_media_type_kind"("content_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."gear_quantity_text"("p_gear" "jsonb", "p_name" "text", "p_quantity" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  with g as (
    select
      case when jsonb_typeof(p_gear -> 'pieces_per_unit') = 'number' and (p_gear ->> 'pieces_per_unit') ~ '^[0-9]{1,4}$'
                and (p_gear ->> 'pieces_per_unit')::int > 1
           then (p_gear ->> 'pieces_per_unit')::int else 1 end as pieces,
      coalesce(nullif(btrim(p_gear ->> 'piece_label'), ''), 'pieces') as label,
      btrim(coalesce(p_gear ->> 'unit_label', '')) as unit
  )
  select case
    when g.pieces = 1 then p_quantity || ' × ' || p_name
    when g.unit ~* '^[a-z]+$' and lower(g.unit) <> 'unit' then
      p_quantity || ' ' || private.plural_unit(g.unit, p_quantity) || ' of ' || p_name
      || ' (' || (p_quantity::bigint * g.pieces) || ' ' || g.label || ')'
    else p_quantity || ' × ' || p_name || ' (' || (p_quantity::bigint * g.pieces) || ' ' || g.label || ')'
  end
  from g;
$_$;


ALTER FUNCTION "private"."gear_quantity_text"("p_gear" "jsonb", "p_name" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."grant_platform_admin"("p_email" "text", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_users uuid[];
begin
  select array_agg(u.id) into v_users from auth.users u
  where lower(u.email) = lower(btrim(p_email)) and u.email_confirmed_at is not null;
  if coalesce(array_length(v_users, 1), 0) <> 1 then
    raise exception 'expected exactly one verified Auth user with that email, found %', coalesce(array_length(v_users, 1), 0)
      using errcode = 'no_data_found';
  end if;
  insert into public.platform_admins (user_id, note) values (v_users[1], btrim(p_note))
    on conflict (user_id) do nothing;
  if found then
    perform private.platform_audit('platform_admin', v_users[1], 'granted', null, jsonb_build_object('note', btrim(p_note)));
  end if;
  return v_users[1];
end;
$$;


ALTER FUNCTION "private"."grant_platform_admin"("p_email" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."insert_selection_submission"("p_proposal_id" "uuid", "p_selection" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_proposal public.proposals%rowtype;
  v_selection_id uuid;
begin
  select * into v_proposal from public.proposals where id = p_proposal_id;
  if v_proposal.offer_snapshot is null then
    raise exception 'the offer is not frozen yet' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.proposal_selections (
    tenant_id, proposal_id, version, package_key, addon_quantities, logistics_answers,
    subtotal_cents, discount_cents, tax_cents, total_cents, currency, tax_breakdown, selection_snapshot,
    pricing_version, offer_sha256, submitted_at, idempotency_key
  ) values (
    v_proposal.tenant_id, v_proposal.id, v_proposal.current_selection_version + 1,
    p_selection ->> 'package_key', p_selection -> 'addon_quantities', p_selection -> 'logistics_answers',
    (p_selection ->> 'subtotal_cents')::bigint, coalesce((p_selection ->> 'discount_cents')::bigint, 0),
    (p_selection ->> 'tax_cents')::bigint, (p_selection ->> 'total_cents')::bigint,
    p_selection ->> 'currency', p_selection -> 'tax_breakdown', p_selection,
    p_selection ->> 'pricing_version', p_selection ->> 'offer_sha256', now(), p_idempotency_key
  )
  returning id into v_selection_id;

  insert into public.proposal_selection_lines (
    tenant_id, selection_id, line_no, source, item_key, name, description, quantity,
    unit_price_cents, line_total_cents, required_quantity, required_reasons, tax_category, discount_cents
  )
  select v_proposal.tenant_id, v_selection_id, l.ord::int,
         l.x ->> 'source', l.x ->> 'item_key', l.x ->> 'name', l.x ->> 'description',
         (l.x ->> 'quantity')::int, (l.x ->> 'unit_price_cents')::bigint, (l.x ->> 'line_total_cents')::bigint,
         coalesce((l.x ->> 'required_quantity')::int, 0),
         coalesce(array(select jsonb_array_elements_text(l.x -> 'required_reasons')), '{}'),
         l.x ->> 'tax_category', coalesce((l.x ->> 'discount_cents')::bigint, 0)
  from jsonb_array_elements(p_selection -> 'lines') with ordinality as l(x, ord);

  update public.proposals set current_selection_version = v_proposal.current_selection_version + 1 where id = v_proposal.id;
  return v_selection_id;
end;
$$;


ALTER FUNCTION "private"."insert_selection_submission"("p_proposal_id" "uuid", "p_selection" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";


