CREATE OR REPLACE FUNCTION "private"."is_valid_discount"("d" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select case
    when jsonb_typeof(d) <> 'object' then false
    when jsonb_typeof(d -> 'label') is not null and jsonb_typeof(d -> 'label') not in ('string', 'null') then false
    when length(coalesce(d ->> 'label', '')) > 80 then false
    when d ->> 'type' = 'percent' then
      not exists (select 1 from jsonb_object_keys(d) k where k not in ('type', 'percent_basis_points', 'label'))
      and case when jsonb_typeof(d -> 'percent_basis_points') is distinct from 'number'
                 or (d ->> 'percent_basis_points') !~ '^[0-9]{1,5}$' then false
               else (d ->> 'percent_basis_points')::int <= 10000 end
    when d ->> 'type' = 'fixed' then
      not exists (select 1 from jsonb_object_keys(d) k where k not in ('type', 'amount_cents', 'label'))
      and case when jsonb_typeof(d -> 'amount_cents') is distinct from 'number'
                 or (d ->> 'amount_cents') !~ '^[0-9]{1,9}$' then false
               else (d ->> 'amount_cents')::bigint <= 100000000 end
    else false
  end;
$_$;


ALTER FUNCTION "private"."is_valid_discount"("d" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_draft_offer"("draft" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select jsonb_typeof(draft) = 'object'
     and not exists (select 1 from jsonb_object_keys(draft) k
                     where k not in ('template_id', 'intro', 'expiry_days', 'packages', 'addons', 'question_ids', 'price_overrides', 'discount'))
     and coalesce(jsonb_typeof(draft -> 'template_id') in ('string', 'null'), true)
     and (jsonb_typeof(draft -> 'template_id') is distinct from 'string' or private.is_uuid_text(draft ->> 'template_id'))
     and coalesce(jsonb_typeof(draft -> 'intro') in ('string', 'null'), true)
     and coalesce(length(draft ->> 'intro') <= 10000, true)
     and coalesce(jsonb_typeof(draft -> 'expiry_days') in ('number', 'null'), true)
     and coalesce(jsonb_typeof(draft -> 'packages') = 'array' and jsonb_array_length(draft -> 'packages') <= 3, true)
     and coalesce(jsonb_typeof(draft -> 'addons') = 'array' and jsonb_array_length(draft -> 'addons') <= 100, true)
     and coalesce(jsonb_typeof(draft -> 'question_ids') = 'array' and jsonb_array_length(draft -> 'question_ids') <= 100, true)
     and coalesce(private.is_valid_price_overrides(draft -> 'price_overrides'), true)
     and (jsonb_typeof(draft -> 'discount') is null or jsonb_typeof(draft -> 'discount') = 'null' or private.is_valid_discount(draft -> 'discount'));
$$;


ALTER FUNCTION "private"."is_valid_draft_offer"("draft" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_email"("email" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select length(email) <= 320
     and email = lower(btrim(email))
     and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$';
$_$;


ALTER FUNCTION "private"."is_valid_email"("email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_gear_media_path"("object_name" "text", "p_tenant_id" "uuid", "p_gear_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from private.parse_gear_media_path(object_name) p
    where p.tenant_id = p_tenant_id and p.gear_item_id = p_gear_item_id
  );
$$;


ALTER FUNCTION "private"."is_valid_gear_media_path"("object_name" "text", "p_tenant_id" "uuid", "p_gear_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_key"("k" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select k ~ '^[a-z][a-z0-9_]{0,63}$';
$_$;


ALTER FUNCTION "private"."is_valid_key"("k" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_package_media_path"("object_name" "text", "p_tenant_id" "uuid", "p_package_id" "uuid") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from private.parse_package_media_path(object_name) p
    where p.tenant_id = p_tenant_id and p.package_id = p_package_id
  );
$$;


ALTER FUNCTION "private"."is_valid_package_media_path"("object_name" "text", "p_tenant_id" "uuid", "p_package_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_price_overrides"("overrides" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select jsonb_typeof(overrides) = 'array'
     and jsonb_array_length(overrides) <= 100
     and not exists (
       select 1 from jsonb_array_elements(overrides) o
       where case
         when jsonb_typeof(o) <> 'object' then true
         when (select array_agg(k order by k) from jsonb_object_keys(o) k) is distinct from array['gear_item_id', 'unit_price_cents']
          and (select array_agg(k order by k) from jsonb_object_keys(o) k) is distinct from array['package_id', 'unit_price_cents'] then true
         when jsonb_typeof(coalesce(o -> 'gear_item_id', o -> 'package_id')) <> 'string'
           or not private.is_uuid_text(coalesce(o ->> 'gear_item_id', o ->> 'package_id'))
           or jsonb_typeof(o -> 'unit_price_cents') <> 'number'
           or (o ->> 'unit_price_cents') !~ '^[0-9]{1,9}$'
           then true
         else (o ->> 'unit_price_cents')::bigint > 100000000
       end
     )
     and (select count(distinct o ->> 'gear_item_id') = count(o ->> 'gear_item_id')
            and count(distinct o ->> 'package_id') = count(o ->> 'package_id')
          from jsonb_array_elements(overrides) o);
$_$;


ALTER FUNCTION "private"."is_valid_price_overrides"("overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_question_options"("answer_type" "text", "options" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select case
    when answer_type in ('boolean', 'short_text') then options = '[]'::jsonb
    when answer_type in ('single_choice', 'multi_choice') then
      jsonb_typeof(options) = 'array'
      and jsonb_array_length(options) between 1 and 50
      and not exists (
        select 1 from jsonb_array_elements(options) as o(item)
        where jsonb_typeof(o.item) <> 'object'
           or (select count(*) from jsonb_object_keys(o.item)) <> 2
           or jsonb_typeof(o.item -> 'value') <> 'string'
           or not private.is_valid_key(o.item ->> 'value')
           or jsonb_typeof(o.item -> 'label') <> 'string'
           or length(btrim(o.item ->> 'label')) not between 1 and 200
      )
      and (select count(distinct o.item ->> 'value') = count(*)
           from jsonb_array_elements(options) as o(item))
    else false
  end;
$$;


ALTER FUNCTION "private"."is_valid_question_options"("answer_type" "text", "options" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_rule_condition"("condition" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select jsonb_typeof(condition) = 'object'
     and case condition ->> 'op'
       when 'equals' then
         (select array_agg(k order by k) from jsonb_object_keys(condition) k) = array['op', 'value']
         and (
           jsonb_typeof(condition -> 'value') = 'boolean'
           or (jsonb_typeof(condition -> 'value') = 'string' and private.is_valid_key(condition ->> 'value'))
         )
       when 'contains' then
         (select array_agg(k order by k) from jsonb_object_keys(condition) k) = array['op', 'value']
         and jsonb_typeof(condition -> 'value') = 'string'
         and private.is_valid_key(condition ->> 'value')
       when 'in' then
         (select array_agg(k order by k) from jsonb_object_keys(condition) k) = array['op', 'values']
         and jsonb_typeof(condition -> 'values') = 'array'
         and jsonb_array_length(condition -> 'values') between 1 and 50
         and not exists (
           select 1 from jsonb_array_elements(condition -> 'values') v(item)
           where jsonb_typeof(v.item) <> 'string' or not private.is_valid_key(v.item #>> '{}')
         )
         and (select count(distinct v.item) = count(*) from jsonb_array_elements(condition -> 'values') v(item))
       else false
     end;
$$;


ALTER FUNCTION "private"."is_valid_rule_condition"("condition" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_tax_categories"("tax_config" "jsonb", "tax_categories" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select jsonb_typeof(tax_categories) = 'object'
     and (select count(*) from jsonb_object_keys(tax_categories)) <= 20
     and not exists (
       select 1 from jsonb_each(tax_categories) as c(key, codes)
       where not private.is_valid_key(c.key)
          or jsonb_typeof(c.codes) <> 'array'
          or exists (
            select 1 from jsonb_array_elements(c.codes) as x(code)
            where jsonb_typeof(x.code) <> 'string'
               or not exists (
                 select 1 from jsonb_array_elements(tax_config) t(item)
                 where t.item ->> 'code' = x.code #>> '{}'
               )
          )
          or (select count(distinct x.code) <> count(*) from jsonb_array_elements(c.codes) x(code))
     );
$$;


ALTER FUNCTION "private"."is_valid_tax_categories"("tax_config" "jsonb", "tax_categories" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_tax_config"("config" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select jsonb_typeof(config) = 'array'
     and jsonb_array_length(config) <= 5
     and not exists (
       select 1
       from jsonb_array_elements(config) as t(item)
       where jsonb_typeof(t.item) <> 'object'
          or (select count(*) from jsonb_object_keys(t.item)) <> 3
          or jsonb_typeof(t.item -> 'code') <> 'string'
          or (t.item ->> 'code') !~ '^[A-Z0-9_]{1,16}$'
          or jsonb_typeof(t.item -> 'label') <> 'string'
          or length(btrim(t.item ->> 'label')) not between 1 and 40
          or jsonb_typeof(t.item -> 'rate_ppm') <> 'number'
          or (t.item ->> 'rate_ppm') !~ '^[0-9]+$'
          or (t.item ->> 'rate_ppm')::bigint > 1000000
     )
     and (
       select count(distinct t.item ->> 'code') = count(*)
       from jsonb_array_elements(config) as t(item)
     );
$_$;


ALTER FUNCTION "private"."is_valid_tax_config"("config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_valid_tenant_slug"("slug" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select slug ~ '^[a-z0-9][a-z0-9-]{1,46}[a-z0-9]$'
     and slug !~ '--'
     and slug not in (
       'admin', 'api', 'app', 'assets', 'auth', 'callback', 'dashboard', 'flux',
       'fluxdj', 'help', 'legal', 'login', 'logout', 'manifest', 'my', 'offline',
       'privacy', 'public', 'settings', 'signin', 'signup', 'staff', 'static',
       'support', 'terms', 'www'
     );
$_$;


ALTER FUNCTION "private"."is_valid_tenant_slug"("slug" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."contracts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    "proposal_id" "uuid" NOT NULL,
    "selection_id" "uuid" NOT NULL,
    "approval_id" "uuid" NOT NULL,
    "template_id" "uuid" NOT NULL,
    "template_version_id" "uuid" NOT NULL,
    "template_content_sha256" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "status_changed_at" timestamp with time zone,
    "replaces_id" "uuid",
    "signer_client_id" "uuid" NOT NULL,
    "signer_name" "text" NOT NULL,
    "signer_email" "text" NOT NULL,
    "currency" "text" NOT NULL,
    "total_cents" bigint NOT NULL,
    "deposit_cents" bigint NOT NULL,
    "balance_cents" bigint NOT NULL,
    "balance_due_date" "date",
    "rendered_content" "jsonb" NOT NULL,
    "commercial_snapshot" "jsonb" NOT NULL,
    "party_snapshot" "jsonb" NOT NULL,
    "content_sha256" "text" NOT NULL,
    "generated_by_membership_id" "uuid",
    "generated_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deposit_percent" integer NOT NULL,
    "sent_at" timestamp with time zone,
    "voided_at" timestamp with time zone,
    "void_reason" "text",
    "signed_at" timestamp with time zone,
    "signing_mode" "text" NOT NULL,
    "consent_version" "text",
    "booking_policy" "text",
    CONSTRAINT "contracts_balance_nonnegative" CHECK (("balance_cents" >= 0)),
    CONSTRAINT "contracts_booking_policy_valid" CHECK (("booking_policy" = ANY (ARRAY['on_deposit'::"text", 'on_signature'::"text"]))),
    CONSTRAINT "contracts_commercial_object" CHECK (("jsonb_typeof"("commercial_snapshot") = 'object'::"text")),
    CONSTRAINT "contracts_consent_matches_mode" CHECK (
CASE "signing_mode"
    WHEN 'demo'::"text" THEN ("consent_version" = 'demo-v1'::"text")
    WHEN 'client_use'::"text" THEN ("consent_version" = 'client-v1'::"text")
    ELSE ("consent_version" IS NULL)
END),
    CONSTRAINT "contracts_content_sha256_format" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contracts_currency_valid" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "contracts_deposit_nonnegative" CHECK (("deposit_cents" >= 0)),
    CONSTRAINT "contracts_deposit_percent_matches_snapshot" CHECK ((((("commercial_snapshot" -> 'payment'::"text") ->> 'deposit_basis_points'::"text"))::integer = ("deposit_percent" * 100))),
    CONSTRAINT "contracts_deposit_percent_range" CHECK ((("deposit_percent" >= 0) AND ("deposit_percent" <= 100))),
    CONSTRAINT "contracts_deposit_plus_balance" CHECK ((("deposit_cents" + "balance_cents") = "total_cents")),
    CONSTRAINT "contracts_party_object" CHECK (("jsonb_typeof"("party_snapshot") = 'object'::"text")),
    CONSTRAINT "contracts_rendered_shape" CHECK ((("jsonb_typeof"("rendered_content") = 'object'::"text") AND ("jsonb_typeof"(("rendered_content" -> 'title'::"text")) = 'string'::"text") AND ("jsonb_typeof"(("rendered_content" -> 'sections'::"text")) = 'array'::"text"))),
    CONSTRAINT "contracts_sent_at_matches_status" CHECK ((("status" = ANY (ARRAY['sent'::"text", 'signed'::"text", 'void'::"text"])) = ("sent_at" IS NOT NULL))),
    CONSTRAINT "contracts_signed_matches_status" CHECK ((("status" = 'signed'::"text") = ("signed_at" IS NOT NULL))),
    CONSTRAINT "contracts_signer_email_valid" CHECK ("private"."is_valid_email"("signer_email")),
    CONSTRAINT "contracts_signer_name_length" CHECK ((("length"("btrim"("signer_name")) >= 1) AND ("length"("btrim"("signer_name")) <= 200))),
    CONSTRAINT "contracts_signing_mode_valid" CHECK (("signing_mode" = ANY (ARRAY['demo'::"text", 'client_use'::"text", 'none'::"text"]))),
    CONSTRAINT "contracts_status_valid" CHECK (("status" = ANY (ARRAY['draft'::"text", 'replaced'::"text", 'superseded'::"text", 'sent'::"text", 'signed'::"text", 'void'::"text"]))),
    CONSTRAINT "contracts_template_sha256_format" CHECK (("template_content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contracts_total_nonnegative" CHECK (("total_cents" >= 0)),
    CONSTRAINT "contracts_void_matches_status" CHECK ((("status" = 'void'::"text") = (("voided_at" IS NOT NULL) AND ("void_reason" IS NOT NULL)))),
    CONSTRAINT "contracts_void_reason_length" CHECK ((("length"("btrim"("void_reason")) >= 1) AND ("length"("btrim"("void_reason")) <= 500)))
);


ALTER TABLE "public"."contracts" OWNER TO "postgres";


COMMENT ON TABLE "public"."contracts" IS 'Contracts rendered from an approved selection and a published template version. Content, terms and hash never change after insert; only status moves. Staff-only.';



COMMENT ON COLUMN "public"."contracts"."content_sha256" IS 'SHA-256 of the canonical jsonb text of private.contract_hash_document(rendered_content, commercial_snapshot, party_snapshot, template_version_id, template_content_sha256). Not a PDF hash.';



COMMENT ON COLUMN "public"."contracts"."deposit_percent" IS 'Deposit percentage frozen at generation (also in commercial_snapshot.payment).';



COMMENT ON COLUMN "public"."contracts"."sent_at" IS 'When the contract was first sent. Set once by the database; resends never change it.';



COMMENT ON COLUMN "public"."contracts"."signed_at" IS 'When the contract was signed (database time, set once by sign_contract).';



COMMENT ON COLUMN "public"."contracts"."signing_mode" IS 'demo | client_use | none, frozen from the template version at generation. none: generated from a legacy version; cannot be signed or sent.';



COMMENT ON COLUMN "public"."contracts"."consent_version" IS 'The consent statement version the signer is shown, frozen at generation. Null when signing_mode is none.';



COMMENT ON COLUMN "public"."contracts"."booking_policy" IS 'Booking policy frozen at generation. Null for contracts generated before policies existed (checked explicitly by staff).';



CREATE OR REPLACE FUNCTION "private"."issue_contract_invitation"("c" "public"."contracts", "p_link_id" "uuid", "p_token_hash" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_expires timestamptz := now() + interval '14 days';
begin
  if p_link_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid access link' using errcode = 'invalid_parameter_value';
  end if;
  insert into public.access_links (id, tenant_id, purpose, proposal_id, contract_id, intended_client_id, token_hash, expires_at)
  values (p_link_id, c.tenant_id, 'contract', c.proposal_id, c.id, c.signer_client_id, p_token_hash, v_expires);
  perform private.enqueue_contract_email(
    c.tenant_id, 'contract_sent', c.signer_email, c.id, p_link_id,
    jsonb_build_object(
      'client_name', c.signer_name,
      'event_title', c.party_snapshot -> 'event' ->> 'title',
      'legal_name', coalesce(c.party_snapshot -> 'business' ->> 'legal_name', c.party_snapshot -> 'business' ->> 'name'),
      'contact_email', c.party_snapshot -> 'business' ->> 'contact_email',
      'deposit_cents', c.deposit_cents, 'deposit_percent', c.deposit_percent, 'currency', c.currency,
      'invitation_expires_at', v_expires),
    'contract_sent:' || p_link_id);
  return v_expires;
end;
$_$;


ALTER FUNCTION "private"."issue_contract_invitation"("c" "public"."contracts", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_contract_for_staff"("p_contract_id" "uuid") RETURNS "public"."contracts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
begin
  select * into c from public.contracts where id = p_contract_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(c.tenant_id);
  perform 1 from public.events where tenant_id = c.tenant_id and id = c.event_id for update;
  perform 1 from public.proposals where tenant_id = c.tenant_id and id = c.proposal_id for update;
  select * into c from public.contracts where id = p_contract_id for update;
  return c;
end;
$$;


ALTER FUNCTION "private"."lock_contract_for_staff"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."event_plans" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    "source_template_id" "uuid",
    "source_template_name" "text",
    "source_template_version" integer,
    "origin" "text" NOT NULL,
    "initialized_via" "text" NOT NULL,
    "structure_version" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_cutoff_days" integer NOT NULL,
    "client_cutoff_version" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "event_plans_client_cutoff_days_range" CHECK ((("client_cutoff_days" >= 0) AND ("client_cutoff_days" <= 365))),
    CONSTRAINT "event_plans_client_cutoff_version_positive" CHECK (("client_cutoff_version" >= 1)),
    CONSTRAINT "event_plans_initialized_via_valid" CHECK (("initialized_via" = ANY (ARRAY['booking'::"text", 'backfill'::"text", 'staff'::"text"]))),
    CONSTRAINT "event_plans_origin_matches" CHECK ((("origin" = 'template'::"text") = ("source_template_id" IS NOT NULL))),
    CONSTRAINT "event_plans_origin_valid" CHECK (("origin" = ANY (ARRAY['template'::"text", 'fallback'::"text"]))),
    CONSTRAINT "event_plans_structure_version_positive" CHECK (("structure_version" >= 1))
);


ALTER TABLE "public"."event_plans" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_plans" IS 'One planning instance per event, copied from a template (or a minimal fallback). Created at booking or by staff.';



COMMENT ON COLUMN "public"."event_plans"."client_cutoff_days" IS 'Days before the event the client deadline was computed with: the business setting when the plan was set up, or set by staff.';



COMMENT ON COLUMN "public"."event_plans"."client_cutoff_version" IS 'Optimistic version of the client deadline and reopening (events.planning_lock_at, planning_override_until).';



CREATE OR REPLACE FUNCTION "private"."lock_plan_cutoff_for_staff"("p_event_id" "uuid") RETURNS "public"."event_plans"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  p public.event_plans%rowtype;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into e from public.events where id = e.id for no key update;
  if e.archived_at is not null then
    perform private.planning_error('the event is archived. Unarchive it before changing its planning');
  end if;
  select * into p from public.event_plans where tenant_id = e.tenant_id and event_id = e.id for update;
  if not found then
    perform private.planning_error('planning isn''t set up for this event yet');
  end if;
  return p;
end;
$$;


ALTER FUNCTION "private"."lock_plan_cutoff_for_staff"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."lock_plan_for_staff"("p_event_id" "uuid", "p_expected_version" integer) RETURNS "public"."event_plans"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  p public.event_plans%rowtype;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into e from public.events where id = e.id for share;
  if e.archived_at is not null then
    perform private.planning_error('the event is archived. Unarchive it before changing its planning');
  end if;
  select * into p from public.event_plans where tenant_id = e.tenant_id and event_id = e.id for update;
  if not found then
    perform private.planning_error('planning isn''t set up for this event yet');
  end if;
  if p_expected_version is not null and p.structure_version <> p_expected_version then
    raise exception 'planning structure was changed elsewhere' using errcode = 'PT409';
  end if;
  return p;
end;
$$;


ALTER FUNCTION "private"."lock_plan_for_staff"("p_event_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."event_plan_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
