    CONSTRAINT "event_plan_items_parent_shape" CHECK ((("kind" = 'moment'::"text") = ("parent_id" IS NOT NULL))),
    CONSTRAINT "event_plan_items_position_range" CHECK ((("position" >= 0) AND ("position" <= 10000)))
);


ALTER TABLE "public"."event_plan_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."event_plan_items" IS 'A library item in one event''s plan. Never deleted: disabled and restored, so answers survive.';



CREATE OR REPLACE FUNCTION "private"."lock_plan_item_for_staff"("p_item_id" "uuid", "p_expected_version" integer) RETURNS "public"."event_plan_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.event_plan_items%rowtype;
  v_event uuid;
begin
  select * into i from public.event_plan_items where id = p_item_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  select event_id into v_event from public.event_plans where id = i.plan_id;
  perform private.lock_plan_for_staff(v_event, p_expected_version);
  select * into i from public.event_plan_items where id = i.id;
  return i;
end;
$$;


ALTER FUNCTION "private"."lock_plan_item_for_staff"("p_item_id" "uuid", "p_expected_version" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."planning_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "starter_key" "text",
    "default_event_type" "text",
    "version" integer DEFAULT 1 NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "planning_templates_archived_not_default" CHECK ((("archived_at" IS NULL) OR ("default_event_type" IS NULL))),
    CONSTRAINT "planning_templates_default_event_type_valid" CHECK (("default_event_type" ~ '^[a-z][a-z0-9_]{0,39}$'::"text")),
    CONSTRAINT "planning_templates_description_length" CHECK (("length"("description") <= 1000)),
    CONSTRAINT "planning_templates_name_length" CHECK ((("length"("btrim"("name")) >= 1) AND ("length"("btrim"("name")) <= 120))),
    CONSTRAINT "planning_templates_starter_key_valid" CHECK (("starter_key" = ANY (ARRAY['wedding'::"text", 'simple_party'::"text"]))),
    CONSTRAINT "planning_templates_version_positive" CHECK (("version" >= 1))
);


ALTER TABLE "public"."planning_templates" OWNER TO "postgres";


COMMENT ON TABLE "public"."planning_templates" IS 'Reusable planning structure of one business. Structure only: no prices, services or gear. Archived, never deleted.';



CREATE OR REPLACE FUNCTION "private"."lock_planning_template"("p_template_id" "uuid", "p_expected_version" integer) RETURNS "public"."planning_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  t public.planning_templates%rowtype;
begin
  select * into t from public.planning_templates where id = p_template_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(t.tenant_id);
  select * into t from public.planning_templates where id = t.id for update;
  if p_expected_version is null or t.version <> p_expected_version then
    raise exception 'planning template was changed elsewhere' using errcode = 'PT409';
  end if;
  if t.archived_at is not null then
    perform private.planning_error('this template is archived. Unarchive it before editing');
  end if;
  return t;
end;
$$;


