CREATE OR REPLACE FUNCTION "private"."move_plan_client_cutoff"("p_event_id" "uuid", "p_expected_version" integer, "p_days" integer, "p_reason" "text", "p_op" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.event_plans%rowtype;
  e public.events%rowtype;
  v_reason text;
  v_days integer;
  v_before timestamptz;
  v_before_days integer;
  v_after timestamptz;
begin
  p := private.lock_plan_cutoff_for_staff(p_event_id);
  v_before_days := p.client_cutoff_days;
  select * into e from public.events where id = p.event_id;
  v_reason := private.planning_reason(p_reason);
  v_days := coalesce(p_days, p.client_cutoff_days);
  if v_days < 0 or v_days > 365 then
    perform private.planning_error('enter a whole number of days from 0 to 365');
  end if;
  v_before := private.plan_deadline(e, p);
  v_after := private.planning_cutoff_at(e.event_date, e.timezone, v_days);
  if p_expected_version is null or p.client_cutoff_version <> p_expected_version then
    -- A repeated click whose change is already in place is the same change.
    if v_before = v_after and p.client_cutoff_days = v_days then
      return jsonb_build_object('status', 'unchanged', 'version', p.client_cutoff_version, 'editing', private.plan_staff_editing(e, p));
    end if;
    raise exception 'the planning deadline was changed elsewhere' using errcode = 'PT409';
  end if;
  if v_before = v_after and p.client_cutoff_days = v_days then
    return jsonb_build_object('status', 'unchanged', 'version', p.client_cutoff_version, 'editing', private.plan_staff_editing(e, p));
  end if;
  perform private.set_plan_cutoff_columns(e.id, v_after, e.planning_override_until);
  update public.event_plans set client_cutoff_days = v_days, client_cutoff_version = client_cutoff_version + 1
  where id = p.id returning * into p;
  select * into e from public.events where id = p.event_id;
  perform private.audit(e.tenant_id, 'event', e.id, 'planning_cutoff_' || p_op, 'staff', (select auth.uid()),
    jsonb_build_object('reason', v_reason, 'at', clock_timestamp(),
                       'event_date', e.event_date, 'timezone', e.timezone,
                       'before', jsonb_build_object('deadline', v_before, 'days', v_before_days),
                       'after', jsonb_build_object('deadline', v_after, 'days', v_days)));
  return jsonb_build_object('status', p_op, 'version', p.client_cutoff_version, 'editing', private.plan_staff_editing(e, p));
end;
$$;


ALTER FUNCTION "private"."move_plan_client_cutoff"("p_event_id" "uuid", "p_expected_version" integer, "p_days" integer, "p_reason" "text", "p_op" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_answers"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when p_editor = 'basics' then private.normalize_plan_basics(p_answers)
              when p_editor = 'processional' then private.normalize_plan_processional(p_answers)
              when p_editor in ('introductions', 'speeches') then private.normalize_plan_entry_list(p_editor, p_answers)
              when p_editor = 'mc' then private.normalize_plan_mc(p_answers)
              when p_editor = 'contacts' then private.normalize_plan_contacts(p_answers)
              when p_editor = 'preferences' then private.normalize_plan_preferences(p_answers)
              when p_editor = 'music_style' then private.normalize_plan_music_style(p_answers)
              when p_editor = 'arrival' then private.normalize_plan_arrival(p_answers)
              when p_editor in ('program', 'activities', 'dedications') then private.normalize_plan_timed(p_editor, p_answers)
              when private.is_music_editor(p_editor) then private.normalize_plan_music(p_editor, p_answers)
              else private.normalize_plan_stage(p_editor, p_answers) end;
$$;


ALTER FUNCTION "private"."normalize_plan_answers"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_arrival"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  n jsonb := private.normalize_plan_stage('arrival', p_answers);
  a jsonb;
begin
  if not (n ->> 'ok')::boolean then
    return n;
  end if;
  a := n -> 'answers';
  -- Each reuse keeps only its own fields.
  if a ->> 'location_source' is distinct from 'other' then
    a := a - 'location_other';
  end if;
  if a ->> 'time_source' = 'ceremony' then
    a := a - 'start_time' - 'start_next_day' - 'end_time' - 'end_next_day';
  end if;
  if a ? 'arrival_none' and (a ?| array['location_source', 'location_other', 'location_area', 'time_source', 'start_time', 'end_time']) then
    return jsonb_build_object('ok', false, 'field', 'arrival_none',
      'message', 'Clear the location and times first, or uncheck "No separate arrival arrangements".');
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$$;


ALTER FUNCTION "private"."normalize_plan_arrival"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_basics"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  a jsonb := '{}'::jsonb;
  v jsonb;
  k text;
  s text;
  v_limit int;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('guest_count', 'start_time', 'end_time', 'venue_details', 'venue_room', 'access_notes', 'access_notes_none',
                 'announcement_language') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;

  v := p_answers -> 'guest_count';
  if v is not null and jsonb_typeof(v) <> 'null' then
    if jsonb_typeof(v) <> 'number' or (v #>> '{}') !~ '^[0-9]{1,4}$' or (v #>> '{}')::int not between 1 and 5000 then
      return jsonb_build_object('ok', false, 'field', 'guest_count', 'message', 'Enter a guest count between 1 and 5,000.');
    end if;
    a := a || jsonb_build_object('guest_count', (v #>> '{}')::int);
  end if;

  foreach k in array array['start_time', 'end_time'] loop
    v := p_answers -> k;
    if v is not null and jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'string' or (v #>> '{}') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
        return jsonb_build_object('ok', false, 'field', k, 'message', 'Enter a time such as 18:30.');
      end if;
      a := a || jsonb_build_object(k, v #>> '{}');
    end if;
  end loop;
  if a ? 'start_time' and a ? 'end_time' and a ->> 'start_time' = a ->> 'end_time' then
    return jsonb_build_object('ok', false, 'field', 'end_time', 'message', 'The end time must differ from the start time.');
  end if;

  foreach k in array array['venue_details', 'venue_room', 'access_notes'] loop
    v := p_answers -> k;
    if v is not null and jsonb_typeof(v) <> 'null' then
      if jsonb_typeof(v) <> 'string' then
        return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
      end if;
      s := btrim(v #>> '{}');
      v_limit := case k when 'venue_room' then 200 when 'venue_details' then 500 else 2000 end;
      if length(s) > v_limit then
        return jsonb_build_object('ok', false, 'field', k, 'message',
          'Keep this under ' || to_char(v_limit, 'FM9,999') || ' characters.');
      end if;
      if s <> '' then
        a := a || jsonb_build_object(k, s);
      end if;
    end if;
  end loop;

  v := p_answers -> 'access_notes_none';
  if v is not null and jsonb_typeof(v) <> 'null' then
    if jsonb_typeof(v) <> 'boolean' then
      return jsonb_build_object('ok', false, 'field', 'access_notes_none', 'message', 'Reload the page and try again.');
    end if;
    if v = 'true'::jsonb then
      if a ? 'access_notes' then
        return jsonb_build_object('ok', false, 'field', 'access_notes',
          'message', 'Describe the access details or choose "No special instructions", not both.');
      end if;
      a := a || jsonb_build_object('access_notes_none', true);
    end if;
  end if;

  v := p_answers -> 'announcement_language';
  if v is not null and jsonb_typeof(v) <> 'null' then
    if jsonb_typeof(v) <> 'string' or (v #>> '{}') not in ('french', 'english', 'bilingual', 'other') then
      return jsonb_build_object('ok', false, 'field', 'announcement_language', 'message', 'Choose a language from the list.');
    end if;
    a := a || jsonb_build_object('announcement_language', v #>> '{}');
  end if;

  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_basics"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_choices"("p_answers" "jsonb", "p_choices" "jsonb", "p_text" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := '{}'::jsonb;
  k text;
  v text;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if not (p_choices ? k or p_text ? k) then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
    if jsonb_typeof(p_answers -> k) not in ('string', 'null') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
    v := btrim(coalesce(p_answers ->> k, ''));
    continue when v = '';
    if p_choices ? k then
      if not (p_choices -> k) ? v then
        return jsonb_build_object('ok', false, 'field', k, 'message', 'Choose an option from the list.');
      end if;
    elsif length(v) > (p_text ->> k)::int then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Keep this under ' || to_char((p_text ->> k)::int, 'FM9,999') || ' characters.');
    end if;
    a := a || jsonb_build_object(k, v);
  end loop;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$$;


ALTER FUNCTION "private"."normalize_plan_choices"("p_answers" "jsonb", "p_choices" "jsonb", "p_text" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_contacts"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  a jsonb := '{}'::jsonb;
  k text;
  v text;
  v_src text;
  v_limit int;
  pe jsonb;
  e jsonb;
  v_out jsonb := '[]'::jsonb;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('day_of_source', 'day_of_client_id', 'day_of_name', 'day_of_phone', 'day_of_role', 'vendors', 'vendors_choice') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
    if k <> 'vendors' and jsonb_typeof(p_answers -> k) not in ('string', 'null') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;

  v_src := nullif(p_answers ->> 'day_of_source', '');
  if v_src is not null then
    if v_src not in ('event_contact', 'other', 'undecided') then
      return jsonb_build_object('ok', false, 'field', 'day_of_source', 'message', 'Choose an option from the list.');
    end if;
    a := a || jsonb_build_object('day_of_source', v_src);
  end if;
  if v_src = 'event_contact' and nullif(p_answers ->> 'day_of_client_id', '') is not null then
    if (p_answers ->> 'day_of_client_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('ok', false, 'field', 'day_of_client_id', 'message', 'Reload the page and try again.');
    end if;
    a := a || jsonb_build_object('day_of_client_id', p_answers ->> 'day_of_client_id');
  end if;
  v := btrim(coalesce(p_answers ->> 'day_of_phone', ''));
  if v <> '' and v_src in ('event_contact', 'other') then
    if not private.is_phone(v) then
      return jsonb_build_object('ok', false, 'field', 'day_of_phone', 'message', 'Enter a phone number with 7 to 20 digits, such as 514 555-0100.');
    end if;
    a := a || jsonb_build_object('day_of_phone', v);
  end if;
  foreach k in array array['day_of_name', 'day_of_role'] loop
    v := btrim(coalesce(p_answers ->> k, ''));
    v_limit := case k when 'day_of_name' then 200 else 120 end;
    if length(v) > v_limit then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Keep this under ' || v_limit || ' characters.');
    end if;
    if v <> '' and v_src = 'other' then
      a := a || jsonb_build_object(k, v);
    end if;
  end loop;

  pe := private.normalize_plan_entries(p_answers -> 'vendors', 30,
    '{"name":200,"business":200,"phone":30,"email":254,"notes":500}'::jsonb, '{}'::text[], array['role']);
  if not (pe ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'field', replace(pe ->> 'field', 'entries', 'vendors'), 'message', pe ->> 'message');
  end if;
  for e in select x from jsonb_array_elements(pe -> 'entries') x loop
    if jsonb_typeof(e -> 'role') is distinct from 'string'
       or (e ->> 'role') not in ('planner', 'venue', 'photographer', 'videographer', 'caterer', 'musician', 'other') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':role', 'message', 'Choose a role.');
    end if;
    if not (e ? 'name' or e ? 'business') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':name', 'message', 'Enter a person''s name or a business name.');
    end if;
    if e ? 'phone' and not private.is_phone(e ->> 'phone') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':phone', 'message', 'Enter a phone number with 7 to 20 digits, such as 514 555-0100.');
    end if;
    if e ? 'email' and not private.is_email(e ->> 'email') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':email', 'message', 'Enter an email address such as name@example.com.');
    end if;
    v_out := v_out || jsonb_build_array(e);
  end loop;
  if nullif(p_answers ->> 'vendors_choice', '') is not null then
    if p_answers ->> 'vendors_choice' <> 'none' then
      return jsonb_build_object('ok', false, 'field', 'vendors_choice', 'message', 'Choose an option from the list.');
    end if;
    if jsonb_array_length(v_out) > 0 then
      return jsonb_build_object('ok', false, 'field', 'vendors_choice',
        'message', 'Remove the vendors first, or keep them and choose "I''ll list them".');
    end if;
    a := a || jsonb_build_object('vendors_choice', 'none');
  end if;
  if jsonb_array_length(v_out) > 0 then
    a := a || jsonb_build_object('vendors', v_out);
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_contacts"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_entries"("p_list" "jsonb", "p_max" integer, "p_text" "jsonb", "p_required" "text"[], "p_other" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_out jsonb := '[]'::jsonb;
  v_ids text[] := '{}'::text[];
  e jsonb;
  o jsonb;
  k text;
  v text;
  v_id text;
begin
  if p_list is null or jsonb_typeof(p_list) = 'null' then
    return jsonb_build_object('ok', true, 'entries', '[]'::jsonb);
  end if;
  if jsonb_typeof(p_list) <> 'array' then
    return jsonb_build_object('ok', false, 'field', 'entries', 'message', 'Reload the page and try again.');
  end if;
  if jsonb_array_length(p_list) > p_max then
    return jsonb_build_object('ok', false, 'field', 'entries', 'message', 'Keep this to ' || p_max || ' entries or fewer.');
  end if;
  for e in select x from jsonb_array_elements(p_list) x loop
    if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'id') is distinct from 'string'
       or (e ->> 'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or (e ->> 'id') = any (v_ids) then
      return jsonb_build_object('ok', false, 'field', 'entries', 'message', 'Reload the page and try again.');
    end if;
    v_id := e ->> 'id';
    v_ids := v_ids || v_id;
    o := jsonb_build_object('id', v_id);
    for k in select jsonb_object_keys(e) loop
      continue when k = 'id';
      if p_text ? k then
        if jsonb_typeof(e -> k) not in ('string', 'null') then
          return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':' || k, 'message', 'Reload the page and try again.');
        end if;
        v := btrim(coalesce(e ->> k, ''));
        if length(v) > (p_text ->> k)::int then
          return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':' || k,
            'message', 'Keep this under ' || (p_text ->> k) || ' characters.');
        end if;
        if v <> '' then
          o := o || jsonb_build_object(k, v);
        end if;
      elsif k = any (p_other) then
        if jsonb_typeof(e -> k) <> 'null' then
          o := o || jsonb_build_object(k, e -> k);
        end if;
      else
        return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':' || k, 'message', 'Reload the page and try again.');
      end if;
    end loop;
    foreach k in array p_required loop
      if not o ? k then
        return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':' || k,
          'message', case k when 'speaker' then 'Enter the speaker''s name.' else 'Enter the name or names.' end);
      end if;
    end loop;
    v_out := v_out || jsonb_build_array(o);
  end loop;
  return jsonb_build_object('ok', true, 'entries', v_out);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_entries"("p_list" "jsonb", "p_max" integer, "p_text" "jsonb", "p_required" "text"[], "p_other" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_entry_list"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  pe jsonb;
  e jsonb;
  o jsonb;
  m jsonb;
  r jsonb;
  v_out jsonb := '[]'::jsonb;
  v_t text;
  a jsonb := '{}'::jsonb;
  k text;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('entries', 'choice') and not (p_editor = 'introductions' and k = 'songs') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;
  if p_editor = 'introductions' then
    -- The grand entrance's own songs, validated as moment songs (no choice of their own).
    m := private.normalize_plan_music('moment_songs', jsonb_build_object('songs', p_answers -> 'songs'));
    if not (m ->> 'ok')::boolean then
      return m;
    end if;
    pe := private.normalize_plan_entries(p_answers -> 'entries', 40,
      '{"names":300,"role":120,"pronunciation":300,"wording":500,"notes":500}'::jsonb, array['names'], array['song_id', 'music']);
    if not (pe ->> 'ok')::boolean then
      return pe;
    end if;
    -- An entry's music: a linked song, or the explicit "DJ's choice" (never both).
    -- Neither is "not decided yet"; an empty song is never read as DJ's choice.
    select x into o from jsonb_array_elements(pe -> 'entries') x
      where x ? 'music' and (x -> 'music' <> '"dj_choice"'::jsonb or x ? 'song_id') limit 1;
    if o is not null then
      return jsonb_build_object('ok', false, 'field', 'entry:' || (o ->> 'id') || ':music', 'message', 'Reload the page and try again.');
    end if;
    -- Well-formed links here; which songs they may name is checked with the
    -- plan (private.check_plan_song_links), since Entrance music is another row.
    r := private.check_song_links(pe -> 'entries',
      array(select x ->> 'song_id' from jsonb_array_elements(pe -> 'entries') x
            where x ->> 'song_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
      'Reload the page and try again.');
    if not (r ->> 'ok')::boolean then
      return r;
    end if;
    v_out := pe -> 'entries';
    if (m -> 'answers') ? 'songs' then
      a := a || jsonb_build_object('songs', m -> 'answers' -> 'songs');
    end if;
  else
    pe := private.normalize_plan_entries(p_answers -> 'entries', 30,
      '{"speaker":200,"role":120,"pronunciation":300,"cue":300,"av_notes":500,"notes":500}'::jsonb, array['speaker'],
      array['timing', 'time', 'next_day', 'duration']);
    if not (pe ->> 'ok')::boolean then
      return pe;
    end if;
    -- Timing: an exact local time (with an explicit next-day mark), a cue, or not decided.
    for e in select x from jsonb_array_elements(pe -> 'entries') x loop
      v_t := coalesce(e ->> 'timing', 'undecided');
      if jsonb_typeof(coalesce(e -> 'timing', '"undecided"'::jsonb)) <> 'string' or v_t not in ('time', 'cue', 'undecided') then
        return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':timing', 'message', 'Choose an option from the list.');
      end if;
      if e ? 'time' and (jsonb_typeof(e -> 'time') <> 'string' or (e ->> 'time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then
        return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':time', 'message', 'Enter a time such as 18:30.');
      end if;
      if e ? 'next_day' and jsonb_typeof(e -> 'next_day') <> 'boolean' then
        return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':next_day', 'message', 'Reload the page and try again.');
      end if;
      if e ? 'duration' and (jsonb_typeof(e -> 'duration') <> 'number' or (e ->> 'duration') !~ '^[0-9]{1,3}$' or (e ->> 'duration')::int not between 1 and 240) then
        return jsonb_build_object('ok', false, 'field', 'entry:' || (e ->> 'id') || ':duration', 'message', 'Enter whole minutes from 1 to 240.');
      end if;
      -- Only the chosen timing's fields are kept; a next-day mark needs its time.
      o := e - 'time' - 'next_day' - 'cue' || jsonb_build_object('timing', v_t);
      if v_t = 'time' and e ? 'time' then
        o := o || jsonb_build_object('time', e ->> 'time');
        if e -> 'next_day' = 'true'::jsonb then
          o := o || jsonb_build_object('next_day', true);
        end if;
      elsif v_t = 'cue' and e ? 'cue' then
        o := o || jsonb_build_object('cue', e ->> 'cue');
      end if;
      v_out := v_out || jsonb_build_array(o);
    end loop;
  end if;
  if p_answers ? 'choice' and jsonb_typeof(p_answers -> 'choice') <> 'null' then
    if jsonb_typeof(p_answers -> 'choice') <> 'string' or (p_answers ->> 'choice') not in ('none', 'discuss') then
      return jsonb_build_object('ok', false, 'field', 'choice', 'message', 'Choose an option from the list.');
    end if;
    if p_answers ->> 'choice' = 'none' and jsonb_array_length(v_out) > 0 then
      return jsonb_build_object('ok', false, 'field', 'choice',
        'message', 'Remove the entries first, or keep them and choose "I''ll list them".');
    end if;
    a := a || jsonb_build_object('choice', p_answers ->> 'choice');
  end if;
  if jsonb_array_length(v_out) > 0 then
    a := a || jsonb_build_object('entries', v_out);
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_entry_list"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_mc"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := '{}'::jsonb;
  k text;
  v text;
  v_limit int;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('mc', 'name', 'pronunciation', 'contact', 'notes') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
    if jsonb_typeof(p_answers -> k) not in ('string', 'null') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;
  if p_answers ? 'mc' and jsonb_typeof(p_answers -> 'mc') <> 'null' then
    -- 'none' is no longer offered; saved answers keep it.
    if (p_answers ->> 'mc') not in ('dj', 'other', 'shared', 'none', 'discuss') then
      return jsonb_build_object('ok', false, 'field', 'mc', 'message', 'Choose an option from the list.');
    end if;
    a := a || jsonb_build_object('mc', p_answers ->> 'mc');
  end if;
  foreach k in array array['name', 'pronunciation', 'contact', 'notes'] loop
    v := btrim(coalesce(p_answers ->> k, ''));
    v_limit := case k when 'name' then 200 when 'pronunciation' then 300 when 'contact' then 300 else 1000 end;
    if length(v) > v_limit then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Keep this under ' || to_char(v_limit, 'FM9,999') || ' characters.');
    end if;
    -- The other MC's details are kept only while someone else is the MC or shares the duties.
    if v <> '' and (k = 'notes' or a ->> 'mc' in ('other', 'shared')) then
      a := a || jsonb_build_object(k, v);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$$;


ALTER FUNCTION "private"."normalize_plan_mc"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_music"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_choices text[] := case p_editor
    when 'music_background' then array['dj_choice']
    when 'music_requests' then array['none']
    when 'music_exclusions' then array['none']
    when 'moment_songs' then array['dj_choice', 'not_applicable', 'discuss'] end;
  v_max int := case when p_editor = 'moment_songs' then 12 else 150 end;
  v_fields text[] := case when p_editor = 'moment_songs'
    then array['id', 'title', 'artist', 'version', 'link', 'notes', 'cue']
    else array['id', 'title', 'artist', 'version', 'link', 'notes'] end;
  -- Playlists belong to the list editors only.
  v_lists boolean := p_editor in ('music_background', 'music_requests', 'music_exclusions');
  v_songs jsonb := '[]'::jsonb;
  v_ids text[] := '{}'::text[];
  v_playlists jsonb := '[]'::jsonb;
  v_playlist_ids text[] := '{}'::text[];
  v_url_keys text[] := '{}'::text[];
  v_choice text;
  s jsonb;
  out jsonb;
  k text;
  v text;
  v_id text;
  v_limit int;
  a jsonb := '{}'::jsonb;
begin
  if v_choices is null or p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('songs', 'choice') and not (k = 'playlists' and v_lists) then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;

  if p_answers ? 'songs' and jsonb_typeof(p_answers -> 'songs') <> 'null' then
    if jsonb_typeof(p_answers -> 'songs') <> 'array' then
      return jsonb_build_object('ok', false, 'field', 'songs', 'message', 'Reload the page and try again.');
    end if;
    if jsonb_array_length(p_answers -> 'songs') > v_max then
      return jsonb_build_object('ok', false, 'field', 'songs', 'message', 'Keep this list to ' || v_max || ' songs or fewer.');
    end if;
    for s in select x from jsonb_array_elements(p_answers -> 'songs') x loop
      if jsonb_typeof(s) <> 'object' or jsonb_typeof(s -> 'id') is distinct from 'string'
         or (s ->> 'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or (s ->> 'id') = any (v_ids) then
        return jsonb_build_object('ok', false, 'field', 'songs', 'message', 'Reload the page and try again.');
      end if;
      v_id := s ->> 'id';
      v_ids := v_ids || v_id;
      out := jsonb_build_object('id', v_id);
      for k in select jsonb_object_keys(s) loop
        continue when k = 'id';
        if not (k = any (v_fields)) or jsonb_typeof(s -> k) not in ('string', 'null') then
          return jsonb_build_object('ok', false, 'field', 'song:' || v_id || ':' || k, 'message', 'Reload the page and try again.');
        end if;
        v := btrim(coalesce(s ->> k, ''));
        v_limit := case k when 'title' then 200 when 'artist' then 200 when 'version' then 100 when 'cue' then 80
                          when 'notes' then 500 when 'link' then 1000 end;
        if length(v) > v_limit then
          return jsonb_build_object('ok', false, 'field', 'song:' || v_id || ':' || k,
            'message', 'Keep this under ' || v_limit || ' characters.');
        end if;
        if k = 'link' and v <> '' and not private.is_https_url(v) then
          return jsonb_build_object('ok', false, 'field', 'song:' || v_id || ':link',
            'message', 'Enter a full https:// address, or leave the link empty.');
        end if;
        if v <> '' then
          out := out || jsonb_build_object(k, v);
        end if;
      end loop;
      if not out ? 'title' then
        return jsonb_build_object('ok', false, 'field', 'song:' || v_id || ':title', 'message', 'Enter the song title.');
      end if;
      if not out ? 'artist' then
        return jsonb_build_object('ok', false, 'field', 'song:' || v_id || ':artist', 'message', 'Enter the artist.');
      end if;
      v_songs := v_songs || jsonb_build_array(out);
    end loop;
  end if;

  if v_lists and p_answers ? 'playlists' and jsonb_typeof(p_answers -> 'playlists') <> 'null' then
    if jsonb_typeof(p_answers -> 'playlists') <> 'array' then
      return jsonb_build_object('ok', false, 'field', 'playlists', 'message', 'Reload the page and try again.');
    end if;
    if jsonb_array_length(p_answers -> 'playlists') > 5 then
      return jsonb_build_object('ok', false, 'field', 'playlists', 'message', 'Keep this to 5 playlists or fewer.');
    end if;
    for s in select x from jsonb_array_elements(p_answers -> 'playlists') x loop
      if jsonb_typeof(s) <> 'object' or jsonb_typeof(s -> 'id') is distinct from 'string'
         or (s ->> 'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or (s ->> 'id') = any (v_playlist_ids) then
        return jsonb_build_object('ok', false, 'field', 'playlists', 'message', 'Reload the page and try again.');
      end if;
      v_id := s ->> 'id';
      v_playlist_ids := v_playlist_ids || v_id;
      out := jsonb_build_object('id', v_id);
      for k in select jsonb_object_keys(s) loop
        continue when k = 'id';
        if k not in ('url', 'label', 'notes') or jsonb_typeof(s -> k) not in ('string', 'null') then
          return jsonb_build_object('ok', false, 'field', 'playlist:' || v_id || ':' || k, 'message', 'Reload the page and try again.');
        end if;
        v := btrim(coalesce(s ->> k, ''));
        v_limit := case k when 'url' then 1000 when 'label' then 100 when 'notes' then 500 end;
        if length(v) > v_limit then
          return jsonb_build_object('ok', false, 'field', 'playlist:' || v_id || ':' || k,
            'message', 'Keep this under ' || v_limit || ' characters.');
        end if;
        if k = 'url' and v <> '' and not private.is_https_url(v) then
          return jsonb_build_object('ok', false, 'field', 'playlist:' || v_id || ':url',
            'message', 'Enter the full playlist link, starting with https://.');
        end if;
        if v <> '' then
          out := out || jsonb_build_object(k, v);
        end if;
      end loop;
      if not out ? 'url' then
        return jsonb_build_object('ok', false, 'field', 'playlist:' || v_id || ':url', 'message', 'Paste the playlist link.');
      end if;
      if private.playlist_url_key(out ->> 'url') = any (v_url_keys) then
        return jsonb_build_object('ok', false, 'field', 'playlist:' || v_id || ':url', 'message', 'This playlist is already added here.');
      end if;
      v_url_keys := v_url_keys || private.playlist_url_key(out ->> 'url');
      v_playlists := v_playlists || jsonb_build_array(out);
    end loop;
  end if;

  if p_answers ? 'choice' and jsonb_typeof(p_answers -> 'choice') <> 'null' then
    v_choice := p_answers ->> 'choice';
    if jsonb_typeof(p_answers -> 'choice') <> 'string' or not (v_choice = any (v_choices)) then
      return jsonb_build_object('ok', false, 'field', 'choice', 'message', 'Choose an option from the list.');
    end if;
    -- Nothing is removed silently: an exclusive choice needs an empty list.
    if v_choice <> 'discuss' and jsonb_array_length(v_songs) > 0 then
      return jsonb_build_object('ok', false, 'field', 'choice',
        'message', case when v_lists then 'Remove the songs and playlists first, or keep them and choose to add songs or playlists.'
                        else 'Remove the songs first, or keep them and choose "I''ll list the songs".' end);
    end if;
    if v_choice <> 'discuss' and jsonb_array_length(v_playlists) > 0 then
      return jsonb_build_object('ok', false, 'field', 'choice',
        'message', 'Remove the songs and playlists first, or keep them and choose to add songs or playlists.');
    end if;
    a := a || jsonb_build_object('choice', v_choice);
  end if;
  if jsonb_array_length(v_songs) > 0 then
    a := a || jsonb_build_object('songs', v_songs);
  end if;
  if jsonb_array_length(v_playlists) > 0 then
    a := a || jsonb_build_object('playlists', v_playlists);
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_music"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_music_style"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  r jsonb;
  g jsonb := '[]'::jsonb;
  x jsonb;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  r := private.normalize_plan_choices(p_answers - 'genres',
    '{"style_choice":["dj_choice"],"slow_songs":["dj_choice","none","a_few","discuss"]}'::jsonb,
    '{"other_style":300,"favorite_artists":500,"dance_floor":1000}'::jsonb);
  if not (r ->> 'ok')::boolean then
    return r;
  end if;
  if p_answers ? 'genres' and jsonb_typeof(p_answers -> 'genres') <> 'null' then
    if jsonb_typeof(p_answers -> 'genres') <> 'array' then
      return jsonb_build_object('ok', false, 'field', 'genres', 'message', 'Reload the page and try again.');
    end if;
    -- Kept in the list's own order, once each.
    for x in select to_jsonb(v) from unnest(array['pop', 'dance', 'hiphop_rnb', 'rock', 'disco_funk', 'country', 'latin', 'house_electronic', 'throwbacks']) v loop
      if p_answers -> 'genres' @> jsonb_build_array(x) then
        g := g || jsonb_build_array(x);
      end if;
    end loop;
    if exists (select 1 from jsonb_array_elements(p_answers -> 'genres') e
               where not (jsonb_typeof(e) = 'string' and (e #>> '{}') in ('pop', 'dance', 'hiphop_rnb', 'rock', 'disco_funk', 'country', 'latin', 'house_electronic', 'throwbacks'))) then
      return jsonb_build_object('ok', false, 'field', 'genres', 'message', 'Choose styles from the list.');
    end if;
  end if;
  if r -> 'answers' ->> 'style_choice' = 'dj_choice' and (jsonb_array_length(g) > 0 or r -> 'answers' ? 'other_style') then
    return jsonb_build_object('ok', false, 'field', 'style_choice',
      'message', 'Clear the styles first, or keep them and choose "I''ll pick styles".');
  end if;
  return jsonb_build_object('ok', true, 'answers', r -> 'answers' || case when jsonb_array_length(g) > 0 then jsonb_build_object('genres', g) else '{}'::jsonb end);
end;
$$;


ALTER FUNCTION "private"."normalize_plan_music_style"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_preferences"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select private.normalize_plan_choices(p_answers,
    '{"interaction":["music_mostly","a_little","interactive","occasional","discuss"],"lyrics":["clean","explicit_ok","discuss"],"requests":["welcome","not_welcome","discuss"]}'::jsonb,
    '{"atmosphere":1000,"notes":1000}'::jsonb);
$$;


ALTER FUNCTION "private"."normalize_plan_preferences"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_processional"("p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  m jsonb;
  pe jsonb;
  r jsonb;
  a jsonb;
  k text;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if k not in ('songs', 'choice', 'participants', 'participants_choice') then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;
  m := private.normalize_plan_music('moment_songs', p_answers - 'participants' - 'participants_choice');
  if not (m ->> 'ok')::boolean then
    return m;
  end if;
  a := m -> 'answers';
  pe := private.normalize_plan_entries(p_answers -> 'participants', 30,
    '{"names":300,"role":120,"pronunciation":300,"notes":500}'::jsonb, array['names'], array['song_id']);
  if not (pe ->> 'ok')::boolean then
    return pe;
  end if;
  -- Well-formed links here; which songs they may name is checked with the
  -- plan (private.check_plan_song_links), since Couple entrance is another row.
  r := private.check_song_links(pe -> 'entries',
    array(select e ->> 'song_id' from jsonb_array_elements(pe -> 'entries') e
          where e ->> 'song_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
    'Reload the page and try again.');
  if not (r ->> 'ok')::boolean then
    return r;
  end if;
  if jsonb_array_length(pe -> 'entries') > 0 then
    if a ->> 'choice' = 'not_applicable' then
      return jsonb_build_object('ok', false, 'field', 'choice',
        'message', 'Remove the people walking in first, or keep them and choose "I''ll list the songs".');
    end if;
    a := a || jsonb_build_object('participants', pe -> 'entries');
  end if;
  if p_answers ? 'participants_choice' and jsonb_typeof(p_answers -> 'participants_choice') <> 'null' then
    if p_answers -> 'participants_choice' <> '"discuss"'::jsonb then
      return jsonb_build_object('ok', false, 'field', 'participants_choice', 'message', 'Choose an option from the list.');
    end if;
    a := a || jsonb_build_object('participants_choice', 'discuss');
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_processional"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_stage"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  a jsonb := '{}'::jsonb;
  f record;
  v jsonb;
  s text;
  k text;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if not exists (select 1 from private.planning_editor_fields() x where x.editor = p_editor and x.field = k) then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;
  for f in select * from private.planning_editor_fields() x where x.editor = p_editor loop
    v := p_answers -> f.field;
    continue when v is null or jsonb_typeof(v) = 'null';
    if f.kind = 'text' then
      if jsonb_typeof(v) <> 'string' then
        return jsonb_build_object('ok', false, 'field', f.field, 'message', 'Reload the page and try again.');
      end if;
      s := btrim(v #>> '{}');
      if length(s) > f.max_value then
        return jsonb_build_object('ok', false, 'field', f.field, 'message', 'Keep this under ' || to_char(f.max_value, 'FM9,999') || ' characters.');
      end if;
      if s <> '' then
        a := a || jsonb_build_object(f.field, s);
      end if;
    elsif f.kind = 'choice' then
      if jsonb_typeof(v) <> 'string' or not ((v #>> '{}') = any (f.choices)) then
        return jsonb_build_object('ok', false, 'field', f.field, 'message', 'Choose an option from the list.');
      end if;
      a := a || jsonb_build_object(f.field, v #>> '{}');
    elsif f.kind = 'time' then
      if jsonb_typeof(v) <> 'string' or (v #>> '{}') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
        return jsonb_build_object('ok', false, 'field', f.field, 'message', 'Enter a time such as 18:30.');
      end if;
      a := a || jsonb_build_object(f.field, v #>> '{}');
    elsif f.kind in ('flag', 'next_day') then
      if jsonb_typeof(v) <> 'boolean' then
        return jsonb_build_object('ok', false, 'field', f.field, 'message', 'Reload the page and try again.');
      end if;
      if v = 'true'::jsonb then
        a := a || jsonb_build_object(f.field, true);
      end if;
    elsif f.kind = 'int' then
      if jsonb_typeof(v) <> 'number' or (v #>> '{}') !~ '^[0-9]{1,4}$' or (v #>> '{}')::int not between f.min_value and f.max_value then
        return jsonb_build_object('ok', false, 'field', f.field,
          'message', 'Enter a whole number from ' || f.min_value || ' to ' || to_char(f.max_value, 'FM9,999') || '.');
      end if;
      a := a || jsonb_build_object(f.field, (v #>> '{}')::int);
    end if;
  end loop;
  -- A next-day mark means nothing without its time.
  for f in select * from private.planning_editor_fields() x where x.editor = p_editor and x.kind = 'next_day' loop
    if a ? f.field and not a ? replace(f.field, '_next_day', '_time') then
      a := a - f.field;
    end if;
  end loop;
  -- Within a stage the end comes after the start; after midnight is explicit.
  if a ? 'start_time' and a ? 'end_time' and private.plan_minutes(a, 'end') <= private.plan_minutes(a, 'start') then
    return jsonb_build_object('ok', false, 'field', 'end_time',
      'message', 'The end must be after the start. If it ends after midnight, check "Next day".');
  end if;
  -- The grand entrance decision replaces the older "No formal entrance" mark;
  -- the two are never stored together. A time kept beside "none" or
  -- "undecided" is a hidden earlier answer, preserved for switching back.
  if a ? 'grand_entrance' and a ? 'entrance_none' then
    return jsonb_build_object('ok', false, 'field', 'grand_entrance', 'message', 'Reload the page and try again.');
  end if;
  if a ? 'entrance_none' and a ? 'entrance_time' then
    return jsonb_build_object('ok', false, 'field', 'entrance_time',
      'message', 'Remove the entrance time or uncheck "No formal entrance", not both.');
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_stage"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."normalize_plan_timed"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_text jsonb := case p_editor
    when 'program' then '{"title":200,"presenter":200,"pronunciation":300,"notes":500,"cue":300}'
    when 'activities' then '{"name":200,"host":200,"participants":300,"pronunciation":300,"notes":500,"cue":300,"song_title":200,"song_artist":200,"song_version":100,"song_link":1000}'
    else '{"recipient":200,"relationship":120,"pronunciation":300,"message":1000,"notes":500,"cue":300,"song_title":200,"song_artist":200,"song_version":100,"song_link":1000}' end::jsonb;
  v_required text := case p_editor when 'program' then 'title' when 'activities' then 'name' else 'recipient' end;
  v_timings text[] := case when p_editor = 'dedications' then array['anytime', 'time', 'cue', 'undecided'] else array['time', 'cue', 'undecided'] end;
  v_extra text[] := case when p_editor = 'dedications' then array['timing', 'time', 'next_day'] else array['timing', 'time', 'next_day', 'duration'] end;
  v_top text[] := case when p_editor = 'program' then array['entries', 'choice', 'start_time', 'start_next_day', 'end_time', 'end_next_day', 'host', 'host_pronunciation', 'notes']
                       else array['entries', 'choice'] end;
  pe jsonb;
  st jsonb;
  e jsonb;
  o jsonb;
  t text;
  v_id text;
  v_out jsonb := '[]'::jsonb;
  a jsonb := '{}'::jsonb;
  k text;
begin
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' then
    return jsonb_build_object('ok', false, 'field', null, 'message', 'Reload the page and try again.');
  end if;
  for k in select jsonb_object_keys(p_answers) loop
    if not (k = any (v_top)) then
      return jsonb_build_object('ok', false, 'field', k, 'message', 'Reload the page and try again.');
    end if;
  end loop;
  if p_editor = 'program' then
    -- The program's own times and host, validated like stage details.
    st := private.normalize_plan_stage('program', p_answers - 'entries' - 'choice');
    if not (st ->> 'ok')::boolean then
      return st;
    end if;
    a := st -> 'answers';
  end if;
  pe := private.normalize_plan_entries(p_answers -> 'entries', 40, v_text, array[v_required], v_extra);
  if not (pe ->> 'ok')::boolean then
    return pe;
  end if;
  for e in select x from jsonb_array_elements(pe -> 'entries') x loop
    v_id := e ->> 'id';
    t := coalesce(e ->> 'timing', 'undecided');
    if jsonb_typeof(coalesce(e -> 'timing', '"undecided"'::jsonb)) <> 'string' or not (t = any (v_timings)) then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':timing', 'message', 'Choose an option from the list.');
    end if;
    if e ? 'time' and (jsonb_typeof(e -> 'time') <> 'string' or (e ->> 'time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':time', 'message', 'Enter a time such as 18:30.');
    end if;
    if e ? 'next_day' and jsonb_typeof(e -> 'next_day') <> 'boolean' then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':next_day', 'message', 'Reload the page and try again.');
    end if;
    if e ? 'duration' and (jsonb_typeof(e -> 'duration') <> 'number' or (e ->> 'duration') !~ '^[0-9]{1,3}$' or (e ->> 'duration')::int not between 1 and 240) then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':duration', 'message', 'Enter whole minutes from 1 to 240.');
    end if;
    if (e ? 'song_title' or e ? 'song_artist' or e ? 'song_version' or e ? 'song_link') and not (e ? 'song_title' and e ? 'song_artist') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':' || case when e ? 'song_title' then 'song_artist' else 'song_title' end,
        'message', 'Enter the song''s title and artist, or clear the song.');
    end if;
    if e ? 'song_link' and not private.is_https_url(e ->> 'song_link') then
      return jsonb_build_object('ok', false, 'field', 'entry:' || v_id || ':song_link', 'message', 'Enter a full https:// address, or leave the link empty.');
    end if;
    -- Only the chosen timing's fields are kept; a next-day mark needs its time.
    o := e - 'time' - 'next_day' - 'cue' || jsonb_build_object('timing', t);
    if t = 'time' and e ? 'time' then
      o := o || jsonb_build_object('time', e ->> 'time');
      if e -> 'next_day' = 'true'::jsonb then
        o := o || jsonb_build_object('next_day', true);
      end if;
    elsif t = 'cue' and e ? 'cue' then
      o := o || jsonb_build_object('cue', e ->> 'cue');
    end if;
    v_out := v_out || jsonb_build_array(o);
  end loop;
  if p_answers ? 'choice' and jsonb_typeof(p_answers -> 'choice') <> 'null' then
    if jsonb_typeof(p_answers -> 'choice') <> 'string' or (p_answers ->> 'choice') not in ('none', 'discuss') then
      return jsonb_build_object('ok', false, 'field', 'choice', 'message', 'Choose an option from the list.');
    end if;
    if p_answers ->> 'choice' = 'none' and jsonb_array_length(v_out) > 0 then
      return jsonb_build_object('ok', false, 'field', 'choice',
        'message', 'Remove the entries first, or keep them and choose "I''ll list them".');
    end if;
    a := a || jsonb_build_object('choice', p_answers ->> 'choice');
  end if;
  if jsonb_array_length(v_out) > 0 then
    a := a || jsonb_build_object('entries', v_out);
  end if;
  return jsonb_build_object('ok', true, 'answers', a);
end;
$_$;


ALTER FUNCTION "private"."normalize_plan_timed"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."offer_discount_cents"("p_offer" "jsonb", "p_subtotal" bigint) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_offer -> 'discount' is null or jsonb_typeof(p_offer -> 'discount') = 'null' then 0
    when p_offer -> 'discount' ->> 'type' = 'percent'
      then (p_subtotal * (p_offer -> 'discount' ->> 'percent_basis_points')::bigint + 5000) / 10000
    else least((p_offer -> 'discount' ->> 'amount_cents')::bigint, p_subtotal)
  end;
$$;


