CREATE OR REPLACE FUNCTION "private"."offer_min_subtotal"("p_offer" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_lowest bigint;
  v_combinations numeric := 1;
  v_count int;
  v_min bigint;
begin
  select min((p ->> 'base_price_cents')::bigint) into v_lowest from jsonb_array_elements(p_offer -> 'packages') p;

  for v_count in
    select case q ->> 'answer_type' when 'boolean' then 2 else jsonb_array_length(q -> 'options') end
    from jsonb_array_elements(p_offer -> 'questions') q
    where (q ->> 'required')::boolean and q ->> 'answer_type' in ('boolean', 'single_choice')
      and exists (select 1 from jsonb_array_elements(p_offer -> 'rules') r where r ->> 'question_key' = q ->> 'key')
  loop
    v_combinations := v_combinations * v_count;
  end loop;
  if v_combinations > 4096 then
    return v_lowest;
  end if;

  with recursive varying as (
    select row_number() over (order by x.ord) as i, q ->> 'key' as key,
           case q ->> 'answer_type' when 'boolean' then '[true, false]'::jsonb
                else (select jsonb_agg(o -> 'value') from jsonb_array_elements(q -> 'options') o) end as vals
    from jsonb_array_elements(p_offer -> 'questions') with ordinality as x(q, ord)
    where (q ->> 'required')::boolean and q ->> 'answer_type' in ('boolean', 'single_choice')
      and exists (select 1 from jsonb_array_elements(p_offer -> 'rules') r where r ->> 'question_key' = q ->> 'key')
  ),
  combos(i, answers) as (
    select 0::bigint, '{}'::jsonb
    union all
    select c.i + 1, c.answers || jsonb_build_object(v.key, val.value)
    from combos c
    join varying v on v.i = c.i + 1
    cross join jsonb_array_elements(v.vals) as val(value)
  ),
  complete as (
    select c.answers from combos c where c.i = (select count(*) from varying)
  ),
  -- Gear the answers require (rules of the same gear add up), per combination.
  required as (
    select c.answers, r ->> 'gear_key' as gear, sum((r ->> 'required_quantity')::bigint) as qty
    from complete c
    cross join jsonb_array_elements(p_offer -> 'rules') r
    where c.answers ? (r ->> 'question_key')
      and case r -> 'condition' ->> 'op'
            when 'equals' then (c.answers -> (r ->> 'question_key')) = (r -> 'condition' -> 'value')
            when 'in' then (r -> 'condition' -> 'values') @> jsonb_build_array(c.answers -> (r ->> 'question_key'))
            else false
          end
    group by c.answers, r ->> 'gear_key'
  ),
  subtotals as (
    select (pk ->> 'base_price_cents')::bigint + coalesce((
             select sum(greatest(0, rq.qty - coalesce((
                          select (inc ->> 'quantity')::bigint from jsonb_array_elements(pk -> 'included') inc
                          where inc ->> 'gear_key' = rq.gear), 0))
                        * (p_offer -> 'gear' -> rq.gear ->> 'unit_price_cents')::bigint)
             from required rq where rq.answers = c.answers), 0) as subtotal
    from complete c
    cross join jsonb_array_elements(p_offer -> 'packages') pk
  )
  select min(s.subtotal) into v_min from subtotals s;
  return coalesce(v_min, v_lowest);
end;
$$;


ALTER FUNCTION "private"."offer_min_subtotal"("p_offer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."one_way_revocation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'revocation cannot be undone or changed' using errcode = 'check_violation';
  end if;
  if old.revoked_at is null and new.revoked_at is not null then
    new.revoked_at := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."one_way_revocation"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."staff_invitations" (
    "id" "uuid" NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "role" "text" DEFAULT 'staff'::"text" NOT NULL,
    "link_id" "uuid" NOT NULL,
    "token_hash" "text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "send_count" integer DEFAULT 1 NOT NULL,
    "last_sent_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "invited_by" "uuid" NOT NULL,
    "revoked_at" timestamp with time zone,
    "revoked_by" "uuid",
    "accepted_at" timestamp with time zone,
    "accepted_by" "uuid",
    "membership_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "staff_invitations_accepted_complete" CHECK (((("accepted_at" IS NULL) AND ("accepted_by" IS NULL) AND ("membership_id" IS NULL)) OR (("accepted_at" IS NOT NULL) AND ("accepted_by" IS NOT NULL) AND ("membership_id" IS NOT NULL)))),
    CONSTRAINT "staff_invitations_email_valid" CHECK ("private"."is_valid_email"("email")),
    CONSTRAINT "staff_invitations_one_outcome" CHECK ((("revoked_at" IS NULL) OR ("accepted_at" IS NULL))),
    CONSTRAINT "staff_invitations_revoked_complete" CHECK ((("revoked_at" IS NULL) = ("revoked_by" IS NULL))),
    CONSTRAINT "staff_invitations_role_staff" CHECK (("role" = 'staff'::"text")),
    CONSTRAINT "staff_invitations_send_count_positive" CHECK (("send_count" >= 1)),
    CONSTRAINT "staff_invitations_token_hash_format" CHECK (("token_hash" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."staff_invitations" OWNER TO "postgres";


COMMENT ON TABLE "public"."staff_invitations" IS 'Invitations to join a business as staff. Only the SHA-256 of the emailed token is stored. Accepting creates or restores one staff membership.';



CREATE OR REPLACE FUNCTION "private"."open_staff_invitation"("p_token_hash" "text") RETURNS "public"."staff_invitations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.* from public.staff_invitations i join public.tenants t on t.id = i.tenant_id
  where i.token_hash = p_token_hash and i.accepted_at is null and i.revoked_at is null and i.expires_at > now()
    and t.archived_at is null and t.suspended_at is null;
$$;


