CREATE OR REPLACE FUNCTION "private"."parse_gear_media_path"("object_name" "text") RETURNS TABLE("tenant_id" "uuid", "gear_item_id" "uuid")
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select m[1]::uuid, m[2]::uuid
  from (
    select regexp_match(
      object_name,
      '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})'
      '/gear-items/'
      '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})'
      '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
      '\.(jpg|jpeg|png|webp|avif|mp4|webm)$'
    ) as m
  ) parsed
  where m is not null;
$_$;


