       where i.tenant_id = p_plan.tenant_id and i.plan_id = p_plan.id
         and i.key <> 'basics' and i.disabled_at is null
     );
$$;


ALTER FUNCTION "private"."plan_awaiting_setup"("p_plan" "public"."event_plans") OWNER TO "postgres";


COMMENT ON FUNCTION "private"."plan_awaiting_setup"("p_plan" "public"."event_plans") IS 'Booking (or backfill) set the plan up with Event basics only and staff have not configured it: clients see "setting up" and cannot save.';



CREATE OR REPLACE FUNCTION "private"."plan_basics_requirements"("p_answers" "jsonb", "p_event_venue_name" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(
    jsonb_build_object('key', 'guest_count', 'state', case when a ? 'guest_count' then 'answered' else 'unanswered' end),
    jsonb_build_object('key', 'start_time', 'state', case when a ? 'start_time' then 'answered' else 'unanswered' end),
    jsonb_build_object('key', 'end_time', 'state', case when a ? 'end_time' then 'answered' else 'unanswered' end),
    jsonb_build_object('key', 'venue', 'state', case when p_event_venue_name is not null then 'imported'
                                                     when a ? 'venue_details' then 'answered' else 'unanswered' end),
    jsonb_build_object('key', 'access', 'state', case when a ? 'access_notes' then 'answered'
                                                      when a ? 'access_notes_none' then 'not_applicable' else 'unanswered' end))
  from (select coalesce(p_answers, '{}'::jsonb) as a) x;
$$;


ALTER FUNCTION "private"."plan_basics_requirements"("p_answers" "jsonb", "p_event_venue_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_client_editing"("p_event" "public"."events", "p_plan" "public"."event_plans", "p_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_deadline timestamptz := private.plan_deadline(p_event, p_plan);
  v_override timestamptz := case when p_event.planning_override_until > p_at then p_event.planning_override_until end;
  v_state text := private.plan_editing_state(v_deadline, p_event.planning_override_until, p_at, p_event.planning_client_closed_at);
begin
  return jsonb_build_object(
    'state', v_state,
    'deadline', v_deadline,
    'closes_at', case when v_state = 'closed' then null else greatest(v_deadline, v_override) end,
    'closed_by_dj', p_event.planning_client_closed_at is not null,
    'timezone', p_event.timezone);
end;
$$;


ALTER FUNCTION "private"."plan_client_editing"("p_event" "public"."events", "p_plan" "public"."event_plans", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_contacts_requirements"("p_plan_id" "uuid", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := coalesce(p_answers, '{}'::jsonb);
  v_contact jsonb;
  v_day jsonb;
begin
  if a ->> 'day_of_source' = 'event_contact' then
    select c into v_contact from jsonb_array_elements(private.plan_event_contacts(p_plan_id)) c where c ->> 'id' = a ->> 'day_of_client_id';
    v_day := case
      when v_contact is null and a ? 'day_of_client_id' then jsonb_build_object('key', 'day_of', 'state', 'unanswered', 'note', 'contact_unavailable')
      when v_contact is null then jsonb_build_object('key', 'day_of', 'state', 'unanswered')
      when a ? 'day_of_phone' or nullif(btrim(coalesce(v_contact ->> 'phone', '')), '') is not null then jsonb_build_object('key', 'day_of', 'state', 'answered')
      else jsonb_build_object('key', 'day_of', 'state', 'unanswered', 'note', 'phone_missing') end;
  elsif a ->> 'day_of_source' = 'other' then
    v_day := case
      when a ? 'day_of_name' and a ? 'day_of_phone' then jsonb_build_object('key', 'day_of', 'state', 'answered')
      when a ? 'day_of_name' then jsonb_build_object('key', 'day_of', 'state', 'unanswered', 'note', 'phone_missing')
      else jsonb_build_object('key', 'day_of', 'state', 'unanswered') end;
  elsif a ->> 'day_of_source' = 'undecided' then
    v_day := jsonb_build_object('key', 'day_of', 'state', 'unanswered', 'note', 'not_decided');
  else
    v_day := jsonb_build_object('key', 'day_of', 'state', 'unanswered');
  end if;
  return jsonb_build_array(v_day, case
    when jsonb_array_length(coalesce(a -> 'vendors', '[]'::jsonb)) > 0 then jsonb_build_object('key', 'vendors', 'state', 'answered')
    when a ->> 'vendors_choice' = 'none' then jsonb_build_object('key', 'vendors', 'state', 'not_applicable')
    else jsonb_build_object('key', 'vendors', 'state', 'unanswered') end);
end;
$$;


ALTER FUNCTION "private"."plan_contacts_requirements"("p_plan_id" "uuid", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_deadline"("p_event" "public"."events", "p_plan" "public"."event_plans") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(p_event.planning_lock_at,
                  private.planning_cutoff_at(p_event.event_date, p_event.timezone, coalesce(p_plan.client_cutoff_days, 14)));
$$;


ALTER FUNCTION "private"."plan_deadline"("p_event" "public"."events", "p_plan" "public"."event_plans") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_editing_state"("p_deadline" timestamp with time zone, "p_override" timestamp with time zone, "p_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_at < p_deadline then 'open'
              when p_override is not null and p_at < p_override then 'reopened'
              else 'closed' end;
$$;


ALTER FUNCTION "private"."plan_editing_state"("p_deadline" timestamp with time zone, "p_override" timestamp with time zone, "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_editing_state"("p_deadline" timestamp with time zone, "p_override" timestamp with time zone, "p_at" timestamp with time zone, "p_closed_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_closed_at is not null then 'closed'
              else private.plan_editing_state(p_deadline, p_override, p_at) end;
$$;


ALTER FUNCTION "private"."plan_editing_state"("p_deadline" timestamp with time zone, "p_override" timestamp with time zone, "p_at" timestamp with time zone, "p_closed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_event_contacts"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'phone', c.phone, 'primary', ec.is_primary)
                            order by ec.is_primary desc, c.name, c.id), '[]'::jsonb)
  from public.event_plans p
  join public.event_clients ec on ec.tenant_id = p.tenant_id and ec.event_id = p.event_id
  join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
  where p.id = p_plan_id and c.archived_at is null;
$$;


ALTER FUNCTION "private"."plan_event_contacts"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_grand_entrance"("p_answers" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_answers ->> 'grand_entrance' in ('planned', 'none', 'undecided') then p_answers ->> 'grand_entrance'
    when p_answers -> 'entrance_none' = 'true'::jsonb then 'none'
    when p_answers ? 'entrance_time' then 'planned'
  end;
$$;


ALTER FUNCTION "private"."plan_grand_entrance"("p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_latest_import"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('captured_at', i.captured_at, 'questions', i.questions, 'answers', i.answers)
  from public.event_plan_imports i where i.plan_id = p_plan_id
  order by i.captured_at desc limit 1;
$$;


ALTER FUNCTION "private"."plan_latest_import"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_minutes"("p_answers" "jsonb", "p_prefix" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when p_answers ->> (p_prefix || '_time') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    split_part(p_answers ->> (p_prefix || '_time'), ':', 1)::int * 60 + split_part(p_answers ->> (p_prefix || '_time'), ':', 2)::int
    + case when p_answers -> (p_prefix || '_next_day') = 'true'::jsonb then 1440 else 0 end
  end;
$_$;


ALTER FUNCTION "private"."plan_minutes"("p_answers" "jsonb", "p_prefix" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_moment_answers"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(i.id, jsonb_build_object('answers', coalesce(r.answers, '{}'::jsonb), 'revision', coalesce(r.revision, 0))), '{}'::jsonb)
  from public.event_plan_items i
  join private.planning_library() l on l.key = i.key
  left join public.event_plan_items p on p.tenant_id = i.tenant_id and p.plan_id = i.plan_id and p.id = i.parent_id
  left join public.event_plan_responses r on r.tenant_id = i.tenant_id and r.item_id = i.id
  where i.plan_id = p_plan_id and i.disabled_at is null and (p.id is null or p.disabled_at is null)
    and private.is_moment_editor(l.editor);
$$;


ALTER FUNCTION "private"."plan_moment_answers"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_moment_requirements"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with input as (select coalesce(p_answers, '{}'::jsonb) as a)
  select case p_editor
    when 'music_style' then jsonb_build_array(
      case when a ->> 'style_choice' = 'dj_choice' or jsonb_array_length(coalesce(a -> 'genres', '[]'::jsonb)) > 0 or a ? 'other_style'
           then jsonb_build_object('key', 'style', 'state', 'answered')
           else jsonb_build_object('key', 'style', 'state', 'unanswered') end,
      case when a ->> 'slow_songs' = 'discuss' then jsonb_build_object('key', 'slow_songs', 'state', 'unanswered', 'discuss', true)
           when a ? 'slow_songs' then jsonb_build_object('key', 'slow_songs', 'state', 'answered')
           else jsonb_build_object('key', 'slow_songs', 'state', 'unanswered') end)
    when 'program' then private.plan_timed_requirements('program', a, false)
    when 'activities' then private.plan_timed_requirements('activities', a, false)
    when 'dedications' then private.plan_timed_requirements('dedications', a, true)
    else private.plan_people_requirements(p_editor, a) end
  from input;
$$;


ALTER FUNCTION "private"."plan_moment_requirements"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_music"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(i.id, jsonb_build_object('answers', coalesce(r.answers, '{}'::jsonb), 'revision', coalesce(r.revision, 0))), '{}'::jsonb)
  from public.event_plan_items i
  join private.planning_library() l on l.key = i.key
  left join public.event_plan_items p on p.tenant_id = i.tenant_id and p.plan_id = i.plan_id and p.id = i.parent_id
  left join public.event_plan_responses r on r.tenant_id = i.tenant_id and r.item_id = i.id
  where i.plan_id = p_plan_id and i.disabled_at is null and (p.id is null or p.disabled_at is null)
    and (private.is_music_editor(l.editor) or l.editor = 'processional');
$$;


ALTER FUNCTION "private"."plan_music"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_music_requirements"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(case
    when coalesce(p_answers, '{}'::jsonb) ->> 'choice' = 'discuss' then jsonb_build_object('key', 'songs', 'state', 'unanswered', 'discuss', true)
    when jsonb_array_length(coalesce(p_answers -> 'songs', '[]'::jsonb)) > 0 then jsonb_build_object('key', 'songs', 'state', 'answered')
    -- Only list editors can hold playlists (normalize_plan_music).
    when p_editor in ('music_background', 'music_requests', 'music_exclusions')
         and jsonb_typeof(p_answers -> 'playlists') = 'array' and jsonb_array_length(p_answers -> 'playlists') > 0
      then jsonb_build_object('key', 'songs', 'state', 'answered')
    when p_answers ->> 'choice' in ('dj_choice', 'none') then jsonb_build_object('key', 'songs', 'state', 'answered')
    when p_answers ->> 'choice' = 'not_applicable' then jsonb_build_object('key', 'songs', 'state', 'not_applicable')
    else jsonb_build_object('key', 'songs', 'state', 'unanswered') end);
$$;


ALTER FUNCTION "private"."plan_music_requirements"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_people_requirements"("p_editor" "text", "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with input as (select coalesce(p_answers, '{}'::jsonb) as a)
  select case p_editor
    when 'processional' then private.plan_music_requirements('moment_songs', a) || jsonb_build_array(case
      when a ->> 'participants_choice' = 'discuss' then jsonb_build_object('key', 'participants', 'state', 'unanswered', 'discuss', true)
      when jsonb_array_length(coalesce(a -> 'participants', '[]'::jsonb)) > 0 then jsonb_build_object('key', 'participants', 'state', 'answered')
      when a ->> 'choice' = 'not_applicable' then jsonb_build_object('key', 'participants', 'state', 'not_applicable')
      else jsonb_build_object('key', 'participants', 'state', 'unanswered') end)
    when 'mc' then jsonb_build_array(case a ->> 'mc'
      when 'dj' then jsonb_build_object('key', 'mc', 'state', 'answered')
      when 'other' then jsonb_build_object('key', 'mc', 'state', case when a ? 'name' then 'answered' else 'unanswered' end)
      when 'shared' then jsonb_build_object('key', 'mc', 'state', case when a ? 'name' then 'answered' else 'unanswered' end)
      when 'none' then jsonb_build_object('key', 'mc', 'state', 'not_applicable')
      when 'discuss' then jsonb_build_object('key', 'mc', 'state', 'unanswered', 'discuss', true)
      else jsonb_build_object('key', 'mc', 'state', 'unanswered') end)
    when 'introductions' then jsonb_build_array(case
      when a ->> 'choice' = 'discuss' then jsonb_build_object('key', 'introductions', 'state', 'unanswered', 'discuss', true)
      when jsonb_array_length(coalesce(a -> 'entries', '[]'::jsonb)) > 0 then jsonb_build_object('key', 'introductions', 'state', 'answered')
      when a ->> 'choice' = 'none' then jsonb_build_object('key', 'introductions', 'state', 'not_applicable')
      else jsonb_build_object('key', 'introductions', 'state', 'unanswered') end)
      -- Everyone introduced needs their music decided: a song, or the DJ's choice.
      || case when jsonb_array_length(coalesce(a -> 'entries', '[]'::jsonb)) = 0 then '[]'::jsonb
              when exists (select 1 from jsonb_array_elements(a -> 'entries') e where not (e ? 'song_id' or e -> 'music' is not distinct from '"dj_choice"'::jsonb))
                then jsonb_build_array(jsonb_build_object('key', 'entry_music', 'state', 'unanswered', 'note', 'music_open'))
              else jsonb_build_array(jsonb_build_object('key', 'entry_music', 'state', 'answered')) end
    when 'speeches' then jsonb_build_array(case
      when a ->> 'choice' = 'discuss' then jsonb_build_object('key', 'speeches', 'state', 'unanswered', 'discuss', true)
      when jsonb_array_length(coalesce(a -> 'entries', '[]'::jsonb)) > 0 then
        case when exists (select 1 from jsonb_array_elements(a -> 'entries') e
                          where not ((e ->> 'timing' = 'time' and e ? 'time') or (e ->> 'timing' = 'cue' and e ? 'cue')))
             then jsonb_build_object('key', 'speeches', 'state', 'unanswered', 'note', 'timing_open')
             else jsonb_build_object('key', 'speeches', 'state', 'answered') end
      when a ->> 'choice' = 'none' then jsonb_build_object('key', 'speeches', 'state', 'not_applicable')
      else jsonb_build_object('key', 'speeches', 'state', 'unanswered') end)
  end
  from input;
$$;


ALTER FUNCTION "private"."plan_people_requirements"("p_editor" "text", "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_preferences_requirements"("p_answers" "jsonb", "p_basics" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with input as (select coalesce(p_answers, '{}'::jsonb) as a)
  select jsonb_build_array(
    case when a ->> 'interaction' = 'discuss' then jsonb_build_object('key', 'interaction', 'state', 'unanswered', 'discuss', true)
         when a ? 'interaction' then jsonb_build_object('key', 'interaction', 'state', 'answered')
         else jsonb_build_object('key', 'interaction', 'state', 'unanswered') end,
    case when coalesce(p_basics, '{}'::jsonb) ? 'announcement_language' then jsonb_build_object('key', 'language', 'state', 'answered')
         else jsonb_build_object('key', 'language', 'state', 'unanswered', 'note', 'basics_missing') end,
    case when a ->> 'lyrics' = 'discuss' then jsonb_build_object('key', 'lyrics', 'state', 'unanswered', 'discuss', true)
         when a ? 'lyrics' then jsonb_build_object('key', 'lyrics', 'state', 'answered')
         else jsonb_build_object('key', 'lyrics', 'state', 'unanswered') end,
    case when a ->> 'requests' = 'discuss' then jsonb_build_object('key', 'requests', 'state', 'unanswered', 'discuss', true)
         when a ? 'requests' then jsonb_build_object('key', 'requests', 'state', 'answered')
         else jsonb_build_object('key', 'requests', 'state', 'unanswered') end)
  from input;
$$;


ALTER FUNCTION "private"."plan_preferences_requirements"("p_answers" "jsonb", "p_basics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_progress"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_plan public.event_plans%rowtype;
  v_venue text;
  v_basics jsonb;
  v_venue_known boolean;
  v_ceremony jsonb;
  v_entrance text;
  v_entrance_saved boolean;
  r record;
  v_req jsonb;
  v_items jsonb := '[]'::jsonb;
  v_state text;
  v_item_total int;
  v_item_met int;
  v_total int := 0;
  v_met int := 0;
  v_available int := 0;
  v_complete int := 0;
  v_unavailable int := 0;
begin
  select * into v_plan from public.event_plans where id = p_plan_id;
  select e.venue_name into v_venue from public.events e where e.tenant_id = v_plan.tenant_id and e.id = v_plan.event_id;
  select resp.answers into v_basics from public.event_plan_items i
    join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = v_plan.id and i.key = 'basics';
  v_venue_known := v_venue is not null or coalesce(v_basics, '{}'::jsonb) ? 'venue_details';
  -- The visible Ceremony's details, for arrival answers that reuse them.
  select resp.answers into v_ceremony from public.event_plan_items i
    join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = v_plan.id and i.key = 'ceremony' and i.disabled_at is null;
  -- The grand entrance decision, and whether its moments already hold answers
  -- (older plans answered them before the decision existed).
  select private.plan_grand_entrance(coalesce(resp.answers, '{}'::jsonb)) into v_entrance from public.event_plan_items i
    left join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = v_plan.id and i.key = 'reception_entrance';
  select exists (select 1 from public.event_plan_items i
    join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = v_plan.id and i.key in ('introductions', 'entrance_music') and i.disabled_at is null
      and resp.answers <> '{}'::jsonb) into v_entrance_saved;
  for r in
    select i.id, i.key, i.kind, l.editor, resp.answers
    from public.event_plan_items i
    join private.planning_library() l on l.key = i.key
    left join public.event_plan_items p on p.tenant_id = i.tenant_id and p.plan_id = i.plan_id and p.id = i.parent_id
    left join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = v_plan.id and i.disabled_at is null and (p.id is null or p.disabled_at is null)
    order by l.library_order
  loop
    -- Covered by another editor: nothing of its own to count.
    continue when r.editor in ('stage_details', 'included');
    -- A stage without fields of its own (Guest arrival, Speeches and program,
    -- Special dances) only holds moments, which count themselves.
    continue when r.kind = 'stage' and r.editor is null;
    -- The grand entrance's moments count only while it is planned (or, before
    -- any decision, once they hold answers). Otherwise they are left out of
    -- progress altogether, keeping what is saved.
    continue when r.key in ('introductions', 'entrance_music')
      and (v_entrance in ('none', 'undecided') or (v_entrance is null and not v_entrance_saved));
    if r.editor = 'basics' then
      v_req := private.plan_basics_requirements(r.answers, v_venue);
    elsif r.editor = 'contacts' then
      v_req := private.plan_contacts_requirements(v_plan.id, r.answers);
    elsif r.editor = 'arrival' then
      v_req := private.plan_arrival_requirements(r.answers, v_venue_known, v_ceremony);
    elsif r.editor = 'preferences' then
      v_req := private.plan_preferences_requirements(r.answers, v_basics);
    elsif private.is_moment_editor(r.editor) then
      v_req := private.plan_moment_requirements(r.editor, r.answers);
    elsif private.is_music_editor(r.editor) then
      v_req := private.plan_music_requirements(r.editor, r.answers);
    elsif r.editor like 'stage\_%' then
      v_req := private.plan_stage_requirements(r.editor, r.answers, v_venue_known, v_basics);
    else
      v_req := null;
    end if;
    if v_req is not null then
      select count(*)::int, (count(*) filter (where x ->> 'state' <> 'unanswered'))::int into v_item_total, v_item_met
      from jsonb_array_elements(v_req) x;
      v_state := case when v_item_met = v_item_total then 'complete'
                      when coalesce(r.answers, '{}'::jsonb) <> '{}'::jsonb then 'in_progress'
                      else 'not_started' end;
      v_total := v_total + v_item_total;
      v_met := v_met + v_item_met;
      v_available := v_available + 1;
      v_complete := v_complete + case when v_state = 'complete' then 1 else 0 end;
    else
      v_req := '[]'::jsonb;
      v_item_total := 0;
      v_item_met := 0;
      v_state := 'not_available';
      v_unavailable := v_unavailable + 1;
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'item_id', r.id, 'key', r.key, 'state', v_state, 'requirements', v_req, 'met', v_item_met, 'total', v_item_total));
  end loop;
  return jsonb_build_object(
    'scope', 'available_sections_only',
    'items', v_items,
    'requirements_total', v_total,
    'requirements_met', v_met,
    'percent', case when v_total = 0 then null else (v_met * 100) / v_total end,
    'available_sections', v_available,
    'complete_sections', v_complete,
    'unavailable_sections', v_unavailable);
end;
$$;


ALTER FUNCTION "private"."plan_progress"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_staff_editing"("p_event" "public"."events", "p_plan" "public"."event_plans") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  -- A read: the statement's time is enough (writes recheck with clock_timestamp()).
  v_at timestamptz := now();
  v_deadline timestamptz := private.plan_deadline(p_event, p_plan);
  v_days integer := coalesce(p_plan.client_cutoff_days, 14);
  v_expected timestamptz := private.planning_cutoff_at(p_event.event_date, p_event.timezone, v_days);
begin
  return private.plan_client_editing(p_event, p_plan, v_at) || jsonb_build_object(
    'now', v_at,
    'cutoff_days', v_days,
    'business_days', (select t.planning_lock_days from public.tenants t where t.id = p_event.tenant_id),
    'expected_deadline', v_expected,
    'schedule_changed', v_expected is distinct from v_deadline,
    'reopened_until', p_event.planning_override_until,
    'reopen_active', coalesce(p_event.planning_client_closed_at is null and p_event.planning_override_until > v_at and v_at >= v_deadline, false),
    'reopen_max_days', 14,
    'closed_at', p_event.planning_client_closed_at,
    'version', p_plan.client_cutoff_version,
    'history', coalesce((
      select jsonb_agg(h.entry order by h.occurred_at desc)
      from (select a.occurred_at,
                   jsonb_build_object('action', a.action, 'at', coalesce(a.metadata -> 'at', to_jsonb(a.occurred_at)),
                                      'actor', case when a.actor_type = 'staff' then coalesce(u.email, 'Former staff member') else 'Flux DJ' end,
                                      'reason', a.metadata ->> 'reason', 'before', a.metadata -> 'before', 'after', a.metadata -> 'after') as entry
            from public.audit_events a
            left join auth.users u on u.id = a.actor_id
            where a.tenant_id = p_event.tenant_id and a.entity_type = 'event' and a.entity_id = p_event.id
              and a.action in ('planning_cutoff_set', 'planning_cutoff_changed', 'planning_cutoff_recalculated',
                               'planning_client_reopened', 'planning_client_reopen_closed',
                               'planning_client_closed', 'planning_client_opened')
            order by a.occurred_at desc limit 10) h), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "private"."plan_staff_editing"("p_event" "public"."events", "p_plan" "public"."event_plans") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_stage_details"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(i.id, jsonb_build_object('answers', coalesce(r.answers, '{}'::jsonb), 'revision', coalesce(r.revision, 0))), '{}'::jsonb)
  from public.event_plan_items i
  join private.planning_library() l on l.key = i.key
  left join public.event_plan_responses r on r.tenant_id = i.tenant_id and r.item_id = i.id
  where i.plan_id = p_plan_id and i.kind = 'stage' and i.disabled_at is null
    and l.editor like 'stage\_%' and l.editor <> 'stage_details';
$$;


ALTER FUNCTION "private"."plan_stage_details"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_stage_requirements"("p_editor" "text", "p_answers" "jsonb", "p_venue_known" boolean, "p_basics" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := coalesce(p_answers, '{}'::jsonb);
  b jsonb := coalesce(p_basics, '{}'::jsonb);
  r jsonb := '[]'::jsonb;
begin
  if p_editor in ('stage_ceremony', 'stage_cocktail', 'stage_dinner', 'stage_party') then
    r := r || jsonb_build_array(
      case
        when a ->> 'location_source' = 'event_venue' and p_venue_known then jsonb_build_object('key', 'location', 'state', 'answered')
        when a ->> 'location_source' = 'event_venue' then jsonb_build_object('key', 'location', 'state', 'unanswered', 'note', 'venue_unknown')
        when a ->> 'location_source' = 'other' and a ? 'location_other' then jsonb_build_object('key', 'location', 'state', 'answered')
        else jsonb_build_object('key', 'location', 'state', 'unanswered')
      end);
    -- A ceremony needs its guest arrival time (no default is ever assumed).
    if p_editor = 'stage_ceremony' then
      r := r || jsonb_build_array(jsonb_build_object('key', 'guest_arrival', 'state', case when a ? 'guest_arrival_time' then 'answered' else 'unanswered' end));
    end if;
    r := r || jsonb_build_array(jsonb_build_object('key', 'start_time', 'state', case when a ? 'start_time' then 'answered' else 'unanswered' end));
  end if;
  if p_editor = 'stage_ceremony' then
    r := r || jsonb_build_array(case a ->> 'microphones'
      when 'needed' then jsonb_build_object('key', 'microphones', 'state', 'answered')
      when 'not_needed' then jsonb_build_object('key', 'microphones', 'state', 'answered')
      when 'discuss' then jsonb_build_object('key', 'microphones', 'state', 'unanswered', 'discuss', true)
      else jsonb_build_object('key', 'microphones', 'state', 'unanswered') end);
  elsif p_editor = 'stage_dinner' then
    r := r || jsonb_build_array(case
      when a ->> 'guest_count_source' = 'number' and a ? 'guest_count' then jsonb_build_object('key', 'guest_count', 'state', 'answered')
      when a ->> 'guest_count_source' = 'basics' and b ? 'guest_count' then jsonb_build_object('key', 'guest_count', 'state', 'answered')
      when a ->> 'guest_count_source' = 'basics' then jsonb_build_object('key', 'guest_count', 'state', 'unanswered', 'note', 'basics_missing')
      else jsonb_build_object('key', 'guest_count', 'state', 'unanswered') end);
  elsif p_editor = 'stage_entrance' then
    -- Guest entry is needed whatever the decision; then the decision, then
    -- (only while planned) its time.
    r := r || jsonb_build_array(jsonb_build_object('key', 'guest_entry', 'state', case when a ? 'guest_entry_time' then 'answered' else 'unanswered' end));
    r := r || jsonb_build_array(case private.plan_grand_entrance(a)
      when 'planned' then jsonb_build_object('key', 'grand_entrance', 'state', 'answered')
      when 'none' then jsonb_build_object('key', 'grand_entrance', 'state', 'not_applicable')
      when 'undecided' then jsonb_build_object('key', 'grand_entrance', 'state', 'unanswered', 'note', 'not_decided')
      else jsonb_build_object('key', 'grand_entrance', 'state', 'unanswered') end);
    if private.plan_grand_entrance(a) = 'planned' then
      r := r || jsonb_build_array(jsonb_build_object('key', 'entrance', 'state', case when a ? 'entrance_time' then 'answered' else 'unanswered' end));
    end if;
  elsif p_editor = 'stage_closing' then
    r := r || jsonb_build_array(case
      when a ->> 'finish_source' = 'time' and a ? 'finish_time' then jsonb_build_object('key', 'finish', 'state', 'answered')
      when a ->> 'finish_source' = 'basics_end' and b ? 'end_time' then jsonb_build_object('key', 'finish', 'state', 'answered')
      when a ->> 'finish_source' = 'basics_end' then jsonb_build_object('key', 'finish', 'state', 'unanswered', 'note', 'basics_missing')
      when a ->> 'finish_source' = 'discuss' then jsonb_build_object('key', 'finish', 'state', 'unanswered', 'discuss', true)
      else jsonb_build_object('key', 'finish', 'state', 'unanswered') end);
  end if;
  return r;
end;
$$;


ALTER FUNCTION "private"."plan_stage_requirements"("p_editor" "text", "p_answers" "jsonb", "p_venue_known" boolean, "p_basics" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_structure"("p_plan_id" "uuid", "p_include_disabled" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'general', coalesce((
      select jsonb_agg(jsonb_build_object('id', g.id, 'key', g.key, 'label', g.label, 'editor', l.editor, 'removable', l.removable,
                                          'disabled', g.disabled_at is not null) order by g.position, g.id)
      from public.event_plan_items g join private.planning_library() l on l.key = g.key
      where g.plan_id = p_plan_id and g.kind = 'general' and (p_include_disabled or g.disabled_at is null)), '[]'::jsonb),
    'stages', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'key', s.key, 'label', s.label, 'editor', sl.editor, 'disabled', s.disabled_at is not null,
        'moments', coalesce((
          select jsonb_agg(jsonb_build_object('id', m.id, 'key', m.key, 'label', m.label, 'editor', ml.editor,
                                              'disabled', m.disabled_at is not null) order by m.position, m.id)
          from public.event_plan_items m join private.planning_library() ml on ml.key = m.key
          where m.plan_id = p_plan_id and m.parent_id = s.id and (p_include_disabled or m.disabled_at is null)), '[]'::jsonb))
        order by s.position, s.id)
      from public.event_plan_items s join private.planning_library() sl on sl.key = s.key
      where s.plan_id = p_plan_id and s.kind = 'stage' and (p_include_disabled or s.disabled_at is null)), '[]'::jsonb));
$$;


ALTER FUNCTION "private"."plan_structure"("p_plan_id" "uuid", "p_include_disabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_timed_requirements"("p_key" "text", "p_answers" "jsonb", "p_song" boolean) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with input as (select coalesce(p_answers, '{}'::jsonb) as a)
  select jsonb_build_array(case
    when a ->> 'choice' = 'discuss' then jsonb_build_object('key', p_key, 'state', 'unanswered', 'discuss', true)
    when jsonb_array_length(coalesce(a -> 'entries', '[]'::jsonb)) > 0 then
      case when exists (select 1 from jsonb_array_elements(a -> 'entries') e
                        where not ((e ->> 'timing' = 'time' and e ? 'time') or (e ->> 'timing' = 'cue' and e ? 'cue') or e ->> 'timing' = 'anytime')
                           or (p_song and not e ? 'song_title'))
           then jsonb_build_object('key', p_key, 'state', 'unanswered', 'note', case when p_song then 'dedication_open' else 'entry_timing_open' end)
           else jsonb_build_object('key', p_key, 'state', 'answered') end
    when a ->> 'choice' = 'none' then jsonb_build_object('key', p_key, 'state', 'not_applicable')
    else jsonb_build_object('key', p_key, 'state', 'unanswered') end)
  from input;
$$;


ALTER FUNCTION "private"."plan_timed_requirements"("p_key" "text", "p_answers" "jsonb", "p_song" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plan_timeline_warnings"("p_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  a jsonb;
  b jsonb;
  w jsonb := '[]'::jsonb;
  v_s int;
  v_e int;
  v_x int;
  v_y int;
  v_basics_end int;
  prev_label text;
  prev_s int;
  prev_e int;
begin
  select resp.answers into b from public.event_plan_items i
    join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = p_plan_id and i.key = 'basics';
  b := coalesce(b, '{}'::jsonb);
  -- Event basics' end: earlier than its start means the next day (shown so in its editor).
  v_basics_end := private.plan_minutes(b, 'end');
  if v_basics_end is not null and private.plan_minutes(b, 'start') is not null and v_basics_end <= private.plan_minutes(b, 'start') then
    v_basics_end := v_basics_end + 1440;
  end if;

  for r in
    select i.id, i.key, i.label, l.editor, resp.answers
    from public.event_plan_items i
    join private.planning_library() l on l.key = i.key
    left join public.event_plan_responses resp on resp.tenant_id = i.tenant_id and resp.item_id = i.id
    where i.plan_id = p_plan_id and i.kind = 'stage' and i.disabled_at is null
      and l.editor like 'stage\_%' and l.editor <> 'stage_details'
    order by i.position, i.id
  loop
    a := coalesce(r.answers, '{}'::jsonb);
    case r.editor
      when 'stage_ceremony' then
        v_s := private.plan_minutes(a, 'start');
        v_e := private.plan_minutes(a, 'end');
        v_x := private.plan_minutes(a, 'guest_arrival');
        if v_x is not null and v_s is not null and v_x > v_s then
          w := w || jsonb_build_array(jsonb_build_object('item_id', r.id, 'key', r.key, 'message', 'Guest arrival is after the ceremony starts.'));
        end if;
      when 'stage_entrance' then
        v_x := private.plan_minutes(a, 'guest_entry');
        -- A grand entrance time kept while the entrance is skipped or undecided isn't on the timeline.
        v_y := case when private.plan_grand_entrance(a) = 'planned' then private.plan_minutes(a, 'entrance') end;
        if v_x is not null and v_y is not null and v_y < v_x then
          w := w || jsonb_build_array(jsonb_build_object('item_id', r.id, 'key', r.key, 'message', 'The grand entrance is before guests enter.'));
        end if;
        v_s := coalesce(v_x, v_y);
        v_e := v_y;
      when 'stage_closing' then
        v_s := case a ->> 'finish_source' when 'time' then private.plan_minutes(a, 'finish') when 'basics_end' then v_basics_end end;
        v_e := v_s;
      else
        v_s := private.plan_minutes(a, 'start');
        v_e := private.plan_minutes(a, 'end');
    end case;
    if v_s is not null then
      if prev_s is not null and v_s < prev_s then
        w := w || jsonb_build_array(jsonb_build_object('item_id', r.id, 'key', r.key, 'message',
          case when r.editor = 'stage_closing' then 'The finish time is before ' || prev_label || ' starts.'
               else r.label || ' starts before ' || prev_label || ' starts.' end));
      elsif prev_e is not null and v_s < prev_e then
        w := w || jsonb_build_array(jsonb_build_object('item_id', r.id, 'key', r.key, 'message',
          case when r.editor = 'stage_closing' then 'The finish time is before ' || prev_label || ' ends.'
               else r.label || ' starts before ' || prev_label || ' ends.' end));
      end if;
      prev_label := r.label;
      prev_s := v_s;
      prev_e := v_e;
    end if;
  end loop;
  return w;
end;
$$;


ALTER FUNCTION "private"."plan_timeline_warnings"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."planning_cutoff_at"("p_event_date" "date", "p_timezone" "text", "p_days" integer) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select min(x.at)
  from (select ((p_event_date - p_days)::timestamp at time zone p_timezone) - make_interval(mins => 15 * k) as at
        from generate_series(0, 12) k) x
  where (x.at at time zone p_timezone)::date = p_event_date - p_days;
$$;


