CREATE OR REPLACE FUNCTION "private"."planning_invitations_once"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.revoked_at is not null and (new.revoked_at, new.revoked_by, new.revoke_reason) is distinct from (old.revoked_at, old.revoked_by, old.revoke_reason) then
    raise exception 'a revoked invitation cannot change' using errcode = 'check_violation';
  end if;
  if old.accepted_at is not null and (new.accepted_at, new.accepted_by) is distinct from (old.accepted_at, old.accepted_by) then
    raise exception 'acceptance is recorded once' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."planning_invitations_once"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."planning_item_check"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_lib record;
  v_parent_kind text;
  v_parent_key text;
begin
  select l.kind, l.parent_keys into v_lib from private.planning_library() l where l.key = new.key;
  if not found or v_lib.kind <> new.kind then
    raise exception 'planning item % is not a % in the library', new.key, new.kind using errcode = 'check_violation';
  end if;
  if new.kind = 'moment' then
    if tg_table_name = 'planning_template_items' then
      select p.kind, p.key into v_parent_kind, v_parent_key from public.planning_template_items p
      where p.tenant_id = new.tenant_id and p.template_id = new.template_id and p.id = new.parent_id;
    else
      select p.kind, p.key into v_parent_kind, v_parent_key from public.event_plan_items p
      where p.tenant_id = new.tenant_id and p.plan_id = new.plan_id and p.id = new.parent_id;
    end if;
    if v_parent_kind is distinct from 'stage' or not (v_parent_key = any (v_lib.parent_keys)) then
      raise exception 'planning moment % cannot be placed under %', new.key, coalesce(v_parent_key, 'nothing')
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."planning_item_check"() OWNER TO "postgres";


