CREATE OR REPLACE FUNCTION "private"."playlist_url_key"("p_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  m text[] := regexp_match(btrim(coalesce(p_url, '')), '^https://([^/?#]*)([^?#]*)(\?[^#]*)?');
  v_host text;
  v_param text;
  v_name text;
  v_query text := '';
begin
  if m is null then
    return null;
  end if;
  v_host := lower(m[1]);
  if v_host like 'www.%' then
    v_host := substr(v_host, 5);
  end if;
  if m[3] is not null then
    foreach v_param in array string_to_array(substr(m[3], 2), '&') loop
      v_name := lower(split_part(v_param, '=', 1));
      continue when v_param = '' or v_name = 'si' or v_name like 'utm\_%';
      v_query := v_query || case when v_query = '' then '?' else '&' end || v_param;
    end loop;
  end if;
  return v_host || regexp_replace(m[2], '/+$', '') || v_query;
end;
$_$;


ALTER FUNCTION "private"."playlist_url_key"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."plural_unit"("p_unit" "text", "p_count" bigint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
  select case
    when p_count = 1 or btrim(p_unit) !~* '^[a-z]+$' then btrim(p_unit)
    when btrim(p_unit) ~* '(s|x|z|ch|sh)$' then btrim(p_unit) || 'es'
    when btrim(p_unit) ~* '[^aeiou]y$' then left(btrim(p_unit), -1) || 'ies'
    else btrim(p_unit) || 's'
  end;
$_$;


