CREATE OR REPLACE FUNCTION "private"."require_owner_of"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_membership_id uuid := private.require_staff_of(p_tenant_id);
begin
  if not exists (select 1 from public.tenant_memberships m where m.id = v_membership_id and m.role = 'owner') then
    raise exception 'only the owner can manage the team' using errcode = 'insufficient_privilege';
  end if;
  return v_membership_id;
end;
$$;


ALTER FUNCTION "private"."require_owner_of"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."require_platform_admin"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.is_platform_admin() then
    raise exception 'only platform administrators can manage DJ invitations' using errcode = 'insufficient_privilege';
  end if;
end;
$$;


ALTER FUNCTION "private"."require_platform_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."require_staff_of"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_membership_id uuid;
begin
  select m.id into v_membership_id
  from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid()) and m.removed_at is null;
  if v_membership_id is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if exists (select 1 from public.tenants t where t.id = p_tenant_id and t.suspended_at is not null) then
    raise exception 'workspace_suspended: this workspace is suspended' using errcode = 'PT423';
  end if;
  return v_membership_id;
end;
$$;


ALTER FUNCTION "private"."require_staff_of"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."resolve_proposal_session"("p_session_hash" "text", "p_proposal_id" "uuid", "p_tenant_slug" "text") RETURNS TABLE("state" "text", "session_id" "uuid", "tenant_id" "uuid", "proposal_id" "uuid", "event_id" "uuid", "access_link_id" "uuid", "intended_client_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  r record;
begin
  if p_session_hash is null or p_session_hash !~ '^[0-9a-f]{64}$' then
    return query select 'invalid'::text, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  select s.id as sid, s.expires_at as s_exp, s.revoked_at as s_rev,
         l.id as lid, l.expires_at as l_exp, l.revoked_at as l_rev, l.intended_client_id as cid,
         p.id as pid, p.tenant_id as tid, p.event_id as eid, p.status, p.expires_at as p_exp,
         e.active_proposal_id, t.archived_at, t.suspended_at, e.archived_at as event_archived_at
    into r
  from public.proposal_sessions s
  join public.access_links l on l.tenant_id = s.tenant_id and l.id = s.access_link_id
  join public.proposals p on p.tenant_id = s.tenant_id and p.id = s.proposal_id
  join public.events e on e.tenant_id = p.tenant_id and e.id = p.event_id
  join public.tenants t on t.id = s.tenant_id
  where s.session_hash = p_session_hash and s.proposal_id = p_proposal_id and t.slug = p_tenant_slug
    and l.purpose = 'proposal';

  if not found or r.s_exp <= now() or r.l_exp <= now() or r.archived_at is not null or r.event_archived_at is not null then
    return query select 'invalid'::text, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if r.s_rev is not null or r.l_rev is not null then
    return query select (case when r.status = 'superseded' then 'superseded' else 'invalid' end)::text,
      null::uuid, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if r.suspended_at is not null then
    return query select 'unavailable'::text, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  return query select private.proposal_state(r.status, r.p_exp, r.active_proposal_id = r.pid),
    r.sid, r.tid, r.pid, r.eid, r.lid, r.cid;
end;
$_$;


ALTER FUNCTION "private"."resolve_proposal_session"("p_session_hash" "text", "p_proposal_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."retire_contract_invitations"("p_contract_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.access_links set revoked_at = now()
    where purpose = 'contract' and contract_id = p_contract_id and revoked_at is null;
  update public.email_outbox set status = 'cancelled', last_error = left(p_reason, 1000)
    where entity_type = 'contract' and entity_id = p_contract_id and status = 'pending';
$$;


ALTER FUNCTION "private"."retire_contract_invitations"("p_contract_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."revoke_planning_invitations"("p_event_id" "uuid", "p_reason" "text", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[];
begin
  with revoked as (
    update public.planning_invitations set revoked_at = now(), revoked_by = p_actor, revoke_reason = left(p_reason, 200)
      where event_id = p_event_id and revoked_at is null
      returning id
  )
  select coalesce(array_agg(id), '{}') into v_ids from revoked;
  if cardinality(v_ids) > 0 then
    update public.email_outbox set status = 'cancelled', last_error = left('Cancelled: ' || p_reason, 1000), locked_until = null
      where entity_type = 'planning_invitation' and entity_id = any (v_ids) and status = 'pending';
  end if;
  return cardinality(v_ids);
end;
$$;


ALTER FUNCTION "private"."revoke_planning_invitations"("p_event_id" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."revoke_platform_admin"("p_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid;
begin
  delete from public.platform_admins a using auth.users u
    where u.id = a.user_id and lower(u.email) = lower(btrim(p_email))
    returning a.user_id into v_user;
  if v_user is null then
    return false;
  end if;
  perform private.platform_audit('platform_admin', v_user, 'revoked', null, '{}'::jsonb);
  return true;
end;
$$;


ALTER FUNCTION "private"."revoke_platform_admin"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rule_condition_fits_question"("condition" "jsonb", "answer_type" "text", "options" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  with option_values as (
    select o.item ->> 'value' as value from jsonb_array_elements(options) o(item)
  )
  select case
    when answer_type = 'boolean' then
      condition ->> 'op' = 'equals' and jsonb_typeof(condition -> 'value') = 'boolean'
    when answer_type = 'single_choice' and condition ->> 'op' = 'equals' then
      jsonb_typeof(condition -> 'value') = 'string'
      and (condition ->> 'value') in (select value from option_values)
    when answer_type = 'single_choice' and condition ->> 'op' = 'in' then
      not exists (
        select 1 from jsonb_array_elements_text(condition -> 'values') v(value)
        where v.value not in (select value from option_values)
      )
    when answer_type = 'multi_choice' then
      condition ->> 'op' = 'contains'
      and (condition ->> 'value') in (select value from option_values)
    else false
  end;
$$;


ALTER FUNCTION "private"."rule_condition_fits_question"("condition" "jsonb", "answer_type" "text", "options" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rule_condition_key"("p_condition" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select case
    when p_condition ->> 'op' = 'in' and jsonb_typeof(p_condition -> 'values') = 'array' then (
      select case
        when count(distinct v) = 1 then jsonb_build_object('op', 'equals', 'value', to_jsonb(min(v)))
        else jsonb_build_object('op', 'in', 'values', coalesce(jsonb_agg(distinct v order by v), '[]'::jsonb))
      end
      from jsonb_array_elements_text(p_condition -> 'values') v
    )
    else p_condition
  end;
$$;


ALTER FUNCTION "private"."rule_condition_key"("p_condition" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."rule_condition_matches"("p_condition" "jsonb", "p_answer" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(case p_condition ->> 'op'
    when 'equals' then p_answer = p_condition -> 'value'
    when 'in' then jsonb_typeof(p_answer) = 'string' and (p_condition -> 'values') @> jsonb_build_array(p_answer)
    when 'contains' then jsonb_typeof(p_answer) = 'array' and p_answer @> jsonb_build_array(p_condition -> 'value')
    else false
  end, false);
$$;


ALTER FUNCTION "private"."rule_condition_matches"("p_condition" "jsonb", "p_answer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."save_plan_basics"("p_plan_id" "uuid", "p_expected_revision" integer, "p_answers" "jsonb", "p_actor" "text", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.save_plan_item(p_plan_id, (select i.id from public.event_plan_items i where i.plan_id = p_plan_id and i.key = 'basics'),
                                p_expected_revision, p_answers, p_actor, p_user_id);
$$;


ALTER FUNCTION "private"."save_plan_basics"("p_plan_id" "uuid", "p_expected_revision" integer, "p_answers" "jsonb", "p_actor" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."save_plan_item"("p_plan_id" "uuid", "p_item_id" "uuid", "p_expected_revision" integer, "p_answers" "jsonb", "p_actor" "text", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item public.event_plan_items%rowtype;
  v_editor text;
  v_resp public.event_plan_responses%rowtype;
  v_norm jsonb;
  v_links jsonb;
  v_replay_safe boolean;
begin
  select * into v_item from public.event_plan_items where plan_id = p_plan_id and id = p_item_id;
  if not found then
    return jsonb_build_object('status', 'unavailable');
  end if;
  select l.editor into v_editor from private.planning_library() l where l.key = v_item.key;
  if v_editor is null or v_editor in ('stage_details', 'included') or v_item.disabled_at is not null
     or exists (select 1 from public.event_plan_items p where p.id = v_item.parent_id and p.disabled_at is not null) then
    return jsonb_build_object('status', 'unavailable');
  end if;
  v_norm := private.normalize_plan_answers(v_editor, p_answers);
  if not (v_norm ->> 'ok')::boolean then
    return jsonb_build_object('status', 'invalid', 'field', v_norm -> 'field', 'message', v_norm ->> 'message');
  end if;
  v_replay_safe := private.is_music_editor(v_editor) or private.is_moment_editor(v_editor);
  select * into v_resp from public.event_plan_responses where item_id = v_item.id for update;
  v_links := coalesce(private.check_plan_song_links(p_plan_id, v_item.key, v_resp.answers, v_norm -> 'answers'),
                      private.check_plan_contact_refs(p_plan_id, v_editor, v_norm -> 'answers'),
                      private.check_plan_vendor_reach(v_editor, v_resp.answers, v_norm -> 'answers'));
  if v_links is not null then
    return v_links;
  end if;
  if v_resp.id is null then
    if p_expected_revision is distinct from 0 then
      return jsonb_build_object('status', 'conflict');
    end if;
    insert into public.event_plan_responses (tenant_id, plan_id, item_id, answers, updated_by_actor, updated_by_user_id)
    values (v_item.tenant_id, p_plan_id, v_item.id, v_norm -> 'answers', p_actor, p_user_id)
    on conflict (item_id) do nothing
    returning * into v_resp;
    if v_resp.id is null then
      -- A concurrent first save won: the same answers are this save, already stored.
      select * into v_resp from public.event_plan_responses where item_id = v_item.id for update;
      if not (v_replay_safe and v_resp.answers = v_norm -> 'answers') then
        return jsonb_build_object('status', 'conflict');
      end if;
    end if;
  elsif p_expected_revision is distinct from v_resp.revision then
    -- A retried or doubled save (same entry ids) is already stored.
    if not (v_replay_safe and v_resp.answers = v_norm -> 'answers') then
      return jsonb_build_object('status', 'conflict');
    end if;
  elsif v_resp.answers is distinct from v_norm -> 'answers' or not v_replay_safe then
    update public.event_plan_responses
      set answers = v_norm -> 'answers', revision = revision + 1, updated_by_actor = p_actor, updated_by_user_id = p_user_id
      where id = v_resp.id returning * into v_resp;
  end if;
  return jsonb_build_object('status', 'saved', 'revision', v_resp.revision, 'answers', v_resp.answers,
                            'progress', private.plan_progress(p_plan_id), 'timeline_warnings', private.plan_timeline_warnings(p_plan_id));
end;
$$;


ALTER FUNCTION "private"."save_plan_item"("p_plan_id" "uuid", "p_item_id" "uuid", "p_expected_revision" integer, "p_answers" "jsonb", "p_actor" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."selection_choice_problem"("p_selection_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  s public.proposal_selections%rowtype;
  v_offer jsonb;
  v_package jsonb;
  q jsonb;
  v_answer jsonb;
  v_ok boolean;
  v_problem text;
begin
  select * into s from public.proposal_selections where id = p_selection_id;
  if not found then
    return null;
  end if;
  select p.offer_snapshot into v_offer from public.proposals p where p.tenant_id = s.tenant_id and p.id = s.proposal_id;
  if v_offer is null then
    return 'the offer is not frozen';
  end if;
  select x into v_package from jsonb_array_elements(v_offer -> 'packages') x where x ->> 'key' = s.package_key;
  if v_package is null then
    return 'package is not part of the offer';
  end if;

  if exists (
    select 1
    from jsonb_each(s.addon_quantities) a(k, v)
    left join lateral (
      select (o ->> 'max_quantity')::int as max_q from jsonb_array_elements(v_offer -> 'addons') o where o ->> 'gear_key' = a.k
    ) m on true
    where case
      when m.max_q is null then true
      when jsonb_typeof(a.v) <> 'number' or (a.v #>> '{}') !~ '^[0-9]{1,3}$' then true
      else (a.v #>> '{}')::int not between 1 and m.max_q
    end
  ) then
    return 'addon quantities are outside what the offer allows';
  end if;

  if exists (
    select 1 from jsonb_object_keys(s.logistics_answers) k
    where not exists (select 1 from jsonb_array_elements(v_offer -> 'questions') qq where qq ->> 'key' = k)
  ) then
    return 'an answer refers to a question outside the offer';
  end if;

  for q in select x from jsonb_array_elements(v_offer -> 'questions') x loop
    v_answer := s.logistics_answers -> (q ->> 'key');
    if v_answer is null or jsonb_typeof(v_answer) = 'null' then
      if (q ->> 'required')::boolean then
        return 'required answer missing: ' || (q ->> 'key');
      end if;
      continue;
    end if;
    v_ok := case q ->> 'answer_type'
      when 'boolean' then jsonb_typeof(v_answer) = 'boolean'
      when 'single_choice' then
        jsonb_typeof(v_answer) = 'string' and (q -> 'options') @> jsonb_build_array(jsonb_build_object('value', v_answer))
      when 'multi_choice' then
        case when jsonb_typeof(v_answer) <> 'array' then false
        else not exists (
               select 1 from jsonb_array_elements(v_answer) e
               where jsonb_typeof(e) <> 'string' or not (q -> 'options') @> jsonb_build_array(jsonb_build_object('value', e))
             )
             and (select count(distinct e) = count(*) from jsonb_array_elements(v_answer) e)
        end
      when 'short_text' then
        case when jsonb_typeof(v_answer) <> 'string' then false
        else length(btrim(v_answer #>> '{}')) between 1 and 2000 end
      else false
    end;
    if not v_ok then
      return 'invalid answer: ' || (q ->> 'key');
    end if;
  end loop;

  if (select count(*) <> count(distinct l.item_key) from public.proposal_selection_lines l
      where l.selection_id = s.id and l.source in ('optional', 'required')) then
    return 'chargeable gear appears more than once';
  end if;

  with fired as (
    select r ->> 'gear_key' as gear, (r ->> 'required_quantity')::int as qty
    from jsonb_array_elements(v_offer -> 'rules') r
    where private.rule_condition_matches(r -> 'condition', s.logistics_answers -> (r ->> 'question_key'))
  ),
  required as (select gear, sum(qty)::int as qty from fired group by gear),
  included as (select i ->> 'gear_key' as gear, (i ->> 'quantity')::int as qty from jsonb_array_elements(v_package -> 'included') i),
  optional as (select a.k as gear, (a.v #>> '{}')::int as qty from jsonb_each(s.addon_quantities) a(k, v)),
  expected as (
    select g.gear,
           greatest(0, coalesce(r.qty, 0) - coalesce(i.qty, 0)) as req_extra,
           greatest(coalesce(o.qty, 0), greatest(0, coalesce(r.qty, 0) - coalesce(i.qty, 0))) as qty
    from (select gear from required union select gear from optional) g
    left join required r on r.gear = g.gear
    left join included i on i.gear = g.gear
    left join optional o on o.gear = g.gear
  ),
  expected_lines as (select * from expected where qty > 0),
  actual as (
    select l.item_key as gear, l.source, l.quantity, l.required_quantity
    from public.proposal_selection_lines l
    where l.selection_id = s.id and l.source in ('optional', 'required')
  )
  select coalesce(e.gear, a.gear) into v_problem
  from expected_lines e
  full join actual a on a.gear = e.gear
  where e.gear is null or a.gear is null
     or a.quantity <> e.qty
     or a.required_quantity <> e.req_extra
     or a.source <> case when e.req_extra > 0 then 'required' else 'optional' end
  limit 1;
  if v_problem is not null then
    return 'chargeable gear does not match the answers, package and addons: ' || v_problem;
  end if;

  if exists (
    select 1
    from (select i ->> 'gear_key' as gear, (i ->> 'quantity')::int as qty from jsonb_array_elements(v_package -> 'included') i) e
    full join (
      select l.item_key as gear, l.quantity as qty from public.proposal_selection_lines l
      where l.selection_id = s.id and l.source = 'included'
    ) a on a.gear = e.gear
    where e.gear is null or a.gear is null or a.qty <> e.qty
  ) then
    return 'included gear does not match the package';
  end if;
  return null;
end;
$_$;


ALTER FUNCTION "private"."selection_choice_problem"("p_selection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."set_event_archived"("p_event_id" "uuid", "p_archived" boolean, "p_actor_type" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.events%rowtype;
  v_proposals uuid[];
  v_links int := 0;
  v_sessions int := 0;
  v_emails int := 0;
  v_contract_emails int := 0;
begin
  select * into v_event from public.events where id = p_event_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if p_archived = (v_event.archived_at is not null) then
    return jsonb_build_object('status', case when p_archived then 'archived' else 'active' end, 'replayed', true);
  end if;

  if p_archived then
    select coalesce(array_agg(p.id), '{}') into v_proposals
    from public.proposals p where p.tenant_id = v_event.tenant_id and p.event_id = v_event.id;
    -- Lock order everywhere: event, then proposals.
    perform 1 from public.proposals p where p.id = any (v_proposals) for update;

    update public.events set archived_at = now() where id = v_event.id;
    update public.access_links set revoked_at = now()
      where tenant_id = v_event.tenant_id and proposal_id = any (v_proposals) and revoked_at is null;
    get diagnostics v_links = row_count;
    update public.proposal_sessions set revoked_at = now()
      where tenant_id = v_event.tenant_id and proposal_id = any (v_proposals) and revoked_at is null;
    get diagnostics v_sessions = row_count;
    update public.email_outbox set status = 'cancelled', last_error = 'event archived'
      where tenant_id = v_event.tenant_id and entity_id = any (v_proposals)
        and event_type in ('proposal_sent', 'proposal_approved') and status = 'pending';
    get diagnostics v_emails = row_count;
    -- Contract invitations share the proposal links table and were revoked
    -- above; their pending emails are cancelled here.
    update public.email_outbox set status = 'cancelled', last_error = 'event archived'
      where tenant_id = v_event.tenant_id and entity_type = 'contract' and status = 'pending'
        and event_type <> 'contract_voided'
        and entity_id in (select k.id from public.contracts k where k.tenant_id = v_event.tenant_id and k.event_id = v_event.id);
    get diagnostics v_contract_emails = row_count;
    v_emails := v_emails + v_contract_emails;
  else
    update public.events set archived_at = null where id = v_event.id;
  end if;

  perform private.audit(v_event.tenant_id, 'event', v_event.id, case when p_archived then 'archived' else 'unarchived' end,
    p_actor_type, p_actor_id,
    case when p_archived then jsonb_build_object('links_revoked', v_links, 'sessions_revoked', v_sessions, 'emails_cancelled', v_emails)
         else '{}'::jsonb end);
  return jsonb_build_object('status', case when p_archived then 'archived' else 'active' end, 'replayed', false,
                            'links_revoked', v_links, 'sessions_revoked', v_sessions, 'emails_cancelled', v_emails);
end;
$$;


