CREATE OR REPLACE FUNCTION "private"."tenant_write_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant uuid := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
  v_suspended timestamptz;
begin
  if v_tenant is not null then
    select t.suspended_at into v_suspended from public.tenants t where t.id = v_tenant for key share;
    if v_suspended is not null then
      -- Signed-in non-members get the same refusal RLS would give them, so
      -- the suspension of a business they don't belong to never shows.
      if (select auth.uid()) is not null and not exists (
           select 1 from public.tenant_memberships m
           where m.tenant_id = v_tenant and m.user_id = (select auth.uid()) and m.removed_at is null) then
        raise exception 'new row violates row-level security policy' using errcode = 'insufficient_privilege';
      end if;
      raise exception 'workspace_suspended: this workspace is suspended' using errcode = 'PT423';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "private"."tenant_write_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."tenants_suspension_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.suspended_at is not null or new.suspension_version <> 0 then
      raise exception 'a workspace is created active' using errcode = 'insufficient_privilege';
    end if;
    return new;
  end if;
  if (new.suspended_at is distinct from old.suspended_at or new.suspension_version is distinct from old.suspension_version)
     and current_setting('flux.workspace_suspension', true) is distinct from new.id::text then
    raise exception 'workspace suspension changes only through suspend_workspace and restore_workspace'
      using errcode = 'insufficient_privilege';
  end if;
  if old.suspended_at is not null and new.suspended_at is not null
     and (to_jsonb(new) - array['archived_at', 'updated_at']) is distinct from (to_jsonb(old) - array['archived_at', 'updated_at']) then
    raise exception 'workspace_suspended: this workspace is suspended' using errcode = 'PT423';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."tenants_suspension_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."unused_tenant_logos"() RETURNS TABLE("tenant_id" "uuid", "storage_path" "text", "registered" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select l.tenant_id, l.storage_path, true, l.created_at
  from public.tenant_logos l
  where not exists (select 1 from public.tenants t where t.id = l.tenant_id and t.logo_storage_path = l.storage_path)
    and not exists (select 1 from public.proposals p
                    where p.tenant_id = l.tenant_id and p.offer_snapshot -> 'branding' ->> 'logo_storage_path' = l.storage_path)
  union all
  select (split_part(o.name, '/', 1))::uuid, o.name, false, o.created_at
  from storage.objects o
  where o.bucket_id = 'tenant-logos' and split_part(o.name, '/', 1) ~ '^[0-9a-f-]{36}$'
    and not exists (select 1 from public.tenant_logos l where l.storage_path = o.name);
$_$;


