CREATE OR REPLACE FUNCTION "private"."verify_proposal_selection"("p_selection_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s public.proposal_selections%rowtype;
  offer jsonb;
  offer_hash text;
  problem text;
begin
  select * into s from public.proposal_selections where id = p_selection_id;
  if not found then
    return;
  end if;

  select p.offer_snapshot, p.offer_sha256 into offer, offer_hash
  from public.proposals p
  where p.tenant_id = s.tenant_id and p.id = s.proposal_id;

  problem := case
    when s.offer_sha256 <> offer_hash then 'selection was priced against a different offer'
    when s.currency <> offer ->> 'currency' then 'currency does not match the offer'
    when not exists (select 1 from jsonb_array_elements(offer -> 'packages') pk where pk ->> 'key' = s.package_key)
      then 'package is not part of the offer'
    when (select count(*) from public.proposal_selection_lines l
          where l.selection_id = s.id and l.source = 'package') <> 1
      then 'exactly one package line is required'
    when exists (select 1 from public.proposal_selection_lines l
                 where l.selection_id = s.id and l.source = 'package' and l.item_key <> s.package_key)
      then 'package line does not match the selected package'
    else null
  end;

  -- Unit prices and tax categories must come from the frozen offer.
  if problem is null then
    select 'line ' || l.line_no || ' (' || l.item_key || ') does not match the frozen offer'
      into problem
    from public.proposal_selection_lines l
    left join lateral (
      select (pk ->> 'base_price_cents')::bigint as price, pk ->> 'tax_category' as tax_category
      from jsonb_array_elements(offer -> 'packages') pk
      where pk ->> 'key' = l.item_key
    ) pkg on l.source = 'package'
    left join lateral (
      select (offer -> 'gear' -> l.item_key ->> 'unit_price_cents')::bigint as price,
             offer -> 'gear' -> l.item_key ->> 'tax_category' as tax_category
    ) gear on l.source in ('optional', 'required', 'included')
    left join lateral (
      select (inc ->> 'quantity')::int as quantity
      from jsonb_array_elements(offer -> 'packages') pk,
           jsonb_array_elements(pk -> 'included') inc
      where pk ->> 'key' = s.package_key and inc ->> 'gear_key' = l.item_key
    ) incl on l.source = 'included'
    where l.selection_id = s.id
      and case l.source
        when 'package' then pkg.price is distinct from l.unit_price_cents
                         or pkg.tax_category is distinct from l.tax_category
        when 'included' then incl.quantity is distinct from l.quantity
                          or gear.tax_category is distinct from l.tax_category
        else gear.price is distinct from l.unit_price_cents
          or gear.tax_category is distinct from l.tax_category
      end
    order by l.line_no
    limit 1;
  end if;

  if problem is null and s.subtotal_cents <> (
    select coalesce(sum(l.line_total_cents), 0) from public.proposal_selection_lines l where l.selection_id = s.id
  ) then
    problem := 'subtotal does not equal the sum of line totals';
  end if;

  -- The discount, from the frozen offer and the subtotal.
  if problem is null and s.discount_cents <> private.offer_discount_cents(offer, s.subtotal_cents) then
    problem := 'discount does not match the frozen offer';
  end if;

  -- Its allocation: proportional to line totals, largest remainder first,
  -- ties to the lower line number.
  if problem is null then
    with l as (
      select l.line_no, l.line_total_cents, l.discount_cents,
             s.discount_cents::numeric * l.line_total_cents as share
      from public.proposal_selection_lines l
      where l.selection_id = s.id
    ),
    split as (
      select l.*,
             case when s.subtotal_cents = 0 then 0 else floor(l.share / s.subtotal_cents) end as base,
             case when s.subtotal_cents = 0 then 0 else mod(l.share, s.subtotal_cents) end as remainder
      from l
    ),
    ranked as (
      select split.*, row_number() over (order by split.remainder desc, split.line_no) as rank,
             s.discount_cents - sum(split.base) over () as extra
      from split
    )
    select 'line ' || r.line_no || ' has the wrong share of the discount' into problem
    from ranked r
    where r.discount_cents <> r.base + case when r.rank <= r.extra then 1 else 0 end
    order by r.line_no
    limit 1;
  end if;

  -- The selection record says the same about its discount.
  if problem is null and (
       coalesce(s.selection_snapshot ->> 'discount_cents', '0') <> s.discount_cents::text
       or (s.selection_snapshot ? 'discount') <> (offer ? 'discount')
       or (offer ? 'discount' and (
             s.selection_snapshot -> 'discount' ->> 'type' is distinct from offer -> 'discount' ->> 'type'
             or s.selection_snapshot -> 'discount' ->> 'label' is distinct from offer -> 'discount' ->> 'label'))
     ) then
    problem := 'the selection''s discount details do not match the frozen offer';
  end if;

  -- Recompute taxes with the frozen rates and the documented rounding
  -- policy, on each line's discounted amount.
  if problem is null then
    with rates as (
      select r ->> 'code' as code, r ->> 'label' as label, (r ->> 'rate_ppm')::bigint as rate_ppm,
             ord
      from jsonb_array_elements(offer -> 'tax' -> 'rates') with ordinality as x(r, ord)
    ),
    expected as (
      select rates.code, rates.label, rates.rate_ppm, rates.ord,
             coalesce(sum(l.line_total_cents - l.discount_cents) filter (where applies), 0) as taxable_cents,
             coalesce(sum(((l.line_total_cents - l.discount_cents) * rates.rate_ppm + 500000) / 1000000) filter (where applies), 0) as amount_cents
      from rates
      left join public.proposal_selection_lines l on l.selection_id = s.id
      left join lateral (
        select exists (
          select 1 from jsonb_array_elements_text(offer -> 'tax' -> 'categories' -> l.tax_category) c(code)
          where c.code = rates.code
        ) as applies
      ) a on true
      group by rates.code, rates.label, rates.rate_ppm, rates.ord
    ),
    expected_json as (
      select coalesce(jsonb_agg(jsonb_build_object(
               'code', code, 'label', label, 'rate_ppm', rate_ppm,
               'taxable_cents', taxable_cents, 'amount_cents', amount_cents) order by ord), '[]'::jsonb) as breakdown,
             coalesce(sum(amount_cents), 0) as total_tax
      from expected
    )
    select case
      when s.tax_breakdown <> e.breakdown then 'tax breakdown does not match the frozen rates and rounding policy'
      when s.tax_cents <> e.total_tax then 'tax total does not equal the sum of rounded taxes'
    end
    into problem
    from expected_json e;
  end if;

  if problem is not null then
    raise exception 'invalid priced selection: %', problem using errcode = 'check_violation';
  end if;
end;
$$;


ALTER FUNCTION "private"."verify_proposal_selection"("p_selection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."verify_selection_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_problem text;
begin
  if tg_table_name = 'proposal_selections' then
    v_id := new.id;
  else
    v_id := new.selection_id;
  end if;
  perform private.verify_proposal_selection(v_id);
  v_problem := private.selection_choice_problem(v_id);
  if v_problem is not null then
    raise exception 'invalid selection: %', v_problem using errcode = 'check_violation';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."verify_selection_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."workspace_suspension_reason"("p_reason" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := btrim(regexp_replace(coalesce(p_reason, ''), '\s+', ' ', 'g'));
begin
  if length(v_reason) not between 3 and 500 then
    raise exception 'workspace_reason_required: give an internal reason (3 to 500 characters)' using errcode = 'invalid_parameter_value';
  end if;
  return v_reason;
end;
$$;


ALTER FUNCTION "private"."workspace_suspension_reason"("p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_contract_invitation"("p_link_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i record;
  v_uid uuid := (select auth.uid());
  v_email text;
  v_existing record;
begin
  if v_uid is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from private.contract_invitation(p_link_id, null, p_tenant_slug);
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;
  perform 1 from public.events where tenant_id = i.tenant_id and id = i.event_id for update;
  select * into i from private.contract_invitation(p_link_id, null, p_tenant_slug);
  if not i.usable then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified');
  end if;
  if v_email <> lower(i.signer_email) then
    return jsonb_build_object('state', 'wrong_account');
  end if;
  if not exists (select 1 from public.event_clients ec where ec.tenant_id = i.tenant_id and ec.event_id = i.event_id
                 and ec.client_id = i.signer_client_id) then
    return jsonb_build_object('state', 'invalid');
  end if;

  select ea.client_id into v_existing from public.event_access ea
  where ea.tenant_id = i.tenant_id and ea.event_id = i.event_id and ea.user_id = v_uid and ea.revoked_at is null;
  if found and v_existing.client_id <> i.signer_client_id then
    return jsonb_build_object('state', 'invalid');
  end if;
  if not found then
    insert into public.event_access (tenant_id, event_id, client_id, user_id)
    values (i.tenant_id, i.event_id, i.signer_client_id, v_uid);
    perform private.audit(i.tenant_id, 'event', i.event_id, 'client_access_granted', 'client', v_uid,
      jsonb_build_object('contract_id', i.contract_id, 'invitation_id', i.link_id));
  end if;
  update public.access_links set consumed_at = now() where id = i.link_id and consumed_at is null;
  return jsonb_build_object('state', 'accepted', 'contract_id', i.contract_id);
end;
$$;


ALTER FUNCTION "public"."accept_contract_invitation"("p_link_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_planning_invitation"("p_invitation_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i record;
  v_uid uuid := (select auth.uid());
  v_email text;
  v_existing record;
begin
  if v_uid is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from private.planning_invitation(p_invitation_id, null, p_tenant_slug);
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;
  -- Lock order: event, then invitation.
  perform 1 from public.events where tenant_id = i.tenant_id and id = i.event_id for update;
  perform 1 from public.planning_invitations where id = i.invitation_id for update;
  select * into i from private.planning_invitation(p_invitation_id, null, p_tenant_slug);
  if not i.usable then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified');
  end if;
  if v_email <> i.email then
    return jsonb_build_object('state', 'wrong_account');
  end if;

  select ea.client_id into v_existing from public.event_access ea
  where ea.tenant_id = i.tenant_id and ea.event_id = i.event_id and ea.user_id = v_uid and ea.revoked_at is null;
  if found and v_existing.client_id <> i.client_id then
    return jsonb_build_object('state', 'invalid');
  end if;
  if not found then
    insert into public.event_access (tenant_id, event_id, client_id, user_id)
    values (i.tenant_id, i.event_id, i.client_id, v_uid);
    perform private.audit(i.tenant_id, 'event', i.event_id, 'client_access_granted', 'client', v_uid,
      jsonb_build_object('planning_invitation_id', i.invitation_id));
  end if;
  update public.planning_invitations set accepted_at = now(), accepted_by = v_uid
    where id = i.invitation_id and accepted_at is null;
  return jsonb_build_object('state', 'accepted', 'event_id', i.event_id);
end;
$$;


ALTER FUNCTION "public"."accept_planning_invitation"("p_invitation_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_platform_invitation"("p_invitation_id" "uuid", "p_display_name" "text", "p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.platform_invitations%rowtype;
  v_uid uuid := (select auth.uid());
  v_email text;
  v_name text := btrim(regexp_replace(coalesce(p_display_name, ''), '\s+', ' ', 'g'));
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  v_tenant uuid;
  v_existing_slug text;
begin
  if v_uid is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from public.platform_invitations where id = p_invitation_id for update;
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;
  if i.accepted_at is not null then
    if i.accepted_by <> v_uid then
      return jsonb_build_object('state', 'invalid');
    end if;
    select t.slug into v_existing_slug from public.tenants t where t.id = i.tenant_id;
    return jsonb_build_object('state', 'created', 'slug', v_existing_slug, 'replayed', true);
  end if;
  if i.revoked_at is not null or i.expires_at <= now() then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified');
  end if;
  if v_email <> i.email then
    return jsonb_build_object('state', 'wrong_account');
  end if;

  if length(v_name) not between 2 and 100 or v_name ~ '[[:cntrl:]]' then
    return jsonb_build_object('state', 'name_invalid');
  end if;
  if not private.is_claimable_tenant_slug(v_slug) then
    return jsonb_build_object('state', 'slug_invalid');
  end if;
  begin
    -- The legal name is unknown until the owner enters it in Business
    -- settings; the display name stands in (the column is required). Address
    -- and contact email stay empty, which keeps contracts unsendable
    -- (business_settings_incomplete) until the owner saves those settings.
    insert into public.tenants (slug, business_name, display_name)
    values (v_slug, v_name, v_name)
    returning id into v_tenant;
  exception when unique_violation then
    return jsonb_build_object('state', 'slug_taken');
  end;
  insert into public.tenant_memberships (tenant_id, user_id, role) values (v_tenant, v_uid, 'owner');
  update public.platform_invitations
    set accepted_at = now(), accepted_by = v_uid, tenant_id = v_tenant
    where id = i.id;
  perform private.cancel_platform_invitation_emails(i.id, 'invitation accepted');
  perform private.platform_audit('platform_invitation', i.id, 'accepted', v_uid, jsonb_build_object('tenant_id', v_tenant, 'slug', v_slug));
  perform private.audit(v_tenant, 'tenant', v_tenant, 'created', 'staff', v_uid, jsonb_build_object('platform_invitation_id', i.id));
  return jsonb_build_object('state', 'created', 'slug', v_slug, 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."accept_platform_invitation"("p_invitation_id" "uuid", "p_display_name" "text", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_staff_invitation"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.staff_invitations%rowtype;
  t public.tenants%rowtype;
  m public.tenant_memberships%rowtype;
  v_uid uuid := (select auth.uid());
  v_email text;
  v_outcome text;
begin
  if v_uid is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from public.staff_invitations where id = p_invitation_id for update;
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;
  select * into t from public.tenants where id = i.tenant_id;
  if i.accepted_at is not null then
    if i.accepted_by <> v_uid then
      return jsonb_build_object('state', 'invalid');
    end if;
    return jsonb_build_object('state', 'accepted', 'slug', t.slug, 'replayed', true);
  end if;
  if i.revoked_at is not null or i.expires_at <= now() then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified');
  end if;
  if v_email <> i.email then
    return jsonb_build_object('state', 'wrong_account');
  end if;
  if t.suspended_at is not null or t.archived_at is not null then
    return jsonb_build_object('state', 'unavailable');
  end if;

  select * into m from public.tenant_memberships where tenant_id = i.tenant_id and user_id = v_uid for update;
  if not found then
    insert into public.tenant_memberships (tenant_id, user_id, role) values (i.tenant_id, v_uid, 'staff') returning * into m;
    v_outcome := 'joined';
  elsif m.removed_at is not null then
    update public.tenant_memberships set removed_at = null, removed_by = null where id = m.id;
    v_outcome := 'restored';
  else
    v_outcome := 'already_member';
  end if;
  update public.staff_invitations set accepted_at = now(), accepted_by = v_uid, membership_id = m.id where id = i.id;
  perform private.cancel_staff_invitation_emails(i.id, 'invitation accepted');
  perform private.audit(i.tenant_id, 'staff_invitation', i.id, 'accepted', 'staff', v_uid,
    jsonb_build_object('membership_id', m.id, 'outcome', v_outcome));
  return jsonb_build_object('state', 'accepted', 'slug', t.slug, 'replayed', false, 'outcome', v_outcome);
end;
$$;


ALTER FUNCTION "public"."accept_staff_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_event_contact"("p_event_id" "uuid", "p_client_id" "uuid", "p_make_primary" boolean DEFAULT false, "p_make_signer" boolean DEFAULT false, "p_expected_primary_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  c public.clients%rowtype;
  v_primary uuid;
  v_id uuid;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  -- One contact change per event at a time: concurrent requests queue here.
  select * into e from public.events where id = p_event_id for update;

  select * into c from public.clients where tenant_id = e.tenant_id and id = p_client_id;
  if not found then
    raise exception 'contact_invalid: that client wasn''t found in this business' using errcode = 'invalid_parameter_value';
  end if;
  if c.archived_at is not null then
    raise exception 'contact_invalid: that client is archived; restore them first or choose another client' using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from public.event_clients ec where ec.tenant_id = e.tenant_id and ec.event_id = e.id and ec.client_id = c.id) then
    raise exception 'contact_invalid: % is already a contact on this event', c.name using errcode = 'invalid_parameter_value';
  end if;

  if coalesce(p_make_primary, false) then
    select ec.client_id into v_primary from public.event_clients ec where ec.tenant_id = e.tenant_id and ec.event_id = e.id and ec.is_primary;
    if v_primary is distinct from p_expected_primary_client_id then
      raise exception 'contact_conflict: the primary contact changed since this page was loaded; reload and try again' using errcode = 'PT409';
    end if;
    update public.event_clients set is_primary = false where tenant_id = e.tenant_id and event_id = e.id and is_primary;
  end if;
  if coalesce(p_make_signer, false) then
    update public.event_clients set can_sign = false where tenant_id = e.tenant_id and event_id = e.id and can_sign;
  end if;
  insert into public.event_clients (tenant_id, event_id, client_id, is_primary, can_sign)
  values (e.tenant_id, e.id, c.id, coalesce(p_make_primary, false), coalesce(p_make_signer, false))
  returning id into v_id;

  perform private.audit(e.tenant_id, 'event', e.id, 'contact_added', 'staff', (select auth.uid()),
    jsonb_build_object('client_id', c.id, 'primary', coalesce(p_make_primary, false), 'signer', coalesce(p_make_signer, false)));
  return jsonb_build_object('event_client_id', v_id);
end;
$$;


ALTER FUNCTION "public"."add_event_contact"("p_event_id" "uuid", "p_client_id" "uuid", "p_make_primary" boolean, "p_make_signer" boolean, "p_expected_primary_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_event_contact"("p_event_id" "uuid", "p_client_id" "uuid", "p_make_primary" boolean, "p_make_signer" boolean, "p_expected_primary_client_id" "uuid") IS 'Adds a client to an event (optionally as primary contact and/or signer) atomically, under the event lock. Staff of the business only.';



CREATE OR REPLACE FUNCTION "public"."add_event_plan_item"("p_event_id" "uuid", "p_expected_version" integer, "p_key" "text", "p_parent_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.event_plans%rowtype;
  v_lib record;
  v_existing public.event_plan_items%rowtype;
  v_parent public.event_plan_items%rowtype;
begin
  p := private.lock_plan_for_staff(p_event_id, p_expected_version);
  select * into v_lib from private.planning_library() l where l.key = p_key;
  if not found then
    perform private.planning_error('choose an item from the library');
  end if;
  select * into v_existing from public.event_plan_items i where i.plan_id = p.id and i.key = p_key;
  if found then
    if v_existing.disabled_at is null then
      perform private.planning_error('this item is already in the plan');
    end if;
    update public.event_plan_items set disabled_at = null where id = v_existing.id;
    return private.bump_plan_structure(p.id, 'restored', p_key);
  end if;
  if v_lib.kind = 'moment' then
    select * into v_parent from public.event_plan_items i where i.plan_id = p.id and i.key = p_parent_key and i.kind = 'stage';
    if not found or not (p_parent_key = any (v_lib.parent_keys)) then
      perform private.planning_error('add the moment to a stage it belongs to');
    end if;
  end if;
  insert into public.event_plan_items (tenant_id, plan_id, kind, key, parent_id, label, position)
  values (p.tenant_id, p.id, v_lib.kind, v_lib.key, v_parent.id, v_lib.default_label,
    (select coalesce(max(s.position), 0) + 1 from public.event_plan_items s
     where s.plan_id = p.id and s.kind = v_lib.kind and s.parent_id is not distinct from v_parent.id));
  return private.bump_plan_structure(p.id, 'added', p_key);
end;
$$;


ALTER FUNCTION "public"."add_event_plan_item"("p_event_id" "uuid", "p_expected_version" integer, "p_key" "text", "p_parent_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_planning_template_item"("p_template_id" "uuid", "p_expected_version" integer, "p_key" "text", "p_parent_key" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  t public.planning_templates%rowtype;
  v_lib record;
  v_parent public.planning_template_items%rowtype;
begin
  t := private.lock_planning_template(p_template_id, p_expected_version);
  select * into v_lib from private.planning_library() l where l.key = p_key;
  if not found then
    perform private.planning_error('choose an item from the library');
  end if;
  if exists (select 1 from public.planning_template_items i where i.template_id = t.id and i.key = p_key) then
    perform private.planning_error('this item is already in the template');
  end if;
  if v_lib.kind = 'moment' then
    select * into v_parent from public.planning_template_items i where i.template_id = t.id and i.key = p_parent_key and i.kind = 'stage';
    if not found or not (p_parent_key = any (v_lib.parent_keys)) then
      perform private.planning_error('add the moment to a stage it belongs to');
    end if;
  end if;
  insert into public.planning_template_items (tenant_id, template_id, kind, key, parent_id, label, position)
  values (t.tenant_id, t.id, v_lib.kind, v_lib.key, v_parent.id, v_lib.default_label,
    (select coalesce(max(s.position), 0) + 1 from public.planning_template_items s
     where s.template_id = t.id and s.kind = v_lib.kind and s.parent_id is not distinct from v_parent.id));
  return private.bump_planning_template(t.id);
end;
$$;


ALTER FUNCTION "public"."add_planning_template_item"("p_template_id" "uuid", "p_expected_version" integer, "p_key" "text", "p_parent_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_event_plan_template"("p_event_id" "uuid", "p_template_id" "uuid", "p_expected_version" integer, "p_confirm" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.event_plans%rowtype;
  t public.planning_templates%rowtype;
  v_added int := 0;
  v_kept int := 0;
  v_hidden int := 0;
  v_count int;
  g record;
begin
  p := private.lock_plan_for_staff(p_event_id, p_expected_version);
  select * into t from public.planning_templates where tenant_id = p.tenant_id and id = p_template_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if t.archived_at is not null then
    perform private.planning_error('this template is archived. Unarchive it or choose another');
  end if;
  if p_confirm is not true then
    perform private.planning_error('confirm that you want to replace the planning structure');
  end if;

  -- Top level, then moments (their stages exist by then).
  update public.event_plan_items i
    set label = ti.label, position = ti.position, disabled_at = null
    from public.planning_template_items ti
    where ti.template_id = t.id and ti.parent_id is null and i.plan_id = p.id and i.key = ti.key;
  get diagnostics v_count = row_count;
  v_kept := v_kept + v_count;
  insert into public.event_plan_items (tenant_id, plan_id, kind, key, label, position, source_template_item_id)
  select p.tenant_id, p.id, ti.kind, ti.key, ti.label, ti.position, ti.id
  from public.planning_template_items ti
  where ti.template_id = t.id and ti.parent_id is null
    and not exists (select 1 from public.event_plan_items i where i.plan_id = p.id and i.key = ti.key);
  get diagnostics v_count = row_count;
  v_added := v_added + v_count;

  update public.event_plan_items i
    set label = ti.label, position = ti.position, disabled_at = null, parent_id = pi.id
    from public.planning_template_items ti
    join public.planning_template_items tp on tp.id = ti.parent_id
    join public.event_plan_items pi on pi.plan_id = p.id and pi.key = tp.key
    where ti.template_id = t.id and i.plan_id = p.id and i.key = ti.key;
  get diagnostics v_count = row_count;
  v_kept := v_kept + v_count;
  insert into public.event_plan_items (tenant_id, plan_id, kind, key, parent_id, label, position, source_template_item_id)
  select p.tenant_id, p.id, ti.kind, ti.key, pi.id, ti.label, ti.position, ti.id
  from public.planning_template_items ti
  join public.planning_template_items tp on tp.id = ti.parent_id
  join public.event_plan_items pi on pi.plan_id = p.id and pi.key = tp.key
  where ti.template_id = t.id
    and not exists (select 1 from public.event_plan_items i where i.plan_id = p.id and i.key = ti.key);
  get diagnostics v_count = row_count;
  v_added := v_added + v_count;

  -- Everything else is hidden, after the template's items, in its old order.
  update public.event_plan_items i
    set disabled_at = coalesce(i.disabled_at, now()), position = least(10000, 5000 + i.position)
    where i.plan_id = p.id and i.key <> 'basics'
      and not exists (select 1 from public.planning_template_items ti where ti.template_id = t.id and ti.key = i.key);
  get diagnostics v_hidden = row_count;
  for g in select distinct i.parent_id, i.kind from public.event_plan_items i where i.plan_id = p.id loop
    perform private.renumber_plan_siblings(p.id, g.parent_id, g.kind);
  end loop;

  update public.event_plans
    set source_template_id = t.id, source_template_name = t.name, source_template_version = t.version, origin = 'template',
        structure_version = structure_version + 1
    where id = p.id returning * into p;
  perform private.audit(p.tenant_id, 'event', p.event_id, 'planning_template_applied', 'staff', (select auth.uid()),
    jsonb_build_object('plan_id', p.id, 'template_id', t.id, 'kept', v_kept, 'added', v_added, 'hidden', v_hidden));
  return jsonb_build_object('status', 'applied', 'structure_version', p.structure_version,
                            'kept', v_kept, 'added', v_added, 'hidden', v_hidden);
end;
$$;


ALTER FUNCTION "public"."apply_event_plan_template"("p_event_id" "uuid", "p_template_id" "uuid", "p_expected_version" integer, "p_confirm" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_proposal_selection"("p_proposal_id" "uuid", "p_selection_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_proposal public.proposals%rowtype;
  v_event public.events%rowtype;
  v_membership_id uuid;
  v_selection public.proposal_selections%rowtype;
  v_existing record;
  v_client record;
  v_approval_id uuid;
begin
  select * into v_proposal from public.proposals where id = p_proposal_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(v_proposal.tenant_id);
  select * into v_event from public.events where tenant_id = v_proposal.tenant_id and id = v_proposal.event_id for update;
  select * into v_proposal from public.proposals where id = p_proposal_id for update;

  select a.id, a.selection_id into v_existing from public.proposal_approvals a where a.proposal_id = p_proposal_id;
  if found then
    if v_existing.selection_id = p_selection_id then
      return jsonb_build_object('status', 'approved', 'approval_id', v_existing.id, 'replayed', true);
    end if;
    raise exception 'this proposal was already approved with a different selection' using errcode = 'invalid_parameter_value';
  end if;
  if v_proposal.status <> 'submitted' or v_event.active_proposal_id is distinct from v_proposal.id then
    raise exception 'only the current, submitted proposal can be approved' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_selection from public.proposal_selections
  where tenant_id = v_proposal.tenant_id and proposal_id = v_proposal.id and id = p_selection_id;
  if not found or v_selection.version <> v_proposal.current_selection_version then
    raise exception 'approve the latest submitted selection' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.proposal_approvals (tenant_id, proposal_id, selection_id, approved_by_membership_id, approved_by_user_id, selection_sha256)
  values (v_proposal.tenant_id, v_proposal.id, v_selection.id, v_membership_id, (select auth.uid()),
          encode(pg_catalog.sha256(convert_to(v_selection.selection_snapshot::text, 'UTF8')), 'hex'))
  returning id into v_approval_id;

  update public.proposals set status = 'approved' where id = v_proposal.id;
  update public.events set lifecycle_status = 'awaiting_signature'
    where id = v_event.id and lifecycle_status in ('lead', 'pending_approval');

  select c.name, c.email into v_client
  from public.access_links l join public.clients c on c.tenant_id = l.tenant_id and c.id = l.intended_client_id
  where l.tenant_id = v_proposal.tenant_id and l.proposal_id = v_proposal.id and l.purpose = 'proposal'
  order by l.created_at desc limit 1;

  perform private.enqueue_email(
    v_proposal.tenant_id, 'proposal_approved', v_client.email, v_proposal.id, null,
    jsonb_build_object('event_title', v_event.title, 'client_name', v_client.name,
                       'total_cents', v_selection.total_cents, 'currency', v_selection.currency),
    'proposal_approved:' || v_proposal.id
  );
  perform private.audit(v_proposal.tenant_id, 'proposal', v_proposal.id, 'approved', 'staff', (select auth.uid()),
    jsonb_build_object('selection_id', v_selection.id));

  return jsonb_build_object('status', 'approved', 'approval_id', v_approval_id, 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."approve_proposal_selection"("p_proposal_id" "uuid", "p_selection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_email_outbox"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.email_outbox
    set status = 'cancelled', last_error = left(coalesce(p_reason, 'cancelled'), 1000), locked_until = null
    where id = p_id and status in ('pending', 'sending');
$$;


ALTER FUNCTION "public"."cancel_email_outbox"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.staff_invitations%rowtype;
begin
  perform private.require_owner_of(p_tenant_id);
  select * into i from public.staff_invitations where tenant_id = p_tenant_id and id = p_invitation_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if i.revoked_at is not null then
    return jsonb_build_object('status', 'cancelled', 'replayed', true);
  end if;
  if i.accepted_at is not null then
    raise exception 'invitation_not_cancellable: this invitation was already accepted. Remove the staff member instead'
      using errcode = 'invalid_parameter_value';
  end if;
  update public.staff_invitations set revoked_at = now(), revoked_by = (select auth.uid()) where id = i.id;
  perform private.cancel_staff_invitation_emails(i.id, 'invitation cancelled');
  perform private.audit(p_tenant_id, 'staff_invitation', i.id, 'cancelled', 'staff', (select auth.uid()), '{}'::jsonb);
  return jsonb_build_object('status', 'cancelled', 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."cancel_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_event_booking"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from public.events where id = p_event_id;
  if v_tenant is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_tenant);
  return private.evaluate_booking(p_event_id, 'staff', (select auth.uid()), true);
end;
$$;


