CREATE OR REPLACE FUNCTION "public"."claim_platform_email_outbox"("p_limit" integer DEFAULT 10, "p_lock_seconds" integer DEFAULT 120, "p_invitation_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "event_type" "text", "recipient_email" "text", "payload" "jsonb", "attempts" integer, "invitation_id" "uuid", "link_id" "uuid", "token_hash" "text", "deliverable" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
begin
  update public.email_outbox o
    set status = 'failed', locked_until = null, last_error = coalesce(o.last_error, 'delivery did not complete')
