CREATE OR REPLACE FUNCTION "public"."client_approved_offer"("p_contract_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  v_result jsonb;
begin
  select k.* into c from public.contracts k join public.tenants t on t.id = k.tenant_id
  where k.id = p_contract_id and t.slug = p_tenant_slug;
  if not found or not private.client_can_read_contract(c.id) then
    return jsonb_build_object('state', 'unavailable');
  end if;

  select jsonb_build_object(
    'state', 'available',
    'event_id', c.event_id,
    'contract', jsonb_build_object('id', c.id, 'status', c.status, 'signed_at', c.signed_at),
    'proposal', jsonb_build_object('revision', p.revision, 'offer_sha256', p.offer_sha256, 'offer', p.offer_snapshot),
    'selection', jsonb_build_object('version', s.version, 'submitted_at', s.submitted_at, 'priced', s.selection_snapshot),
    'approved_at', a.approved_at,
    -- The contract's frozen terms (what was signed), never recomputed.
    'agreed', jsonb_build_object(
      'currency', c.commercial_snapshot -> 'currency',
      'subtotal_cents', c.commercial_snapshot -> 'subtotal_cents',
      'tax_breakdown', c.commercial_snapshot -> 'tax_breakdown',
      'tax_cents', c.commercial_snapshot -> 'tax_cents',
      'total_cents', c.commercial_snapshot -> 'total_cents',
      'discount', c.commercial_snapshot -> 'discount',
      'discounted_subtotal_cents', c.commercial_snapshot -> 'discounted_subtotal_cents'))
  into v_result
  from public.proposals p
  join public.proposal_selections s on s.tenant_id = c.tenant_id and s.proposal_id = p.id and s.id = c.selection_id
  join public.proposal_approvals a on a.tenant_id = c.tenant_id and a.proposal_id = p.id and a.id = c.approval_id and a.selection_id = s.id
  where p.tenant_id = c.tenant_id and p.id = c.proposal_id;

  return coalesce(v_result, jsonb_build_object('state', 'unavailable'));
end;
$$;


ALTER FUNCTION "public"."client_approved_offer"("p_contract_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."client_approved_offer"("p_contract_id" "uuid", "p_tenant_slug" "text") IS 'The offer and selection a contract was built from, for its signer only (client_can_read_contract). Read-only, frozen data.';



CREATE OR REPLACE FUNCTION "public"."client_contract_view"("p_contract_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  t public.tenants%rowtype;
  s public.contract_signatures%rowtype;
begin
  select k.* into c from public.contracts k join public.tenants tt on tt.id = k.tenant_id
  where k.id = p_contract_id and tt.slug = p_tenant_slug;
  if not found or not private.client_can_read_contract(c.id) then
    return jsonb_build_object('state', 'unavailable');
  end if;
  select * into t from public.tenants where id = c.tenant_id;
  select * into s from public.contract_signatures where contract_id = c.id;
  return jsonb_build_object(
    'state', 'available',
    'brand', jsonb_build_object('display_name', t.display_name, 'brand_colors', t.brand_colors),
    'contract', jsonb_build_object(
      'id', c.id, 'status', c.status, 'sent_at', c.sent_at, 'content_sha256', c.content_sha256, 'rendered_content', c.rendered_content,
      'signer_name', c.signer_name, 'currency', c.currency, 'total_cents', c.total_cents,
      'deposit_percent', c.deposit_percent, 'deposit_cents', c.deposit_cents, 'balance_cents', c.balance_cents,
      'balance_due_date', c.balance_due_date, 'signing_mode', c.signing_mode,
      'event_title', c.party_snapshot -> 'event' ->> 'title', 'event_date', c.party_snapshot -> 'event' ->> 'date',
      'legal_name', coalesce(c.party_snapshot -> 'business' ->> 'legal_name', c.party_snapshot -> 'business' ->> 'name')),
    'signing', case when c.status = 'signed' then
        jsonb_build_object('signed', true, 'typed_name', s.typed_name, 'signed_at', s.signed_at,
          'pdf_ready', exists (select 1 from public.contract_documents d where d.contract_id = c.id and d.kind = 'signed_contract'),
          'pdf_pending', exists (select 1 from public.document_jobs j where j.contract_id = c.id and j.status in ('pending', 'running')))
      else
        jsonb_build_object('signed', false, 'enabled', c.signing_mode <> 'none',
          'consent_version', c.consent_version,
          'consent_text', private.contract_signing_consent(c.consent_version))
      end
  );
end;
$$;


ALTER FUNCTION "public"."client_contract_view"("p_contract_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_invitation_status"("p_link_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i record;
  v_email text;
begin
  if (select auth.uid()) is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from private.contract_invitation(p_link_id, null, p_tenant_slug);
  if not found or not i.usable then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified', 'tenant_display_name', i.tenant_display_name);
  end if;
  if v_email <> lower(i.signer_email) then
    return jsonb_build_object('state', 'wrong_account', 'tenant_display_name', i.tenant_display_name,
      'signed_in_email', v_email, 'intended_email', private.masked_email(i.signer_email));
  end if;
  return jsonb_build_object(
    'state', case when exists (
      select 1 from public.event_access ea where ea.tenant_id = i.tenant_id and ea.event_id = i.event_id
        and ea.user_id = (select auth.uid()) and ea.client_id = i.signer_client_id and ea.revoked_at is null)
      then 'accepted' else 'ready' end,
    'tenant_display_name', i.tenant_display_name, 'event_title', i.event_title, 'signer_name', i.signer_name,
    'contract_id', i.contract_id);
end;
$$;


ALTER FUNCTION "public"."client_invitation_status"("p_link_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_payment_summary"("p_contract_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  s jsonb;
begin
  select k.* into c from public.contracts k join public.tenants t on t.id = k.tenant_id
  where k.id = p_contract_id and t.slug = p_tenant_slug;
  if not found or not private.client_can_read_contract(c.id) then
    return null;
  end if;
  s := private.event_payment_summary(c.event_id);
  return jsonb_build_object(
    'currency', s ->> 'currency',
    'terms_status', s -> 'terms' ->> 'status',
    'total_cents', s -> 'terms' -> 'total_cents',
    'deposit_percent', s -> 'terms' -> 'deposit_percent',
    'deposit_cents', s -> 'terms' -> 'deposit_cents',
    'balance_due_date', s -> 'terms' -> 'balance_due_date',
    'received_cents', s -> 'received_cents',
    'deposit_outstanding_cents', s -> 'deposit_outstanding_cents',
    'remaining_balance_cents', s -> 'remaining_balance_cents',
    'credit_cents', s -> 'credit_cents',
    'invoice_url', s -> 'invoice_url',
    'booking_status', case s -> 'booking' ->> 'lifecycle_status' when 'booked' then 'booked' when 'awaiting_deposit' then 'awaiting_deposit' end
  )
  -- The viewed contract's frozen price breakdown, only when it has a discount.
  || case when c.commercial_snapshot ? 'discount' then jsonb_build_object('pricing', jsonb_build_object(
       'subtotal_cents', c.commercial_snapshot -> 'subtotal_cents',
       'discount', c.commercial_snapshot -> 'discount',
       'discounted_subtotal_cents', c.commercial_snapshot -> 'discounted_subtotal_cents',
       'tax_breakdown', (select coalesce(jsonb_agg(jsonb_build_object('label', t ->> 'label', 'rate_ppm', t -> 'rate_ppm', 'amount_cents', t -> 'amount_cents') order by ord), '[]'::jsonb)
                         from jsonb_array_elements(c.commercial_snapshot -> 'tax_breakdown') with ordinality as x(t, ord)),
       'total_cents', c.commercial_snapshot -> 'total_cents'))
     else '{}'::jsonb end;
end;
$$;


ALTER FUNCTION "public"."client_payment_summary"("p_contract_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_planning_invitation_status"("p_invitation_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i record;
  v_email text;
begin
  if (select auth.uid()) is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from private.planning_invitation(p_invitation_id, null, p_tenant_slug);
  if not found or not i.usable then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified', 'tenant_display_name', i.tenant_display_name);
  end if;
  if v_email <> i.email then
    return jsonb_build_object('state', 'wrong_account', 'tenant_display_name', i.tenant_display_name,
      'signed_in_email', v_email, 'intended_email', private.masked_email(i.email));
  end if;
  return jsonb_build_object(
    'state', case when exists (
      select 1 from public.event_access ea where ea.tenant_id = i.tenant_id and ea.event_id = i.event_id
        and ea.user_id = (select auth.uid()) and ea.client_id = i.client_id and ea.revoked_at is null)
      then 'accepted' else 'ready' end,
    'tenant_display_name', i.tenant_display_name, 'event_title', i.event_title, 'event_date', i.event_date,
    'client_name', i.client_name, 'event_id', i.event_id);
end;
$$;


ALTER FUNCTION "public"."client_planning_invitation_status"("p_invitation_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_planning_view"("p_event_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  t public.tenants%rowtype;
  v_plan public.event_plans%rowtype;
  v_basics record;
begin
  select ev.* into e from public.events ev join public.tenants tt on tt.id = ev.tenant_id
  where ev.id = p_event_id and tt.slug = p_tenant_slug;
  if not found or not private.client_can_access_plan(e.id) then
    return jsonb_build_object('state', 'unavailable');
  end if;
  select * into t from public.tenants where id = e.tenant_id;
  select * into v_plan from public.event_plans where tenant_id = e.tenant_id and event_id = e.id;
  if private.plan_awaiting_setup(v_plan) then
    return jsonb_build_object(
      'state', 'setting_up',
      'brand', jsonb_build_object('display_name', t.display_name, 'brand_colors', t.brand_colors),
      'event', jsonb_build_object('id', e.id, 'title', e.title, 'event_type', e.event_type, 'event_date', e.event_date,
                                  'timezone', e.timezone, 'venue_name', e.venue_name, 'venue_address', e.venue_address));
  end if;
  select i.id, r.answers, r.revision into v_basics
  from public.event_plan_items i left join public.event_plan_responses r on r.tenant_id = i.tenant_id and r.item_id = i.id
  where i.plan_id = v_plan.id and i.key = 'basics';
  return jsonb_build_object(
    'state', 'available',
    'brand', jsonb_build_object('display_name', t.display_name, 'brand_colors', t.brand_colors),
    'dj_name', coalesce(e.dj_name, t.dj_name),
    'event', jsonb_build_object('id', e.id, 'title', e.title, 'event_type', e.event_type, 'event_date', e.event_date,
                                'timezone', e.timezone, 'venue_name', e.venue_name, 'venue_address', e.venue_address),
    'editing', private.plan_client_editing(e, v_plan, now()),
    'structure', private.plan_structure(v_plan.id, false),
    'basics', jsonb_build_object('item_id', v_basics.id, 'answers', coalesce(v_basics.answers, '{}'::jsonb),
                                 'revision', coalesce(v_basics.revision, 0)),
    'stage_details', private.plan_stage_details(v_plan.id),
    'music', private.plan_music(v_plan.id),
    'moments', private.plan_moment_answers(v_plan.id),
    'event_contacts', private.plan_event_contacts(v_plan.id),
    'timeline_warnings', private.plan_timeline_warnings(v_plan.id),
    'imported', private.plan_latest_import(v_plan.id),
    'progress', private.plan_progress(v_plan.id));
end;
$$;


ALTER FUNCTION "public"."client_planning_view"("p_event_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_proposal_view"("p_session_hash" "text", "p_proposal_id" "uuid", "p_tenant_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s record;
  v jsonb;
begin
  select * into s from private.resolve_proposal_session(p_session_hash, p_proposal_id, p_tenant_slug);
  if s.state in ('invalid', 'superseded', 'unavailable') then
    return jsonb_build_object('state', s.state);
  end if;

  select jsonb_build_object(
    'state', s.state,
    'tenant', jsonb_build_object('slug', t.slug, 'display_name', t.display_name),
    'event', jsonb_build_object('title', e.title, 'event_date', e.event_date, 'venue_name', e.venue_name, 'timezone', e.timezone),
    'proposal', jsonb_build_object(
      'id', p.id, 'revision', p.revision, 'sent_at', p.sent_at, 'expires_at', p.expires_at,
      'offer_sha256', p.offer_sha256, 'offer', p.offer_snapshot
    ),
    'selection_draft', (
      select jsonb_build_object('package_key', d.package_key, 'addon_quantities', d.addon_quantities,
                                'logistics_answers', d.logistics_answers, 'version', d.version)
      from public.proposal_selection_drafts d where d.proposal_id = p.id
    ),
    'submission', (
      select jsonb_build_object('version', ps.version, 'submitted_at', ps.submitted_at, 'selection', ps.selection_snapshot)
      from public.proposal_selections ps where ps.proposal_id = p.id order by ps.version desc limit 1
    ),
    'approved_at', (select a.approved_at from public.proposal_approvals a where a.proposal_id = p.id)
  ) into v
  from public.proposals p
  join public.events e on e.tenant_id = p.tenant_id and e.id = p.event_id
  join public.tenants t on t.id = p.tenant_id
  where p.id = s.proposal_id;
  return v;
end;
$$;


ALTER FUNCTION "public"."client_proposal_view"("p_session_hash" "text", "p_proposal_id" "uuid", "p_tenant_slug" "text") OWNER TO "postgres";


