CREATE OR REPLACE FUNCTION "public"."create_package"("p_tenant_id" "uuid", "p_package_id" "uuid", "p_key" "text", "p_name" "text", "p_description" "text", "p_base_price_cents" bigint, "p_tax_category" "text", "p_sort_order" integer, "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_existing uuid;
  v_inserted uuid;
begin
  perform private.require_staff_of(p_tenant_id);
  if p_package_id is null then
    raise exception 'package_invalid: a request id is required' using errcode = 'invalid_parameter_value';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or exists (
       select 1 from jsonb_array_elements(p_items) i
       where jsonb_typeof(i) <> 'object'
          or exists (select 1 from jsonb_object_keys(i) k where k not in ('gear_item_id', 'quantity', 'sort_order'))
          or coalesce(i ->> 'gear_item_id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or jsonb_typeof(i -> 'quantity') is distinct from 'number'
          or (i ->> 'quantity') !~ '^[0-9]+$'
          or (i ? 'sort_order' and (jsonb_typeof(i -> 'sort_order') <> 'number' or (i ->> 'sort_order') !~ '^[0-9]{1,5}$'))
     ) then
    raise exception 'package_invalid: items need a gear_item_id and a whole quantity' using errcode = 'invalid_parameter_value';
  end if;

  -- A retry of a request that already succeeded (its response was lost).
  select tenant_id into v_existing from public.packages where id = p_package_id;
  if found then
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_package_id, 'replayed', true);
  end if;

  insert into public.packages (id, tenant_id, key, name, description, base_price_cents, tax_category, sort_order)
  values (p_package_id, p_tenant_id, p_key, p_name, p_description, p_base_price_cents, p_tax_category, p_sort_order)
  on conflict (id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    -- The same request, committed concurrently.
    select tenant_id into v_existing from public.packages where id = p_package_id;
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_package_id, 'replayed', true);
  end if;

  insert into public.package_items (tenant_id, package_id, gear_item_id, quantity, sort_order)
  select p_tenant_id, p_package_id, (i ->> 'gear_item_id')::uuid, (i ->> 'quantity')::int, coalesce((i ->> 'sort_order')::int, 0)
  from jsonb_array_elements(p_items) i;

  return jsonb_build_object('id', p_package_id, 'replayed', false);
end;
$_$;


ALTER FUNCTION "public"."create_package"("p_tenant_id" "uuid", "p_package_id" "uuid", "p_key" "text", "p_name" "text", "p_description" "text", "p_base_price_cents" bigint, "p_tax_category" "text", "p_sort_order" integer, "p_items" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_package"("p_tenant_id" "uuid", "p_package_id" "uuid", "p_key" "text", "p_name" "text", "p_description" "text", "p_base_price_cents" bigint, "p_tax_category" "text", "p_sort_order" integer, "p_items" "jsonb") IS 'Creates a package and its included gear atomically (staff of the business). An id that already exists in the business returns that package as replayed.';



CREATE OR REPLACE FUNCTION "public"."create_planning_template"("p_tenant_id" "uuid", "p_name" "text", "p_description" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d record;
  v_id uuid;
begin
  perform private.require_staff_of(p_tenant_id);
  select * into d from private.planning_template_details(p_name, p_description);
  insert into public.planning_templates (tenant_id, name, description) values (p_tenant_id, d.name, d.description)
  returning id into v_id;
  insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
  select p_tenant_id, v_id, l.kind, l.key, l.default_label, 1 from private.planning_library() l where l.key = 'basics';
  perform private.audit(p_tenant_id, 'planning_template', v_id, 'created', 'staff', (select auth.uid()), '{}'::jsonb);
  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_planning_template"("p_tenant_id" "uuid", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_planning_template_from_starter"("p_tenant_id" "uuid", "p_starter" "text", "p_name" "text", "p_description" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d record;
  v_id uuid;
begin
  perform private.require_staff_of(p_tenant_id);
  if p_starter is null or p_starter not in ('wedding', 'simple_party') then
    perform private.planning_error('choose the Wedding or Simple Party outline');
  end if;
  select * into d from private.planning_template_details(
    p_name,
    coalesce(nullif(btrim(coalesce(p_description, '')), ''),
      case p_starter
        when 'wedding' then 'Ceremony to closing, in the order of the day. Rename or remove anything a couple doesn''t need.'
        else 'Event basics plus must-play and do-not-play songs. For birthdays and other simple parties.' end));
  insert into public.planning_templates (tenant_id, name, description) values (p_tenant_id, d.name, d.description)
  returning id into v_id;
  insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
  select p_tenant_id, v_id, l.kind, l.key, l.default_label, s.item_position
  from private.starter_planning_items(p_starter) s
  join private.planning_library() l on l.key = s.key
  where s.parent_key is null;
  insert into public.planning_template_items (tenant_id, template_id, kind, key, parent_id, label, position)
  select p_tenant_id, v_id, l.kind, l.key, p.id, l.default_label, s.item_position
  from private.starter_planning_items(p_starter) s
  join private.planning_library() l on l.key = s.key
  join public.planning_template_items p on p.template_id = v_id and p.key = s.parent_key
  where s.parent_key is not null;
  perform private.audit(p_tenant_id, 'planning_template', v_id, 'created', 'staff', (select auth.uid()),
    jsonb_build_object('starter', p_starter));
  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_planning_template_from_starter"("p_tenant_id" "uuid", "p_starter" "text", "p_name" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_planning_template_once"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_start" "text", "p_source_template_id" "uuid", "p_name" "text", "p_description" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d record;
  v_source public.planning_templates%rowtype;
  v_existing uuid;
  v_inserted uuid;
begin
  perform private.require_staff_of(p_tenant_id);
  if p_template_id is null then
    perform private.planning_error('a request id is required');
  end if;

  -- A retry of a request that already succeeded (its response was lost).
  select tenant_id into v_existing from public.planning_templates where id = p_template_id;
  if found then
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_template_id, 'replayed', true);
  end if;

  if p_start is null or p_start not in ('basics', 'wedding', 'simple_party', 'copy') then
    perform private.planning_error('choose a starting point');
  end if;
  if p_start = 'copy' then
    select * into v_source from public.planning_templates t where t.tenant_id = p_tenant_id and t.id = p_source_template_id;
    if not found then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
  end if;
  select * into d from private.planning_template_details(
    p_name,
    case p_start
      when 'copy' then v_source.description
      when 'wedding' then coalesce(nullif(btrim(coalesce(p_description, '')), ''),
        'Ceremony to closing, in the order of the day. Rename or remove anything a couple doesn''t need.')
      when 'simple_party' then coalesce(nullif(btrim(coalesce(p_description, '')), ''),
        'Event basics plus must-play and do-not-play songs. For birthdays and other simple parties.')
      else p_description end);

  insert into public.planning_templates (id, tenant_id, name, description)
  values (p_template_id, p_tenant_id, d.name, d.description)
  on conflict (id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    -- The same request, committed concurrently.
    select tenant_id into v_existing from public.planning_templates where id = p_template_id;
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_template_id, 'replayed', true);
  end if;

  if p_start = 'copy' then
    insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
    select i.tenant_id, p_template_id, i.kind, i.key, i.label, i.position
    from public.planning_template_items i where i.template_id = v_source.id and i.parent_id is null;
    insert into public.planning_template_items (tenant_id, template_id, kind, key, parent_id, label, position)
    select i.tenant_id, p_template_id, i.kind, i.key, np.id, i.label, i.position
    from public.planning_template_items i
    join public.planning_template_items op on op.id = i.parent_id
    join public.planning_template_items np on np.template_id = p_template_id and np.key = op.key
    where i.template_id = v_source.id and i.parent_id is not null;
    perform private.audit(p_tenant_id, 'planning_template', p_template_id, 'duplicated', 'staff', (select auth.uid()),
      jsonb_build_object('from_template_id', v_source.id));
  elsif p_start = 'basics' then
    insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
    select p_tenant_id, p_template_id, l.kind, l.key, l.default_label, 1 from private.planning_library() l where l.key = 'basics';
    perform private.audit(p_tenant_id, 'planning_template', p_template_id, 'created', 'staff', (select auth.uid()), '{}'::jsonb);
  else
    insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
    select p_tenant_id, p_template_id, l.kind, l.key, l.default_label, s.item_position
    from private.starter_planning_items(p_start) s
    join private.planning_library() l on l.key = s.key
    where s.parent_key is null;
    insert into public.planning_template_items (tenant_id, template_id, kind, key, parent_id, label, position)
    select p_tenant_id, p_template_id, l.kind, l.key, p.id, l.default_label, s.item_position
    from private.starter_planning_items(p_start) s
    join private.planning_library() l on l.key = s.key
    join public.planning_template_items p on p.template_id = p_template_id and p.key = s.parent_key
    where s.parent_key is not null;
    perform private.audit(p_tenant_id, 'planning_template', p_template_id, 'created', 'staff', (select auth.uid()),
      jsonb_build_object('starter', p_start));
  end if;

  return jsonb_build_object('id', p_template_id, 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."create_planning_template_once"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_start" "text", "p_source_template_id" "uuid", "p_name" "text", "p_description" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_planning_template_once"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_start" "text", "p_source_template_id" "uuid", "p_name" "text", "p_description" "text") IS 'Creates a planning template (Event basics only, a starter outline, or a copy) atomically (staff of the business). An id that already exists in the business returns that template as replayed.';



CREATE OR REPLACE FUNCTION "public"."create_platform_invitation"("p_email" "text", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_open public.platform_invitations%rowtype;
  v_id uuid;
  v_expires timestamptz := now() + interval '14 days';
begin
  perform private.require_platform_admin();
  if not coalesce(private.is_valid_email(v_email), false) then
    raise exception 'invitation_invalid: enter a valid email address' using errcode = 'invalid_parameter_value';
  end if;
  if p_link_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation link' using errcode = 'invalid_parameter_value';
  end if;
  -- Serializes concurrent invitations to the same address.
  perform pg_advisory_xact_lock(hashtextextended('flux:platform-invitation:' || v_email, 0));
  select * into v_open from public.platform_invitations
    where email = v_email and accepted_at is null and revoked_at is null for update;
  if found then
    return jsonb_build_object('status', 'exists', 'invitation_id', v_open.id, 'email', v_open.email,
      'state', case when v_open.expires_at > now() then 'pending' else 'expired' end, 'expires_at', v_open.expires_at);
  end if;
  if (select count(*) from public.platform_invitations i
      where i.invited_by = (select auth.uid()) and i.created_at > now() - interval '1 day') >= 50 then
    raise exception 'invitation_limit: you have sent many invitations today. Try again tomorrow' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.platform_invitations (email, link_id, token_hash, expires_at, invited_by)
  values (v_email, p_link_id, p_token_hash, v_expires, (select auth.uid()))
  returning id into v_id;
  perform private.enqueue_platform_email('platform_invitation', v_email, v_id,
    jsonb_build_object('link_id', p_link_id, 'expires_at', v_expires), 'platform_invitation:' || p_link_id);
  perform private.platform_audit('platform_invitation', v_id, 'created', (select auth.uid()),
    jsonb_build_object('email', v_email, 'link_id', p_link_id, 'expires_at', v_expires));
  return jsonb_build_object('status', 'created', 'invitation_id', v_id, 'email', v_email, 'expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."create_platform_invitation"("p_email" "text", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_proposal_template"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_intro" "text", "p_expiry_days" integer, "p_package_ids" "jsonb", "p_default_package_id" "uuid", "p_addons" "jsonb", "p_question_ids" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing uuid;
  v_inserted uuid;
begin
  perform private.require_staff_of(p_tenant_id);
  if p_template_id is null then
    raise exception 'template_invalid: a request id is required' using errcode = 'invalid_parameter_value';
  end if;

  -- A retry of a request that already succeeded (its response was lost).
  select tenant_id into v_existing from public.proposal_templates where id = p_template_id;
  if found then
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_template_id, 'replayed', true);
  end if;

  insert into public.proposal_templates (id, tenant_id, name, intro, expiry_days)
  values (p_template_id, p_tenant_id, p_name, p_intro, p_expiry_days)
  on conflict (id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    -- The same request, committed concurrently.
    select tenant_id into v_existing from public.proposal_templates where id = p_template_id;
    if v_existing is distinct from p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('id', p_template_id, 'replayed', true);
  end if;

  -- The template's contents, with the same checks as editing them.
  perform public.set_proposal_template_composition(p_template_id, p_package_ids, p_default_package_id, p_addons, p_question_ids);

  return jsonb_build_object('id', p_template_id, 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."create_proposal_template"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_intro" "text", "p_expiry_days" integer, "p_package_ids" "jsonb", "p_default_package_id" "uuid", "p_addons" "jsonb", "p_question_ids" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_proposal_template"("p_tenant_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_intro" "text", "p_expiry_days" integer, "p_package_ids" "jsonb", "p_default_package_id" "uuid", "p_addons" "jsonb", "p_question_ids" "jsonb") IS 'Creates a proposal template and its packages, add-ons and questions atomically (staff of the business). An id that already exists in the business returns that template as replayed.';



CREATE OR REPLACE FUNCTION "public"."create_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid", "p_email" "text", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_existing public.staff_invitations%rowtype;
  v_expires timestamptz := now() + interval '7 days';
begin
  perform private.require_owner_of(p_tenant_id);
  if exists (select 1 from public.tenants t where t.id = p_tenant_id and t.archived_at is not null) then
    raise exception 'workspace_archived: this business is archived' using errcode = 'invalid_parameter_value';
  end if;
  if p_invitation_id is null or p_link_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation request' using errcode = 'invalid_parameter_value';
  end if;

  -- A retry of a request that already succeeded (its response was lost).
  select * into v_existing from public.staff_invitations where id = p_invitation_id;
  if found then
    if v_existing.tenant_id <> p_tenant_id then
      raise exception 'not found' using errcode = 'no_data_found';
    end if;
    return jsonb_build_object('status', 'created', 'replayed', true, 'invitation_id', v_existing.id, 'email', v_existing.email,
      'expires_at', v_existing.expires_at);
  end if;

  if not coalesce(private.is_valid_email(v_email), false) then
    raise exception 'invitation_invalid: enter a valid email address' using errcode = 'invalid_parameter_value';
  end if;
  -- Serializes concurrent invitations to the same address in this business.
  perform pg_advisory_xact_lock(hashtextextended('flux:staff-invitation:' || p_tenant_id || ':' || v_email, 0));
  if exists (select 1 from public.tenant_memberships m join auth.users u on u.id = m.user_id
             where m.tenant_id = p_tenant_id and m.removed_at is null and lower(u.email) = v_email) then
    return jsonb_build_object('status', 'member', 'email', v_email);
  end if;
  select * into v_existing from public.staff_invitations
    where tenant_id = p_tenant_id and email = v_email and accepted_at is null and revoked_at is null;
  if found then
    return jsonb_build_object('status', 'exists', 'invitation_id', v_existing.id, 'email', v_existing.email,
      'state', case when v_existing.expires_at > now() then 'pending' else 'expired' end, 'expires_at', v_existing.expires_at);
  end if;
  if (select count(*) from public.staff_invitations i
      where i.tenant_id = p_tenant_id and i.created_at > now() - interval '1 day') >= 30 then
    raise exception 'invitation_limit: this business has sent many invitations today. Try again tomorrow' using errcode = 'invalid_parameter_value';
  end if;

  insert into public.staff_invitations (id, tenant_id, email, link_id, token_hash, expires_at, invited_by)
  values (p_invitation_id, p_tenant_id, v_email, p_link_id, p_token_hash, v_expires, (select auth.uid()));
  perform private.enqueue_staff_email(p_tenant_id, 'staff_invitation', v_email, p_invitation_id,
    jsonb_build_object('link_id', p_link_id, 'expires_at', v_expires), 'staff_invitation:' || p_link_id);
  perform private.audit(p_tenant_id, 'staff_invitation', p_invitation_id, 'created', 'staff', (select auth.uid()),
    jsonb_build_object('email', v_email, 'expires_at', v_expires));
  return jsonb_build_object('status', 'created', 'replayed', false, 'invitation_id', p_invitation_id, 'email', v_email, 'expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."create_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid", "p_email" "text", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


