CREATE OR REPLACE FUNCTION "public"."exchange_proposal_link"("p_token_hash" "text", "p_session_hash" "text", "p_tenant_slug" "text", "p_session_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  r record;
  v_expires timestamptz;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$'
     or p_session_hash is null or p_session_hash !~ '^[0-9a-f]{64}$'
     or p_session_seconds is null or p_session_seconds not between 60 and 86400 then
    return jsonb_build_object('status', 'invalid');
  end if;

  select l.id as link_id, l.tenant_id, l.proposal_id, l.expires_at as link_expires, l.revoked_at,
         p.status, p.first_viewed_at, p.event_id, e.active_proposal_id, e.title as event_title, t.archived_at, t.suspended_at
    into r
  from public.access_links l
  join public.tenants t on t.id = l.tenant_id
  join public.proposals p on p.tenant_id = l.tenant_id and p.id = l.proposal_id
  join public.events e on e.tenant_id = p.tenant_id and e.id = p.event_id
  where l.token_hash = p_token_hash and t.slug = p_tenant_slug and l.purpose = 'proposal'
  for update of p;

  if not found or r.link_expires <= now() or r.archived_at is not null then
    return jsonb_build_object('status', 'invalid');
  end if;
  if r.revoked_at is not null then
    return jsonb_build_object('status', case when r.status = 'superseded' then 'superseded' else 'invalid' end);
  end if;
  if r.status not in ('sent', 'submitted', 'approved') or r.active_proposal_id is distinct from r.proposal_id then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- Suspended workspace: temporarily unavailable. No session, view or email;
  -- the link keeps its own expiry and works again after restoration.
  if r.suspended_at is not null then
    return jsonb_build_object('status', 'unavailable');
  end if;
  v_expires := least(now() + make_interval(secs => p_session_seconds), r.link_expires);
  insert into public.proposal_sessions (tenant_id, proposal_id, access_link_id, session_hash, expires_at)
  values (r.tenant_id, r.proposal_id, r.link_id, p_session_hash, v_expires);
  insert into public.proposal_views (tenant_id, proposal_id, access_link_id) values (r.tenant_id, r.proposal_id, r.link_id);

  if r.first_viewed_at is null then
    update public.proposals set first_viewed_at = now() where id = r.proposal_id;
    perform private.enqueue_email(
      r.tenant_id, 'proposal_link_opened', private.staff_notification_email(r.tenant_id), r.proposal_id, null,
      jsonb_build_object('event_title', r.event_title, 'opened_at', now()),
      'proposal_link_opened:' || r.proposal_id
    );
    perform private.audit(r.tenant_id, 'proposal', r.proposal_id, 'link_first_opened', 'client', null);
  end if;

  return jsonb_build_object('status', 'ok', 'proposal_id', r.proposal_id, 'tenant_id', r.tenant_id, 'session_expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."exchange_proposal_link"("p_token_hash" "text", "p_session_hash" "text", "p_tenant_slug" "text", "p_session_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_document_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_permanent" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.document_jobs
    set status = case when p_permanent or attempts >= max_attempts then 'failed' else 'pending' end,
        next_attempt_at = now() + least(interval '1 minute' * power(2, greatest(attempts - 1, 0)), interval '1 hour'),
        last_error = left(coalesce(p_error, 'unknown error'), 1000),
        lease_token = null, locked_until = null
    where id = p_job_id and status = 'running' and lease_token = p_lease_token;
  return found;
end;
$$;


ALTER FUNCTION "public"."fail_document_job"("p_job_id" "uuid", "p_lease_token" "uuid", "p_error" "text", "p_permanent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_email_outbox"("p_id" "uuid", "p_error" "text", "p_permanent" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.email_outbox
    set status = case when p_permanent or attempts >= max_attempts then 'failed' else 'pending' end,
        next_attempt_at = now() + least(interval '1 minute' * power(2, greatest(attempts - 1, 0)), interval '1 hour'),
        last_error = left(coalesce(p_error, 'unknown error'), 1000),
        locked_until = null
    where id = p_id and status = 'sending';
$$;


ALTER FUNCTION "public"."fail_email_outbox"("p_id" "uuid", "p_error" "text", "p_permanent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."freeze_email_branding"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  o public.email_outbox%rowtype;
  v_name text;
  v_color text;
  v_path text;
  v_source text;
  v_logo jsonb;
  v_reply text;
  v_branding jsonb;
begin
  select * into o from public.email_outbox where id = p_id;
  if not found or o.tenant_id is null then
    return null;
  end if;
  if o.branding is not null then
    return o.branding;
  end if;

  if o.entity_type = 'proposal' then
    select p.offer_snapshot -> 'branding' ->> 'display_name', p.offer_snapshot -> 'branding' -> 'brand_colors' ->> 'primary',
           p.offer_snapshot -> 'branding' ->> 'logo_storage_path', 'proposal'
      into v_name, v_color, v_path, v_source
    from public.proposals p
    where p.tenant_id = o.tenant_id and p.id = o.entity_id and p.offer_snapshot ? 'branding';
  end if;
  if v_source is null then
    select t.display_name, t.brand_colors ->> 'primary', t.logo_storage_path, 'business'
      into v_name, v_color, v_path, v_source
    from public.tenants t where t.id = o.tenant_id;
  end if;
  -- Only a registered logo of this business (never another business's file).
  if v_path is not null then
    select jsonb_build_object('path', l.storage_path, 'needs_dark_background', l.needs_dark_background, 'width', l.width, 'height', l.height)
      into v_logo
    from public.tenant_logos l where l.tenant_id = o.tenant_id and l.storage_path = v_path;
  end if;
  -- A frozen sender's reply-to wins; otherwise the business's address now.
  v_reply := case when o.sender ? 'reply_to' then o.sender ->> 'reply_to'
                  else (select t.reply_to_email from public.tenants t where t.id = o.tenant_id) end;
  v_branding := jsonb_strip_nulls(jsonb_build_object(
    -- Emails with a frozen sender keep its display name, so header and sender agree.
    'display_name', coalesce(o.sender ->> 'display_name', v_name),
    'primary_color', v_color,
    'source', v_source,
    'logo', v_logo)) || jsonb_build_object('reply_to', v_reply);

  update public.email_outbox set branding = v_branding
    where id = o.id and branding is null and status = 'sending'
    returning branding into v_branding;
  -- Not claimed (or frozen meanwhile): return what is stored, if anything.
  return coalesce(v_branding, (select e.branding from public.email_outbox e where e.id = o.id));
end;
$$;


ALTER FUNCTION "public"."freeze_email_branding"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."freeze_email_sender"("p_id" "uuid", "p_from_address" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sender jsonb;
begin
  if p_from_address is null or not private.is_valid_email(p_from_address) then
    raise exception 'invalid from address' using errcode = 'invalid_parameter_value';
  end if;
  update public.email_outbox o
    set sender = jsonb_build_object(
      'display_name', coalesce(o.sender ->> 'display_name', t.display_name),
      'from_name', coalesce(o.sender ->> 'from_name', t.display_name || ' via Flux DJ'),
      'reply_to', case when o.sender ? 'reply_to' then o.sender -> 'reply_to' else to_jsonb(t.reply_to_email) end,
      'from_address', coalesce(o.sender ->> 'from_address', p_from_address))
    from public.tenants t
    where o.id = p_id and t.id = o.tenant_id and o.status = 'sending'
    returning o.sender into v_sender;
  return v_sender;
end;
$$;


ALTER FUNCTION "public"."freeze_email_sender"("p_id" "uuid", "p_from_address" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_contract_draft"("p_approval_id" "uuid", "p_template_version_id" "uuid", "p_balance_due_date" "date" DEFAULT NULL::"date", "p_replace_contract_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_approval public.proposal_approvals%rowtype;
  v_membership_id uuid;
  v_event_id uuid;
  v_event public.events%rowtype;
  v_proposal public.proposals%rowtype;
  v_selection public.proposal_selections%rowtype;
  v_tenant public.tenants%rowtype;
  v_version public.contract_template_versions%rowtype;
  v_template_active boolean;
  v_signer record;
  v_has_signer boolean;
  v_package record;
  v_deposit bigint;
  v_has_discount boolean;
  v_discount_text text;
  v_balance bigint;
  v_values jsonb;
  v_missing jsonb;
  v_rendered jsonb;
  v_commercial jsonb;
  v_parties jsonb;
  v_hash text;
  v_existing public.contracts%rowtype;
  v_has_existing boolean;
  v_replaced uuid;
  v_id uuid;
begin
  select * into v_approval from public.proposal_approvals where id = p_approval_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(v_approval.tenant_id);

  -- Lock order everywhere: event, then proposal. The event lock serializes
  -- generation, so concurrent clicks cannot create two drafts.
  select p.event_id into v_event_id from public.proposals p
  where p.tenant_id = v_approval.tenant_id and p.id = v_approval.proposal_id;
  select * into v_event from public.events where tenant_id = v_approval.tenant_id and id = v_event_id for update;
  select * into v_proposal from public.proposals where tenant_id = v_approval.tenant_id and id = v_approval.proposal_id for update;
  select * into v_selection from public.proposal_selections where tenant_id = v_approval.tenant_id and id = v_approval.selection_id;
  select * into v_tenant from public.tenants where id = v_approval.tenant_id;

  if v_proposal.status <> 'approved' or v_event.active_proposal_id is distinct from v_proposal.id then
    raise exception 'contract_stale_approval: this approval is no longer current because a revised offer replaced it'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_event.lifecycle_status <> 'awaiting_signature' then
    raise exception 'contract_not_allowed: the event is %', replace(v_event.lifecycle_status, '_', ' ')
      using errcode = 'invalid_parameter_value';
  end if;
  if v_tenant.archived_at is not null then
    raise exception 'contract_not_allowed: the business is archived' using errcode = 'invalid_parameter_value';
  end if;

  select * into v_version from public.contract_template_versions
  where tenant_id = v_tenant.id and id = p_template_version_id;
  if not found then
    perform private.contract_error('template version not found');
  end if;
  if v_version.published_at is null then
    perform private.contract_error('publish this template version before generating a contract');
  end if;
  select t.active into v_template_active from public.contract_templates t
  where t.tenant_id = v_tenant.id and t.id = v_version.template_id;
  if not v_template_active then
    perform private.contract_error('this template is archived');
  end if;

  if p_balance_due_date is not null then
    if not ('payment.balance_due_date' = any (v_version.placeholders)) then
      raise exception 'contract_input_invalid: this template version has no balance due date, so leave it blank'
        using errcode = 'invalid_parameter_value';
    end if;
    if p_balance_due_date < (now() at time zone v_event.timezone)::date then
      raise exception 'contract_input_invalid: the balance due date is in the past' using errcode = 'invalid_parameter_value';
    end if;
  end if;

  -- Parties, copied now -------------------------------------------------------
  select c.id, c.name, c.email, c.phone, c.archived_at into v_signer
  from public.event_clients ec
  join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
  where ec.tenant_id = v_event.tenant_id and ec.event_id = v_event.id and ec.can_sign;
  v_has_signer := found;

  -- Commercial terms, from the approved selection only -------------------------
  select l.item_key, l.name, l.unit_price_cents into v_package
  from public.proposal_selection_lines l
  where l.tenant_id = v_selection.tenant_id and l.selection_id = v_selection.id and l.source = 'package';

  -- The tenant's deposit percentage, frozen below; deposit rounded half up
  -- to the cent from the approved total; balance = total - deposit.
  v_deposit := private.contract_deposit_cents(v_selection.total_cents, v_tenant.deposit_percent);
  v_balance := v_selection.total_cents - v_deposit;
  -- The approved selection's discount (its total is already discounted).
  v_has_discount := v_selection.selection_snapshot ? 'discount';
  v_discount_text := case when v_selection.discount_cents > 0 then
      (v_selection.selection_snapshot -> 'discount' ->> 'label')
      || case when v_selection.selection_snapshot -> 'discount' ->> 'type' = 'percent'
              then ' (' || private.format_rate_ppm((v_selection.selection_snapshot -> 'discount' ->> 'percent_basis_points')::bigint * 100) || ')'
              else '' end
      || ': ' || private.format_cents(-v_selection.discount_cents, v_selection.currency)
    else 'No discount.' end;

  v_values := jsonb_build_object(
    'business.name', nullif(btrim(v_tenant.business_name), ''),
    'business.legal_name', nullif(btrim(v_tenant.business_name), ''),
    'business.address', nullif(btrim(v_tenant.business_address), ''),
    'business.email', nullif(btrim(v_tenant.contact_email), ''),
    'business.display_name', nullif(btrim(v_tenant.display_name), ''),
    'client.name', case when v_has_signer then nullif(btrim(v_signer.name), '') end,
    'client.email', case when v_has_signer then nullif(btrim(v_signer.email), '') end,
    'client.phone', case when v_has_signer then nullif(btrim(v_signer.phone), '') end,
    'event.title', nullif(btrim(v_event.title), ''),
    'event.date', to_char(v_event.event_date, 'FMDay, FMMonth FMDD, YYYY'),
    'venue.name', nullif(btrim(v_event.venue_name), ''),
    'venue.address', nullif(btrim(v_event.venue_address), ''),
    'package.name', v_package.name,
    'package.price', private.format_cents(v_package.unit_price_cents, v_selection.currency),
    -- Quantities read as on the approved proposal, from its frozen gear
    -- ("1 pair of Moving Heads (2 lights)"); older offers read as before.
    'package.included', coalesce((
      select string_agg('- ' || private.gear_quantity_text(v_proposal.offer_snapshot -> 'gear' -> l.item_key, l.name, l.quantity), E'\n' order by l.line_no)
      from public.proposal_selection_lines l
      where l.tenant_id = v_selection.tenant_id and l.selection_id = v_selection.id and l.source = 'included'
    ), 'No gear is listed as included in the package.'),
    'gear.extras', coalesce((
      select string_agg(
        '- ' || private.gear_quantity_text(v_proposal.offer_snapshot -> 'gear' -> l.item_key, l.name, l.quantity)
        || ': ' || private.format_cents(l.line_total_cents, v_selection.currency)
        || case when l.source = 'required' then ' (required: ' || array_to_string(l.required_reasons, '; ') || ')' else '' end,
        E'\n' order by l.line_no)
      from public.proposal_selection_lines l
      where l.tenant_id = v_selection.tenant_id and l.selection_id = v_selection.id and l.source in ('optional', 'required')
    ), 'No additional gear.'),
    'pricing.subtotal_before_discount', private.format_cents(v_selection.subtotal_cents, v_selection.currency),
    'pricing.discount', v_discount_text,
    'pricing.subtotal', private.format_cents(v_selection.subtotal_cents - v_selection.discount_cents, v_selection.currency),
    'pricing.taxes', coalesce((
      select string_agg(
        '- ' || (t ->> 'label') || ' (' || private.format_rate_ppm((t ->> 'rate_ppm')::bigint) || '): '
        || private.format_cents((t ->> 'amount_cents')::bigint, v_selection.currency),
        E'\n' order by ord)
      from jsonb_array_elements(v_selection.tax_breakdown) with ordinality as x(t, ord)
    ), 'No taxes apply.'),
    'pricing.tax_total', private.format_cents(v_selection.tax_cents, v_selection.currency),
    'pricing.total', private.format_cents(v_selection.total_cents, v_selection.currency),
    'pricing.currency', v_selection.currency,
    'payment.deposit_percent', v_tenant.deposit_percent::text || '%',
    'payment.deposit', private.format_cents(v_deposit, v_selection.currency),
    'payment.balance', private.format_cents(v_balance, v_selection.currency),
    'payment.balance_due_date', to_char(p_balance_due_date, 'FMMonth FMDD, YYYY')
  );

  -- Every placeholder the template uses needs a real value, and a signer is
  -- always required. Nothing is stored when anything is missing.
  select coalesce(jsonb_agg(jsonb_build_object('key', p.key, 'label', p.label, 'hint', p.missing_hint) order by p.sort_order), '[]')
    into v_missing
  from private.contract_placeholders() p
  where p.key = any (v_version.placeholders) and v_values ->> p.key is null;
  if not v_has_signer then
    v_missing := jsonb_build_array(jsonb_build_object('key', 'signer', 'label', 'Signer',
      'hint', 'Signer: mark one of the event''s contacts as the signer.')) || v_missing;
  elsif v_signer.archived_at is not null then
    v_missing := jsonb_build_array(jsonb_build_object('key', 'signer', 'label', 'Signer',
      'hint', 'Signer: the signer''s client record is archived. Restore it or choose another signer.')) || v_missing;
  end if;
  if jsonb_array_length(v_missing) > 0 then
    return jsonb_build_object('status', 'incomplete', 'missing', v_missing);
  end if;

  v_rendered := jsonb_build_object(
    'schema_version', 1,
    'title', private.render_contract_text(v_version.title, v_values),
    'sections', (
      select jsonb_agg(jsonb_build_object(
        'heading', private.render_contract_text(s ->> 'heading', v_values),
        'body', private.render_contract_text(s ->> 'body', v_values)) order by ord)
      from jsonb_array_elements(v_version.sections) with ordinality as x(s, ord)
    )
  );
  v_commercial := jsonb_build_object(
    'schema_version', 1,
    'currency', v_selection.currency,
    'package', jsonb_build_object('key', v_package.item_key, 'name', v_package.name, 'base_price_cents', v_package.unit_price_cents),
    'lines', (
      select jsonb_agg(jsonb_build_object(
        'line_no', l.line_no, 'source', l.source, 'item_key', l.item_key, 'name', l.name, 'description', l.description,
        'quantity', l.quantity, 'unit_price_cents', l.unit_price_cents, 'line_total_cents', l.line_total_cents,
        'required_quantity', l.required_quantity, 'required_reasons', to_jsonb(l.required_reasons),
        'tax_category', l.tax_category)
        || case when v_has_discount then jsonb_build_object('discount_cents', l.discount_cents) else '{}'::jsonb end
        order by l.line_no)
      from public.proposal_selection_lines l
      where l.tenant_id = v_selection.tenant_id and l.selection_id = v_selection.id
    ),
    'subtotal_cents', v_selection.subtotal_cents,
    'tax_breakdown', v_selection.tax_breakdown,
    'tax_cents', v_selection.tax_cents,
    'total_cents', v_selection.total_cents,
    'payment', jsonb_build_object(
      'deposit_percent', v_tenant.deposit_percent,
      'deposit_basis_points', v_tenant.deposit_percent * 100,
      'deposit_rounding', 'half_up_to_cent',
      'deposit_due', 'on_signing',
      'deposit_cents', v_deposit,
      'balance_cents', v_balance,
      'balance_due_date', p_balance_due_date
    ),
    'source', jsonb_build_object(
      'proposal_id', v_proposal.id, 'proposal_revision', v_proposal.revision, 'offer_sha256', v_proposal.offer_sha256,
      'selection_id', v_selection.id, 'selection_version', v_selection.version,
      'approval_id', v_approval.id, 'selection_sha256', v_approval.selection_sha256, 'approved_at', v_approval.approved_at
    )
  );
  -- Only with a discount, so a contract without one is generated exactly as before.
  if v_has_discount then
    v_commercial := v_commercial || jsonb_build_object(
      'discount', (v_selection.selection_snapshot -> 'discount') || jsonb_build_object('amount_cents', v_selection.discount_cents),
      'discounted_subtotal_cents', v_selection.subtotal_cents - v_selection.discount_cents);
  end if;
  v_parties := jsonb_build_object(
    'business', jsonb_build_object(
      'name', v_tenant.business_name, 'display_name', v_tenant.display_name, 'legal_name', v_tenant.business_name,
      'address', v_tenant.business_address, 'contact_email', v_tenant.contact_email),
    'client', jsonb_build_object('client_id', v_signer.id, 'name', v_signer.name, 'email', v_signer.email, 'phone', v_signer.phone),
    'event', jsonb_build_object(
      'event_id', v_event.id, 'title', v_event.title, 'event_type', v_event.event_type, 'date', v_event.event_date,
      'timezone', v_event.timezone, 'venue_name', v_event.venue_name, 'venue_address', v_event.venue_address)
  );
  v_hash := private.contract_content_sha256(v_rendered, v_commercial, v_parties, v_version.id, v_version.content_sha256);

  -- One draft per event: repeat or replace explicitly ---------------------------
  select * into v_existing from public.contracts
  where tenant_id = v_event.tenant_id and event_id = v_event.id and status = 'draft'
  for update;
  v_has_existing := found;

  if v_has_existing then
    if v_existing.content_sha256 = v_hash
       and (p_replace_contract_id is null or p_replace_contract_id in (v_existing.id, v_existing.replaces_id)) then
      return jsonb_build_object('status', 'replayed', 'contract_id', v_existing.id);
    end if;
    if p_replace_contract_id is null then
      return jsonb_build_object('status', 'draft_exists', 'contract_id', v_existing.id);
    end if;
    if p_replace_contract_id <> v_existing.id then
      return jsonb_build_object('status', 'conflict', 'contract_id', v_existing.id);
    end if;
    update public.contracts set status = 'replaced' where id = v_existing.id;
    v_replaced := v_existing.id;
  elsif p_replace_contract_id is not null then
    return jsonb_build_object('status', 'conflict', 'contract_id', null);
  end if;

  insert into public.contracts (
    tenant_id, event_id, proposal_id, selection_id, approval_id, template_id, template_version_id,
    template_content_sha256, replaces_id, signer_client_id, signer_name, signer_email, currency,
    total_cents, deposit_percent, deposit_cents, balance_cents, balance_due_date, rendered_content, commercial_snapshot,
    party_snapshot, content_sha256, generated_by_membership_id, generated_by_user_id
  ) values (
    v_tenant.id, v_event.id, v_proposal.id, v_selection.id, v_approval.id, v_version.template_id, v_version.id,
    v_version.content_sha256, v_replaced, v_signer.id, v_signer.name, v_signer.email, v_selection.currency,
    v_selection.total_cents, v_tenant.deposit_percent, v_deposit, v_balance, p_balance_due_date, v_rendered, v_commercial,
    v_parties, v_hash, v_membership_id, (select auth.uid())
  )
  returning id, content_sha256 into v_id, v_hash;

  perform private.audit(v_tenant.id, 'contract', v_id, case when v_replaced is null then 'draft_generated' else 'draft_regenerated' end,
    'staff', (select auth.uid()),
    jsonb_build_object('event_id', v_event.id, 'approval_id', v_approval.id, 'template_version_id', v_version.id,
                       'content_sha256', v_hash, 'replaces_id', v_replaced));
  if v_replaced is not null then
    perform private.audit(v_tenant.id, 'contract', v_replaced, 'draft_replaced', 'staff', (select auth.uid()),
      jsonb_build_object('replaced_by', v_id));
  end if;

  return jsonb_build_object('status', 'created', 'contract_id', v_id, 'content_sha256', v_hash, 'replaced_id', v_replaced);
end;
$$;


ALTER FUNCTION "public"."generate_contract_draft"("p_approval_id" "uuid", "p_template_version_id" "uuid", "p_balance_due_date" "date", "p_replace_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."install_starter_planning_templates"("p_tenant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_starter text;
  v_id uuid;
  v_created text[] := '{}'::text[];
  v_existing text[] := '{}'::text[];
begin
  perform private.require_staff_of(p_tenant_id);
  foreach v_starter in array array['wedding', 'simple_party'] loop
    v_id := null;
    insert into public.planning_templates (tenant_id, name, description, starter_key)
    values (p_tenant_id,
      case v_starter when 'wedding' then 'Wedding' else 'Simple Party' end,
      case v_starter
        when 'wedding' then 'Ceremony to closing, in the order of the day. Rename or remove anything a couple doesn''t need.'
        else 'Event basics plus must-play and do-not-play songs. For birthdays and other simple parties.' end,
      v_starter)
    on conflict (tenant_id, starter_key) do nothing
    returning id into v_id;
    if v_id is null then
      v_existing := v_existing || v_starter;
      continue;
    end if;
    insert into public.planning_template_items (tenant_id, template_id, kind, key, label, position)
    select p_tenant_id, v_id, l.kind, l.key, l.default_label, s.item_position
    from private.starter_planning_items(v_starter) s
    join private.planning_library() l on l.key = s.key
    where s.parent_key is null;
    insert into public.planning_template_items (tenant_id, template_id, kind, key, parent_id, label, position)
    select p_tenant_id, v_id, l.kind, l.key, p.id, l.default_label, s.item_position
    from private.starter_planning_items(v_starter) s
    join private.planning_library() l on l.key = s.key
    join public.planning_template_items p on p.template_id = v_id and p.key = s.parent_key
    where s.parent_key is not null;
    perform private.audit(p_tenant_id, 'planning_template', v_id, 'starter_installed', 'staff', (select auth.uid()),
      jsonb_build_object('starter', v_starter));
    v_created := v_created || v_starter;
  end loop;
  return jsonb_build_object('created', to_jsonb(v_created), 'existing', to_jsonb(v_existing));
end;
$$;


ALTER FUNCTION "public"."install_starter_planning_templates"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invalidate_event_payment"("p_payment_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.event_payments%rowtype;
  e public.events%rowtype;
  v_membership_id uuid;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into p from public.event_payments where id = p_payment_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(p.tenant_id);
  -- Lock order: event, then payment.
  select * into e from public.events where tenant_id = p.tenant_id and id = p.event_id for update;
  select * into p from public.event_payments where id = p.id for update;
  if p.invalidated_at is not null then
    return jsonb_build_object('status', 'already_invalidated', 'invalidated_at', p.invalidated_at);
  end if;
  if e.archived_at is not null then
    perform private.payment_error('the event is archived. Unarchive it before correcting payments');
  end if;
  if length(v_reason) not between 3 and 500 then
    perform private.payment_error('give a reason (3 to 500 characters)');
  end if;

  perform set_config('flux.invalidating_payment', p.id::text, true);
  update public.event_payments
    set invalidated_at = now(), invalidated_by_user_id = (select auth.uid()), invalidated_by_membership_id = v_membership_id,
        invalidated_by_email = (select lower(u.email) from auth.users u where u.id = (select auth.uid())),
        invalidation_reason = v_reason
    where id = p.id
    returning * into p;
  perform set_config('flux.invalidating_payment', '', true);
  perform private.audit(p.tenant_id, 'event', p.event_id, 'payment_invalidated', 'staff', (select auth.uid()),
    jsonb_build_object('payment_id', p.id, 'amount_cents', p.amount_cents));
  -- Re-evaluated like every payment change. A booking is never undone here;
  -- the summary warns staff if the deposit is no longer covered.
  perform private.evaluate_booking(p.event_id, 'staff', (select auth.uid()), false);
  return jsonb_build_object('status', 'invalidated', 'invalidated_at', p.invalidated_at);
end;
$$;


ALTER FUNCTION "public"."invalidate_event_payment"("p_payment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_event_plan_item"("p_item_id" "uuid", "p_expected_version" integer, "p_direction" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.event_plan_items%rowtype;
  v_other public.event_plan_items%rowtype;
begin
  i := private.lock_plan_item_for_staff(p_item_id, p_expected_version);
  if p_direction is null or p_direction not in ('up', 'down') then
    perform private.planning_error('move up or down');
  end if;
  if i.kind = 'general' then
    perform private.planning_error('general sections keep their order; only stages and moments move');
  end if;
  perform private.renumber_plan_siblings(i.plan_id, i.parent_id, i.kind);
  select * into i from public.event_plan_items where id = i.id;
  select * into v_other from public.event_plan_items s
  where s.plan_id = i.plan_id and s.kind = i.kind and s.parent_id is not distinct from i.parent_id
    and case when p_direction = 'up' then s.position < i.position else s.position > i.position end
  order by case when p_direction = 'up' then -s.position else s.position end
  limit 1;
  if not found then
    perform private.planning_error(case when p_direction = 'up' then 'this item is already first' else 'this item is already last' end);
  end if;
  update public.event_plan_items set position = v_other.position where id = i.id;
  update public.event_plan_items set position = i.position where id = v_other.id;
  return private.bump_plan_structure(i.plan_id, 'moved_' || p_direction, i.key);
end;
$$;


ALTER FUNCTION "public"."move_event_plan_item"("p_item_id" "uuid", "p_expected_version" integer, "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_planning_template_item"("p_item_id" "uuid", "p_expected_version" integer, "p_direction" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.planning_template_items%rowtype;
  t public.planning_templates%rowtype;
  v_other public.planning_template_items%rowtype;
begin
  select * into i from public.planning_template_items where id = p_item_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  t := private.lock_planning_template(i.template_id, p_expected_version);
  if p_direction is null or p_direction not in ('up', 'down') then
    perform private.planning_error('move up or down');
  end if;
  if i.kind = 'general' then
    perform private.planning_error('general sections keep their order; only stages and moments move');
  end if;
  perform private.renumber_template_siblings(t.id, i.parent_id, i.kind);
  select * into i from public.planning_template_items where id = i.id;
  select * into v_other from public.planning_template_items s
  where s.template_id = t.id and s.kind = i.kind and s.parent_id is not distinct from i.parent_id
    and case when p_direction = 'up' then s.position < i.position else s.position > i.position end
  order by case when p_direction = 'up' then -s.position else s.position end
  limit 1;
  if not found then
    perform private.planning_error(case when p_direction = 'up' then 'this item is already first' else 'this item is already last' end);
  end if;
  update public.planning_template_items set position = v_other.position where id = i.id;
  update public.planning_template_items set position = i.position where id = v_other.id;
  return private.bump_planning_template(t.id);
end;
$$;


ALTER FUNCTION "public"."move_planning_template_item"("p_item_id" "uuid", "p_expected_version" integer, "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_contracts"() RETURNS TABLE("tenant_slug" "text", "tenant_display_name" "text", "contract_id" "uuid", "event_title" "text", "event_date" "text", "sent_at" timestamp with time zone, "status" "text", "signed_at" timestamp with time zone, "event_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select t.slug, t.display_name, c.id, c.party_snapshot -> 'event' ->> 'title', c.party_snapshot -> 'event' ->> 'date', c.sent_at,
         c.status, c.signed_at, c.event_id
  from public.contracts c
  join public.tenants t on t.id = c.tenant_id
  join public.event_access ea on ea.tenant_id = c.tenant_id and ea.event_id = c.event_id
    and ea.user_id = (select auth.uid()) and ea.revoked_at is null
  where c.status in ('sent', 'signed') and private.client_can_read_contract(c.id)
  order by c.sent_at desc;
$$;


ALTER FUNCTION "public"."my_contracts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_events"() RETURNS TABLE("event_id" "uuid", "tenant_slug" "text", "tenant_display_name" "text", "title" "text", "event_type" "text", "event_date" "date", "timezone" "text", "venue_name" "text", "venue_address" "text", "lifecycle_status" "text", "booking_source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select e.id, t.slug, t.display_name, e.title, e.event_type, e.event_date,
         e.timezone, e.venue_name, e.venue_address, e.lifecycle_status, e.booking_source
  from public.events e
  join public.tenants t on t.id = e.tenant_id
  where e.id in (select private.client_event_ids())
    and t.archived_at is null
    and e.archived_at is null
  order by e.event_date, e.id;
$$;


ALTER FUNCTION "public"."my_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_plans"() RETURNS TABLE("tenant_slug" "text", "tenant_display_name" "text", "event_id" "uuid", "event_title" "text", "event_date" "date", "contract_id" "uuid", "requirements_total" integer, "requirements_met" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select t.slug, t.display_name, e.id, e.title, e.event_date,
         (select k.id from public.contracts k where k.tenant_id = e.tenant_id and k.event_id = e.id and k.status = 'signed'
          order by k.signed_at desc limit 1),
         (x.progress ->> 'requirements_total')::int, (x.progress ->> 'requirements_met')::int
  from public.event_plans p
  join public.events e on e.tenant_id = p.tenant_id and e.id = p.event_id
  join public.tenants t on t.id = e.tenant_id
  cross join lateral (select private.plan_progress(p.id) as progress) x
  where e.id in (select private.client_event_ids()) and private.client_can_access_plan(e.id)
  order by e.event_date, e.id;
$$;


