CREATE OR REPLACE FUNCTION "public"."open_contract_template_draft"("p_template_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_template public.contract_templates%rowtype;
  v_membership_id uuid;
  v_latest public.contract_template_versions%rowtype;
  v_id uuid;
begin
  select * into v_template from public.contract_templates where id = p_template_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(v_template.tenant_id);

  select v.id into v_id from public.contract_template_versions v
  where v.template_id = v_template.id and v.published_at is null;
  if v_id is not null then
    return v_id;
  end if;

  select * into v_latest from public.contract_template_versions v
  where v.template_id = v_template.id order by v.version_number desc limit 1;
  insert into public.contract_template_versions (tenant_id, template_id, version_number, title, sections, created_by_membership_id)
  values (v_template.tenant_id, v_template.id, v_latest.version_number + 1, v_latest.title, v_latest.sections, v_membership_id)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."open_contract_template_draft"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_proposal_draft"("p_event_id" "uuid", "p_offer" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.events%rowtype;
  v_membership_id uuid;
  v_existing uuid;
  v_revision int;
  v_offer jsonb := p_offer;
  v_id uuid;
begin
  select * into v_event from public.events where id = p_event_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(v_event.tenant_id);

  select p.id into v_existing from public.proposals p where p.event_id = v_event.id and p.status = 'draft';
  if v_existing is not null then
    return v_existing;
  end if;

  if v_event.lifecycle_status in ('cancelled', 'completed', 'booked') then
    perform private.offer_error('event is ' || v_event.lifecycle_status);
  end if;
  if exists (select 1 from public.contracts k where k.tenant_id = v_event.tenant_id and k.event_id = v_event.id and k.status = 'signed') then
    perform private.offer_error('a contract has been signed for this event, so its terms cannot be revised. Amendments are not available yet');
  end if;
  -- A revision starts from the offer the client currently has.
  if v_offer is null and v_event.active_proposal_id is not null then
    select p.draft_offer into v_offer from public.proposals p
    where p.tenant_id = v_event.tenant_id and p.id = v_event.active_proposal_id;
  end if;
  v_offer := coalesce(v_offer, '{}'::jsonb);
  if not private.is_valid_draft_offer(v_offer) then
    perform private.offer_error('draft offer has an invalid shape');
  end if;

  select coalesce(max(p.revision), 0) + 1 into v_revision from public.proposals p where p.event_id = v_event.id;

  insert into public.proposals (tenant_id, event_id, revision, status, draft_offer, source_template_id, created_by_membership_id)
  values (
    v_event.tenant_id, v_event.id, v_revision, 'draft', v_offer,
    case when private.is_uuid_text(v_offer ->> 'template_id') then (v_offer ->> 'template_id')::uuid end,
    v_membership_id
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."open_proposal_draft"("p_event_id" "uuid", "p_offer" "jsonb") OWNER TO "postgres";


