CREATE OR REPLACE FUNCTION "public"."record_email_provider_event"("p_provider_message_id" "text", "p_status" "text", "p_occurred_at" timestamp with time zone, "p_detail" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rank integer := case p_status when 'delayed' then 1 when 'delivered' then 2 when 'failed' then 3 when 'bounced' then 3
                                  when 'suppressed' then 3 when 'complained' then 4 end;
begin
  if p_provider_message_id is null or length(p_provider_message_id) not between 1 and 200 or v_rank is null or p_occurred_at is null then
    raise exception 'invalid provider event' using errcode = 'invalid_parameter_value';
  end if;
  update public.email_outbox o
    set provider_status = p_status, provider_status_at = p_occurred_at, provider_detail = left(nullif(btrim(p_detail), ''), 200)
    where o.provider_message_id = p_provider_message_id
      and (o.provider_status is null
           or v_rank > case o.provider_status when 'delayed' then 1 when 'delivered' then 2 when 'complained' then 4 else 3 end
           or (v_rank = 1 and o.provider_status = 'delayed' and p_occurred_at > o.provider_status_at));
  return found;
end;
$$;


ALTER FUNCTION "public"."record_email_provider_event"("p_provider_message_id" "text", "p_status" "text", "p_occurred_at" timestamp with time zone, "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_event_payment"("p_event_id" "uuid", "p_amount_cents" bigint, "p_paid_on" "date", "p_reference" "text", "p_note" "text", "p_idempotency_key" "uuid", "p_confirm_duplicate" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  t public.tenants%rowtype;
  v_membership_id uuid;
  v_reference text := nullif(btrim(coalesce(p_reference, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_existing public.event_payments%rowtype;
  v_id uuid;
  v_booking jsonb;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  v_membership_id := private.require_staff_of(e.tenant_id);
  -- Serializes payments per event (duplicate check and idempotency).
  select * into e from public.events where id = e.id for update;
  select * into t from public.tenants where id = e.tenant_id;

  if p_idempotency_key is null then
    perform private.payment_error('reload the page and try again');
  end if;
  select * into v_existing from public.event_payments where tenant_id = e.tenant_id and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.event_id = e.id and v_existing.amount_cents = p_amount_cents and v_existing.paid_on = p_paid_on
       and v_existing.reference is not distinct from v_reference and v_existing.note is not distinct from v_note then
      return jsonb_build_object('status', 'replayed', 'payment_id', v_existing.id);
    end if;
    perform private.payment_error('this form was already used for another payment. Reload the page and enter it again');
  end if;

  if e.archived_at is not null or t.archived_at is not null then
    perform private.payment_error('the event is archived. Unarchive it before recording payments');
  end if;
  if p_amount_cents is null or p_amount_cents < 1 then
    perform private.payment_error('enter an amount greater than zero');
  end if;
  if p_amount_cents > 99999999999 then
    perform private.payment_error('the amount is too large');
  end if;
  if p_paid_on is null then
    perform private.payment_error('enter the date the payment was received');
  end if;
  if p_paid_on < date '2000-01-01' or p_paid_on > (now() at time zone t.timezone)::date then
    perform private.payment_error('the payment date can''t be in the future');
  end if;
  if v_reference is not null and length(v_reference) > 200 then
    perform private.payment_error('the reference is limited to 200 characters');
  end if;
  if v_note is not null and length(v_note) > 2000 then
    perform private.payment_error('the note is limited to 2,000 characters');
  end if;
  if not coalesce(p_confirm_duplicate, false) and exists (
    select 1 from public.event_payments x
    where x.tenant_id = e.tenant_id and x.event_id = e.id and x.invalidated_at is null
      and x.amount_cents = p_amount_cents and x.paid_on = p_paid_on) then
    raise exception 'payment_possible_duplicate: a payment with the same amount and date is already recorded for this event. If this is a separate payment, confirm it and record it again'
      using errcode = 'invalid_parameter_value';
  end if;

  insert into public.event_payments (tenant_id, event_id, amount_cents, currency, paid_on, reference, note, idempotency_key,
    recorded_by_user_id, recorded_by_membership_id, recorded_by_email)
  values (e.tenant_id, e.id, p_amount_cents, t.currency, p_paid_on, v_reference, v_note, p_idempotency_key,
    (select auth.uid()), v_membership_id, (select lower(u.email) from auth.users u where u.id = (select auth.uid())))
  returning id into v_id;
  perform private.audit(e.tenant_id, 'event', e.id, 'payment_recorded', 'staff', (select auth.uid()),
    jsonb_build_object('payment_id', v_id, 'amount_cents', p_amount_cents, 'currency', t.currency, 'paid_on', p_paid_on));
  -- The payment may complete a signed contract's deposit: same transaction.
  v_booking := private.evaluate_booking(e.id, 'staff', (select auth.uid()), false);
  return jsonb_build_object('status', 'recorded', 'payment_id', v_id, 'booking', v_booking ->> 'status');
end;
$$;


ALTER FUNCTION "public"."record_event_payment"("p_event_id" "uuid", "p_amount_cents" bigint, "p_paid_on" "date", "p_reference" "text", "p_note" "text", "p_idempotency_key" "uuid", "p_confirm_duplicate" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_tenant_logo"("p_tenant_id" "uuid", "p_user_id" "uuid", "p_storage_path" "text", "p_sha256" "text", "p_byte_size" integer, "p_width" integer, "p_height" integer, "p_needs_dark_background" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_object record;
  v_id uuid;
begin
  if not exists (select 1 from public.tenant_memberships m
                 where m.tenant_id = p_tenant_id and m.user_id = p_user_id and m.role = 'owner') then
    raise exception 'only the owner can change branding' using errcode = 'insufficient_privilege';
  end if;
  if (select count(*) from public.tenant_logos l where l.tenant_id = p_tenant_id and l.created_at > now() - interval '1 day') >= 30 then
    raise exception 'branding_invalid: too many logo uploads today. Try again tomorrow' using errcode = 'invalid_parameter_value';
  end if;
  select (o.metadata ->> 'size')::bigint as size, o.metadata ->> 'mimetype' as mimetype into v_object
  from storage.objects o where o.bucket_id = 'tenant-logos' and o.name = p_storage_path;
  if not found or v_object.size is distinct from p_byte_size or v_object.mimetype is distinct from 'image/png' then
    raise exception 'branding_invalid: the stored logo is missing or does not match' using errcode = 'invalid_parameter_value';
  end if;
  insert into public.tenant_logos (tenant_id, storage_path, sha256, byte_size, width, height, needs_dark_background, uploaded_by)
  values (p_tenant_id, p_storage_path, p_sha256, p_byte_size, p_width, p_height, p_needs_dark_background, p_user_id)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."register_tenant_logo"("p_tenant_id" "uuid", "p_user_id" "uuid", "p_storage_path" "text", "p_sha256" "text", "p_byte_size" integer, "p_width" integer, "p_height" integer, "p_needs_dark_background" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_event_contact"("p_event_id" "uuid", "p_event_client_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  r public.event_clients%rowtype;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into e from public.events where id = p_event_id for update;
  -- Only a contact of this event in this business.
  delete from public.event_clients
  where id = p_event_client_id and tenant_id = e.tenant_id and event_id = e.id
  returning * into r;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.audit(e.tenant_id, 'event', e.id, 'contact_removed', 'staff', (select auth.uid()),
    jsonb_build_object('client_id', r.client_id, 'primary', r.is_primary, 'signer', r.can_sign));
  return jsonb_build_object('removed', true);
end;
$$;


ALTER FUNCTION "public"."remove_event_contact"("p_event_id" "uuid", "p_event_client_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_event_contact"("p_event_id" "uuid", "p_event_client_id" "uuid") IS 'Removes one contact from one event (the row must belong to that event and business). Staff of the business only.';



CREATE OR REPLACE FUNCTION "public"."remove_planning_template_item"("p_item_id" "uuid", "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.planning_template_items%rowtype;
  t public.planning_templates%rowtype;
begin
  select * into i from public.planning_template_items where id = p_item_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  t := private.lock_planning_template(i.template_id, p_expected_version);
  if i.key = 'basics' then
    perform private.planning_error('Event basics is part of every template');
  end if;
  delete from public.planning_template_items where id = i.id;
  perform private.renumber_template_siblings(t.id, i.parent_id, i.kind);
  return private.bump_planning_template(t.id);
end;
$$;


