CREATE OR REPLACE FUNCTION "public"."resend_contract"("p_contract_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  v_problems jsonb;
  v_expires timestamptz;
begin
  c := private.lock_contract_for_staff(p_contract_id);
  if c.status <> 'sent' then
    raise exception 'contract_not_resendable: only a sent, unsigned contract can be resent (this one is %)', c.status
      using errcode = 'invalid_parameter_value';
  end if;
  v_problems := private.contract_send_problems(c.id);
  if jsonb_array_length(v_problems) > 0 then
    raise exception 'contract_not_sendable: %', private.contract_problem_text(v_problems) using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from public.access_links l where l.purpose = 'contract' and l.contract_id = c.id
             and l.created_at > now() - interval '2 minutes')
     or (select count(*) from public.access_links l where l.purpose = 'contract' and l.contract_id = c.id
         and l.created_at > now() - interval '1 day') >= 10 then
    raise exception 'contract_resend_too_soon: this contract was sent very recently. Wait a few minutes before resending'
      using errcode = 'invalid_parameter_value';
  end if;

  perform private.retire_contract_invitations(c.id, 'replaced by a resend');
  v_expires := private.issue_contract_invitation(c, p_link_id, p_token_hash);
  perform private.audit(c.tenant_id, 'contract', c.id, 'resent', 'staff', (select auth.uid()), jsonb_build_object('invitation_id', p_link_id));
  return jsonb_build_object('status', 'sent', 'contract_id', c.id, 'sent_at', c.sent_at, 'recipient_email', c.signer_email,
    'invitation_expires_at', v_expires);
end;
$$;


ALTER FUNCTION "public"."resend_contract"("p_contract_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resend_platform_invitation"("p_invitation_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  i public.platform_invitations%rowtype;
  v_expires timestamptz := now() + interval '14 days';
begin
  perform private.require_platform_admin();
  if p_link_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation link' using errcode = 'invalid_parameter_value';
  end if;
  select * into i from public.platform_invitations where id = p_invitation_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if i.accepted_at is not null then
    raise exception 'invitation_not_resendable: this invitation was already accepted' using errcode = 'invalid_parameter_value';
  end if;
  if i.revoked_at is not null then
    raise exception 'invitation_not_resendable: this invitation was revoked. Send a new invitation instead' using errcode = 'invalid_parameter_value';
  end if;
  if i.last_sent_at > now() - interval '2 minutes'
     or (select count(*) from public.email_outbox o where o.tenant_id is null and o.entity_type = 'platform_invitation'
         and o.entity_id = i.id and o.event_type = 'platform_invitation' and o.created_at > now() - interval '1 day') >= 10 then
    raise exception 'invitation_resend_too_soon: this invitation was sent very recently. Wait a few minutes before resending'
      using errcode = 'invalid_parameter_value';
  end if;

  perform private.cancel_platform_invitation_emails(i.id, 'replaced by a resend');
  update public.platform_invitations
    set link_id = p_link_id, token_hash = p_token_hash, expires_at = v_expires,
        send_count = send_count + 1, last_sent_at = now()
    where id = i.id;
  perform private.enqueue_platform_email('platform_invitation', i.email, i.id,
    jsonb_build_object('link_id', p_link_id, 'expires_at', v_expires), 'platform_invitation:' || p_link_id);
  perform private.platform_audit('platform_invitation', i.id, 'resent', (select auth.uid()),
    jsonb_build_object('previous_link_id', i.link_id, 'link_id', p_link_id, 'expires_at', v_expires));
  return jsonb_build_object('status', 'sent', 'invitation_id', i.id, 'email', i.email, 'expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."resend_platform_invitation"("p_invitation_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resend_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  i public.staff_invitations%rowtype;
  v_expires timestamptz := now() + interval '7 days';
begin
  perform private.require_owner_of(p_tenant_id);
  if exists (select 1 from public.tenants t where t.id = p_tenant_id and t.archived_at is not null) then
    raise exception 'workspace_archived: this business is archived' using errcode = 'invalid_parameter_value';
  end if;
  if p_link_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation request' using errcode = 'invalid_parameter_value';
  end if;
  select * into i from public.staff_invitations where tenant_id = p_tenant_id and id = p_invitation_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if i.link_id = p_link_id then
    return jsonb_build_object('status', 'sent', 'replayed', true, 'email', i.email, 'expires_at', i.expires_at);
  end if;
  if i.accepted_at is not null then
    raise exception 'invitation_not_resendable: this invitation was already accepted' using errcode = 'invalid_parameter_value';
  end if;
  if i.revoked_at is not null then
    raise exception 'invitation_not_resendable: this invitation was cancelled. Send a new invitation instead' using errcode = 'invalid_parameter_value';
  end if;
  if i.last_sent_at > now() - interval '2 minutes'
     or (select count(*) from public.email_outbox o where o.entity_type = 'staff_invitation' and o.entity_id = i.id
         and o.event_type = 'staff_invitation' and o.created_at > now() - interval '1 day') >= 10 then
    raise exception 'invitation_resend_too_soon: this invitation was sent very recently. Wait a few minutes before resending'
      using errcode = 'invalid_parameter_value';
  end if;

  perform private.cancel_staff_invitation_emails(i.id, 'replaced by a resend');
  update public.staff_invitations
    set link_id = p_link_id, token_hash = p_token_hash, expires_at = v_expires, send_count = send_count + 1, last_sent_at = now()
    where id = i.id;
  perform private.enqueue_staff_email(p_tenant_id, 'staff_invitation', i.email, i.id,
    jsonb_build_object('link_id', p_link_id, 'expires_at', v_expires), 'staff_invitation:' || p_link_id);
  perform private.audit(p_tenant_id, 'staff_invitation', i.id, 'resent', 'staff', (select auth.uid()),
    jsonb_build_object('expires_at', v_expires, 'send_count', i.send_count + 1));
  return jsonb_build_object('status', 'sent', 'replayed', false, 'email', i.email, 'expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."resend_staff_invitation"("p_tenant_id" "uuid", "p_invitation_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_workspace"("p_tenant_id" "uuid", "p_expected_version" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  t public.tenants%rowtype;
  v_reason text;
  v_since timestamptz;
begin
  perform private.require_platform_admin();
  v_reason := private.workspace_suspension_reason(p_reason);
  select * into t from public.tenants where id = p_tenant_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if t.suspended_at is null then
    return jsonb_build_object('status', 'active', 'replayed', true, 'version', t.suspension_version);
  end if;
  if p_expected_version is distinct from t.suspension_version then
    raise exception 'workspace suspension was changed elsewhere' using errcode = 'PT409';
  end if;
  v_since := t.suspended_at;
  perform set_config('flux.workspace_suspension', t.id::text, true);
  update public.tenants set suspended_at = null, suspension_version = suspension_version + 1
    where id = t.id returning * into t;
  perform set_config('flux.workspace_suspension', '', true);
  perform private.platform_audit('workspace', t.id, 'restored', (select auth.uid()),
    jsonb_build_object('reason', v_reason, 'slug', t.slug, 'version', t.suspension_version, 'suspended_since', v_since));
  return jsonb_build_object('status', 'active', 'replayed', false, 'version', t.suspension_version);
end;
$$;


ALTER FUNCTION "public"."restore_workspace"("p_tenant_id" "uuid", "p_expected_version" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."retry_email_outbox"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant uuid;
begin
  select o.tenant_id into v_tenant from public.email_outbox o where o.id = p_id;
  if v_tenant is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_tenant);
  update public.email_outbox
    set status = 'pending', max_attempts = least(attempts + 3, 50), next_attempt_at = now()
    where id = p_id and status = 'failed';
  return found;
end;
$$;


ALTER FUNCTION "public"."retry_email_outbox"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_contract_for_send"("p_contract_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  v_problems jsonb;
begin
  select * into c from public.contracts where id = p_contract_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(c.tenant_id);
  v_problems := private.contract_send_problems(c.id);
  return jsonb_build_object(
    'contract_id', c.id,
    'status', c.status,
    'sent_at', c.sent_at,
    'eligible', jsonb_array_length(v_problems) = 0,
    'problems', v_problems,
    'can_send', c.status = 'draft' and jsonb_array_length(v_problems) = 0,
    'send_unavailable_reason', case
      when c.status = 'signed' then 'This contract has been signed. It can no longer be sent, resent or voided.'
      when c.status = 'sent' then 'This contract has already been sent. Resend or void it from the contract page.'
      when c.status <> 'draft' then 'This contract is ' || c.status || ' and cannot be sent.'
      when jsonb_array_length(v_problems) > 0 then 'Fix the problems above before sending.'
      end,
    'signer', jsonb_build_object('name', c.signer_name, 'email', c.signer_email),
    'business', c.party_snapshot -> 'business',
    'deposit_percent', c.deposit_percent,
    'deposit_cents', c.deposit_cents,
    'balance_cents', c.balance_cents,
    'total_cents', c.total_cents,
    'currency', c.currency,
    'balance_due_date', c.balance_due_date,
    'content_sha256', c.content_sha256
  );
end;
$$;


ALTER FUNCTION "public"."review_contract_for_send"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_platform_invitation"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.platform_invitations%rowtype;
begin
  perform private.require_platform_admin();
  select * into i from public.platform_invitations where id = p_invitation_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if i.revoked_at is not null then
    return jsonb_build_object('status', 'revoked', 'replayed', true);
  end if;
  if i.accepted_at is not null then
    raise exception 'invitation_not_revocable: this invitation was already accepted and its workspace created'
      using errcode = 'invalid_parameter_value';
  end if;
  update public.platform_invitations set revoked_at = now(), revoked_by = (select auth.uid()) where id = i.id;
  perform private.cancel_platform_invitation_emails(i.id, 'invitation revoked');
  perform private.platform_audit('platform_invitation', i.id, 'revoked', (select auth.uid()), '{}'::jsonb);
  return jsonb_build_object('status', 'revoked', 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."revoke_platform_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_contract_template_draft"("p_version_id" "uuid", "p_expected_draft_version" integer, "p_title" "text", "p_sections" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_version public.contract_template_versions%rowtype;
  v_problem text;
begin
  select * into v_version from public.contract_template_versions where id = p_version_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_version.tenant_id);
  if v_version.published_at is not null then
    perform private.contract_error('this version is published and cannot be edited; open a new draft version');
  end if;
  if v_version.draft_version <> p_expected_draft_version then
    raise exception 'draft_version_conflict: expected %, current %', p_expected_draft_version, v_version.draft_version
      using errcode = 'PT409';
  end if;
  v_problem := private.contract_template_problem(p_title, p_sections);
  if v_problem is not null then
    perform private.contract_error(v_problem);
  end if;

  update public.contract_template_versions
    set title = btrim(p_title), sections = p_sections, draft_version = draft_version + 1
    where id = v_version.id;
  return v_version.draft_version + 1;
end;
$$;


ALTER FUNCTION "public"."save_contract_template_draft"("p_version_id" "uuid", "p_expected_draft_version" integer, "p_title" "text", "p_sections" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_contract"("p_contract_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  v_problems jsonb;
  v_expires timestamptz;
begin
  c := private.lock_contract_for_staff(p_contract_id);
  if c.status = 'sent' then
    return jsonb_build_object('status', 'sent', 'replayed', true, 'contract_id', c.id, 'sent_at', c.sent_at,
      'recipient_email', c.signer_email);
  end if;
  v_problems := private.contract_send_problems(c.id);
  if c.status <> 'draft' then
    raise exception 'contract_not_sendable: this contract is %', c.status using errcode = 'invalid_parameter_value';
  end if;
  if jsonb_array_length(v_problems) > 0 then
    raise exception 'contract_not_sendable: %', private.contract_problem_text(v_problems) using errcode = 'invalid_parameter_value';
  end if;

  perform set_config('flux.sending_contract', c.id::text, true);
  update public.contracts set status = 'sent' where id = c.id returning * into c;
  perform set_config('flux.sending_contract', '', true);
  v_expires := private.issue_contract_invitation(c, p_link_id, p_token_hash);
  perform private.audit(c.tenant_id, 'contract', c.id, 'sent', 'staff', (select auth.uid()),
    jsonb_build_object('invitation_id', p_link_id, 'content_sha256', c.content_sha256));
  return jsonb_build_object('status', 'sent', 'replayed', false, 'contract_id', c.id, 'sent_at', c.sent_at,
    'recipient_email', c.signer_email, 'invitation_expires_at', v_expires);
end;
$$;


ALTER FUNCTION "public"."send_contract"("p_contract_id" "uuid", "p_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_planning_invitation"("p_event_id" "uuid", "p_invitation_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  e public.events%rowtype;
  t public.tenants%rowtype;
  v_plan public.event_plans%rowtype;
  v_client public.clients%rowtype;
  v_existing public.planning_invitations%rowtype;
  v_expires timestamptz := now() + interval '14 days';
  v_replaced integer;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into e from public.events where id = e.id for update;
  select * into t from public.tenants where id = e.tenant_id;

  if p_invitation_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid invitation link' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_existing from public.planning_invitations where id = p_invitation_id;
  if found then
    if v_existing.event_id <> e.id or v_existing.token_hash <> p_token_hash then
      raise exception 'invalid invitation link' using errcode = 'invalid_parameter_value';
    end if;
    return jsonb_build_object('status', 'sent', 'replayed', true, 'invitation_id', v_existing.id,
      'recipient_email', v_existing.email, 'expires_at', v_existing.expires_at);
  end if;

  if e.archived_at is not null or t.archived_at is not null then
    perform private.planning_error('the event is archived. Unarchive it before inviting the client');
  end if;
  if not private.event_booked_for_planning(e) then
    perform private.planning_error('the event isn''t booked yet. Invite the client to planning once the booking is confirmed');
  end if;
  select * into v_plan from public.event_plans where tenant_id = e.tenant_id and event_id = e.id;
  if not found or private.plan_awaiting_setup(v_plan) then
    perform private.planning_error('set up planning before inviting the client');
  end if;
  if private.plan_editing_state(private.plan_deadline(e, v_plan), e.planning_override_until, now(), e.planning_client_closed_at) = 'closed' then
    perform private.planning_error('client editing is closed. Open client editing on the planning page before inviting the client');
  end if;
  select c.* into v_client
  from public.event_clients ec join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
  where ec.tenant_id = e.tenant_id and ec.event_id = e.id and ec.is_primary;
  if not found or v_client.archived_at is not null then
    perform private.planning_error('add an active primary contact to invite');
  end if;

  v_replaced := private.revoke_planning_invitations(e.id, 'replaced by a new invitation', (select auth.uid()));
  insert into public.planning_invitations (id, tenant_id, event_id, client_id, email, token_hash, expires_at, invited_by)
  values (p_invitation_id, e.tenant_id, e.id, v_client.id, lower(v_client.email), p_token_hash, v_expires, (select auth.uid()));
  perform private.enqueue_planning_email(e.tenant_id, 'planning_invitation', v_client.email, p_invitation_id,
    jsonb_build_object('client_name', v_client.name, 'event_title', e.title, 'event_date', e.event_date, 'expires_at', v_expires),
    'planning_invitation:' || p_invitation_id);
  perform private.audit(e.tenant_id, 'event', e.id, 'planning_invitation_sent', 'staff', (select auth.uid()),
    jsonb_build_object('invitation_id', p_invitation_id, 'client_id', v_client.id, 'replaced', v_replaced));
  return jsonb_build_object('status', 'sent', 'replayed', false, 'invitation_id', p_invitation_id,
    'recipient_email', lower(v_client.email), 'expires_at', v_expires);
end;
$_$;


ALTER FUNCTION "public"."send_planning_invitation"("p_event_id" "uuid", "p_invitation_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_proposal"("p_proposal_id" "uuid", "p_expected_draft_version" integer, "p_access_link_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_proposal public.proposals%rowtype;
  v_event public.events%rowtype;
  v_client record;
  v_snapshot jsonb;
  v_expires timestamptz;
  v_sha text;
  v_previous uuid[];
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' or p_access_link_id is null then
    raise exception 'invalid access link' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_proposal from public.proposals where id = p_proposal_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_proposal.tenant_id);

  -- Lock order everywhere: event, then proposal.
  select * into v_event from public.events where tenant_id = v_proposal.tenant_id and id = v_proposal.event_id for update;
  select * into v_proposal from public.proposals where id = p_proposal_id for update;

  if v_proposal.status <> 'draft' then
    raise exception 'proposal_already_sent: this proposal has already been sent' using errcode = 'invalid_parameter_value';
  end if;
  if v_proposal.draft_version <> p_expected_draft_version then
    raise exception 'draft_version_conflict: expected %, current %', p_expected_draft_version, v_proposal.draft_version
      using errcode = 'PT409';
  end if;
  if v_event.lifecycle_status not in ('lead', 'pending_approval', 'awaiting_signature') then
    perform private.offer_error('event is ' || v_event.lifecycle_status);
  end if;

  select c.id, c.name, c.email, c.archived_at into v_client
  from public.event_clients ec
  join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
  where ec.tenant_id = v_event.tenant_id and ec.event_id = v_event.id and ec.is_primary;
  if not found then
    perform private.offer_error('the event needs a primary contact before sending');
  end if;
  if v_client.archived_at is not null then
    perform private.offer_error('the primary contact is archived');
  end if;

  v_snapshot := private.build_offer_snapshot(v_proposal.tenant_id, v_proposal.draft_offer);
  v_expires := now() + make_interval(days => (v_snapshot ->> 'expiry_days')::int);

  -- Supersede and revoke earlier actionable offers. Their frozen terms,
  -- submissions and approvals are preserved as history.
  select coalesce(array_agg(p.id), '{}') into v_previous
  from public.proposals p
  where p.event_id = v_event.id and p.id <> v_proposal.id and p.status in ('sent', 'submitted', 'approved');
  update public.proposals set status = 'superseded' where id = any (v_previous);
  update public.access_links set revoked_at = now() where proposal_id = any (v_previous) and revoked_at is null;
  update public.proposal_sessions set revoked_at = now() where proposal_id = any (v_previous) and revoked_at is null;
  update public.email_outbox set status = 'cancelled', last_error = 'superseded by a newer revision'
    where entity_id = any (v_previous) and event_type = 'proposal_sent' and status = 'pending';

  update public.proposals
    set offer_snapshot = v_snapshot,
        status = 'sent',
        sent_at = now(),
        expires_at = v_expires,
        supersedes_id = case when v_event.active_proposal_id = any (v_previous) then v_event.active_proposal_id end
    where id = v_proposal.id
    returning offer_sha256 into v_sha;

  insert into public.access_links (id, tenant_id, purpose, proposal_id, intended_client_id, token_hash, expires_at)
  values (p_access_link_id, v_proposal.tenant_id, 'proposal', v_proposal.id, v_client.id, p_token_hash,
          -- The link outlives the offer deadline so the client can still see status.
          v_expires + interval '60 days');

  update public.events set active_proposal_id = v_proposal.id, lifecycle_status = 'lead' where id = v_event.id;

  perform private.enqueue_email(
    v_proposal.tenant_id, 'proposal_sent', v_client.email, v_proposal.id, p_access_link_id,
    jsonb_build_object('event_title', v_event.title, 'event_date', v_event.event_date, 'client_name', v_client.name,
                       'expires_at', v_expires, 'revision', v_proposal.revision),
    'proposal_sent:' || v_proposal.id
  );
  perform private.audit(v_proposal.tenant_id, 'proposal', v_proposal.id, 'sent', 'staff', (select auth.uid()),
    jsonb_build_object('revision', v_proposal.revision, 'offer_sha256', v_sha, 'superseded', to_jsonb(v_previous)));

  return jsonb_build_object('status', 'sent', 'proposal_id', v_proposal.id, 'expires_at', v_expires,
                            'recipient_email', v_client.email, 'offer_sha256', v_sha);
end;
$_$;


ALTER FUNCTION "public"."send_proposal"("p_proposal_id" "uuid", "p_expected_draft_version" integer, "p_access_link_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_signed_contract_copies"("p_contract_id" "uuid", "p_recipients" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
  v_expected text[];
  v_result jsonb;
begin
  select * into c from public.contracts where id = p_contract_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(c.tenant_id);
  -- Lock order: event, then contract (as everywhere).
  perform 1 from public.events where tenant_id = c.tenant_id and id = c.event_id for update;
  if c.status <> 'signed' or not exists (select 1 from public.contract_documents d where d.contract_id = c.id and d.kind = 'signed_contract') then
    raise exception 'contract_document_invalid: generate the signed PDF before sending copies' using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from public.events e where e.tenant_id = c.tenant_id and e.id = c.event_id and e.archived_at is not null) then
    raise exception 'contract_document_invalid: the event is archived. Unarchive it before sending copies' using errcode = 'invalid_parameter_value';
  end if;
  select array_agg(x order by x) into v_expected from unnest(array[
    lower(c.signer_email), lower(c.party_snapshot -> 'business' ->> 'contact_email')]) x where x is not null;
  if (select array_agg(lower(btrim(x)) order by lower(btrim(x))) from unnest(coalesce(p_recipients, '{}')) x) is distinct from v_expected then
    raise exception 'contract_document_invalid: the recipients changed. Reload the page and confirm them again' using errcode = 'invalid_parameter_value';
  end if;
  v_result := private.enqueue_signed_copy_emails(c.id);
  perform private.audit(c.tenant_id, 'contract', c.id, 'signed_copies_requested', 'staff', (select auth.uid()),
    jsonb_build_object('recipients', to_jsonb(v_expected)));
  return v_result;
end;
$$;


ALTER FUNCTION "public"."send_signed_contract_copies"("p_contract_id" "uuid", "p_recipients" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_client_archived"("p_client_id" "uuid", "p_archived" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_client public.clients%rowtype;
  v_events integer;
begin
  select * into v_client from public.clients where id = p_client_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_client.tenant_id);
  if p_archived is null then
    raise exception 'archive_invalid: choose archive or restore' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_client from public.clients where id = p_client_id for update;
  -- Already in the requested state (a repeated click or another tab): nothing changes.
  if p_archived = (v_client.archived_at is not null) then
    return jsonb_build_object('status', case when p_archived then 'archived' else 'active' end, 'replayed', true);
  end if;
  update public.clients set archived_at = case when p_archived then now() end where id = v_client.id;
  select count(*) into v_events from public.event_clients ec where ec.tenant_id = v_client.tenant_id and ec.client_id = v_client.id;
  perform private.audit(v_client.tenant_id, 'client', v_client.id, case when p_archived then 'client_archived' else 'client_restored' end,
    'staff', (select auth.uid()), jsonb_build_object('events', v_events));
  return jsonb_build_object('status', case when p_archived then 'archived' else 'active' end, 'replayed', false, 'events', v_events);
end;
$$;


