CREATE OR REPLACE FUNCTION "public"."set_event_invoice_url"("p_event_id" "uuid", "p_invoice_url" "text", "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  b public.event_billing%rowtype;
  v_url text := nullif(btrim(coalesce(p_invoice_url, '')), '');
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into e from public.events where id = e.id for update;
  if e.archived_at is not null then
    perform private.payment_error('the event is archived. Unarchive it before changing the invoice link');
  end if;
  if v_url is not null and not private.is_https_url(v_url) then
    perform private.payment_error('the invoice link must be a full https:// address');
  end if;
  select * into b from public.event_billing where event_id = e.id;
  if coalesce(b.version, 0) <> p_expected_version then
    raise exception 'draft_version_conflict: expected %, current %', p_expected_version, coalesce(b.version, 0)
      using errcode = 'PT409';
  end if;
  insert into public.event_billing as x (event_id, tenant_id, invoice_url, version, updated_by_user_id)
  values (e.id, e.tenant_id, v_url, 1, (select auth.uid()))
  on conflict (event_id) do update
    set invoice_url = excluded.invoice_url, version = x.version + 1, updated_by_user_id = excluded.updated_by_user_id
  returning * into b;
  perform private.audit(e.tenant_id, 'event', e.id, 'invoice_link_changed', 'staff', (select auth.uid()),
    jsonb_build_object('has_link', v_url is not null));
  return b.version;
end;
$$;


ALTER FUNCTION "public"."set_event_invoice_url"("p_event_id" "uuid", "p_invoice_url" "text", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_event_plan_item_enabled"("p_item_id" "uuid", "p_expected_version" integer, "p_enabled" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.event_plan_items%rowtype;
begin
  i := private.lock_plan_item_for_staff(p_item_id, p_expected_version);
  if i.key = 'basics' then
    perform private.planning_error('Event basics is part of every plan');
  end if;
  if p_enabled is null then
    perform private.planning_error('choose to hide or restore the item');
  end if;
  if p_enabled = (i.disabled_at is null) then
    return (select structure_version from public.event_plans where id = i.plan_id);
  end if;
  update public.event_plan_items set disabled_at = case when p_enabled then null else now() end where id = i.id;
  return private.bump_plan_structure(i.plan_id, case when p_enabled then 'restored' else 'disabled' end, i.key);
end;
$$;


