CREATE OR REPLACE FUNCTION "public"."sign_contract"("p_contract_id" "uuid", "p_tenant_slug" "text", "p_user_id" "uuid", "p_typed_name" "text", "p_content_sha256" "text", "p_consent_version" "text", "p_consent_accepted" boolean, "p_signature_path" "text", "p_signature_sha256" "text", "p_signature_bytes" integer, "p_signature_width" integer, "p_signature_height" integer, "p_user_agent" "text", "p_client_ip" "text", "p_client_ip_source" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  c public.contracts%rowtype;
  e public.events%rowtype;
  p public.proposals%rowtype;
  s public.contract_signatures%rowtype;
  v_email text;
  v_name text := btrim(coalesce(p_typed_name, ''));
  v_consent text;
  v_object record;
  v_ip inet;
  v_ua text := nullif(left(btrim(coalesce(p_user_agent, '')), 512), '');
begin
  select k.* into c from public.contracts k join public.tenants t on t.id = k.tenant_id
  where k.id = p_contract_id and t.slug = p_tenant_slug;
  if not found or p_user_id is null then
    return jsonb_build_object('status', 'rejected', 'code', 'unavailable', 'message', 'This contract isn''t available.');
  end if;

  -- Lock order everywhere: event, proposal, contract.
  select * into e from public.events where tenant_id = c.tenant_id and id = c.event_id for update;
  select * into p from public.proposals where tenant_id = c.tenant_id and id = c.proposal_id for update;
  select * into c from public.contracts where id = c.id for update;

  -- Identity and access: verified email matching the frozen signer, live
  -- access for the signer client, nothing archived. Same answer for every
  -- failure so nothing leaks to other accounts.
  if not private.signer_can_access_contract(c.id, p_user_id) then
    return jsonb_build_object('status', 'rejected', 'code', 'unavailable', 'message', 'This contract isn''t available.');
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = p_user_id;

  -- Already signed: the same signer gets the existing result back.
  if c.status = 'signed' then
    select * into s from public.contract_signatures where contract_id = c.id;
    if s.signer_user_id = p_user_id then
      return jsonb_build_object('status', 'signed', 'replayed', true, 'contract_id', c.id, 'signed_at', s.signed_at,
        'typed_name', s.typed_name);
    end if;
    return jsonb_build_object('status', 'rejected', 'code', 'unavailable', 'message', 'This contract isn''t available.');
  end if;

  -- Contract still sent, current, on the current approval.
  if c.status <> 'sent' or p.status <> 'approved' or e.active_proposal_id is distinct from c.proposal_id
     or e.lifecycle_status <> 'awaiting_signature'
     or not exists (select 1 from public.proposal_approvals a where a.tenant_id = c.tenant_id and a.id = c.approval_id
                    and a.proposal_id = c.proposal_id and a.selection_id = c.selection_id) then
    return jsonb_build_object('status', 'rejected', 'code', 'unavailable', 'message', 'This contract isn''t available.');
  end if;
  -- The frozen signing mode decides; "none" was generated from a legacy version.
  if c.signing_mode = 'none' or c.consent_version is null then
    return jsonb_build_object('status', 'rejected', 'code', 'signing_disabled',
      'message', 'This contract can''t be signed online. Contact your DJ for an updated contract.');
  end if;
  if p_content_sha256 is distinct from c.content_sha256 then
    return jsonb_build_object('status', 'rejected', 'code', 'content_changed',
      'message', 'This contract is not the one you were shown. Reload the page and read it again before signing.');
  end if;
  v_consent := private.contract_signing_consent(c.consent_version);
  if p_consent_version is distinct from c.consent_version or v_consent is null then
    return jsonb_build_object('status', 'rejected', 'code', 'consent_changed',
      'message', 'The signing statement has changed. Reload the page and read it again before signing.');
  end if;
  if p_consent_accepted is not true then
    return jsonb_build_object('status', 'rejected', 'code', 'consent_required',
      'message', 'Check the box to confirm you agree to sign electronically.');
  end if;
  if length(v_name) not between 1 and 200 then
    return jsonb_build_object('status', 'rejected', 'code', 'name_required', 'message', 'Type your full name (up to 200 characters).');
  end if;

  -- The signature image: stored first by the server, unique, in this
  -- contract's folder, with the declared size and type, and unused.
  if p_signature_path is null
     or p_signature_path !~ ('^' || c.tenant_id || '/' || c.id || '/[0-9a-f-]{36}\.png$')
     or p_signature_sha256 is null or p_signature_sha256 !~ '^[0-9a-f]{64}$'
     or p_signature_bytes is null or p_signature_bytes not between 1 and 262144
     or p_signature_width is null or p_signature_width not between 1 and 4096
     or p_signature_height is null or p_signature_height not between 1 and 4096 then
    return jsonb_build_object('status', 'rejected', 'code', 'signature_invalid', 'message', 'Draw your signature again.');
  end if;
  select o.name, (o.metadata ->> 'size')::bigint as size, o.metadata ->> 'mimetype' as mimetype into v_object
  from storage.objects o where o.bucket_id = 'contract-signatures' and o.name = p_signature_path;
  if not found or v_object.size is distinct from p_signature_bytes or v_object.mimetype is distinct from 'image/png'
     or exists (select 1 from public.contract_signatures x where x.signature_path = p_signature_path) then
    return jsonb_build_object('status', 'rejected', 'code', 'signature_invalid', 'message', 'Draw your signature again.');
  end if;

  if p_client_ip_source = 'vercel' and p_client_ip is not null then
    begin
      v_ip := p_client_ip::inet;
    exception when others then
      v_ip := null;
    end;
  end if;

  insert into public.contract_signatures (
    tenant_id, event_id, contract_id, signer_client_id, signer_user_id, signer_email, typed_name,
    signature_path, signature_sha256, signature_bytes, signature_width, signature_height,
    content_sha256, consent_version, consent_text, user_agent, client_ip, client_ip_source)
  values (
    c.tenant_id, c.event_id, c.id, c.signer_client_id, p_user_id, v_email, v_name,
    p_signature_path, p_signature_sha256, p_signature_bytes, p_signature_width, p_signature_height,
    c.content_sha256, c.consent_version, v_consent, v_ua, v_ip, case when v_ip is null then 'unavailable' else 'vercel' end)
  returning * into s;

  perform set_config('flux.signing_contract', c.id::text, true);
  update public.contracts set status = 'signed' where id = c.id returning * into c;
  perform set_config('flux.signing_contract', '', true);
  -- The signature row and the contract share one database timestamp.
  if s.signed_at <> c.signed_at then
    raise exception 'signing timestamps diverged' using errcode = 'internal_error';
  end if;

  perform private.retire_contract_invitations(c.id, 'contract signed');
  -- PDF work is queued in this same transaction and rendered later by the
  -- worker, so a rendering failure can never undo or lose the signature.
  perform private.enqueue_signed_contract_pdf(c.id, true, null);
  -- One audit event. Evidence stays in contract_signatures, not in the log.
  perform private.audit(c.tenant_id, 'contract', c.id, 'signed', 'client', p_user_id,
    jsonb_build_object('signature_id', s.id, 'content_sha256', c.content_sha256, 'signing_mode', c.signing_mode,
                       'consent_version', c.consent_version));
  -- Booking under the contract's frozen policy, in this same transaction
  -- (payments recorded before signing count). Rendering and email happen
  -- later, so they can never block or undo it.
  perform private.evaluate_booking(c.event_id, 'client', p_user_id, false);
  return jsonb_build_object('status', 'signed', 'replayed', false, 'contract_id', c.id, 'signed_at', s.signed_at,
    'typed_name', s.typed_name);
end;
$_$;


ALTER FUNCTION "public"."sign_contract"("p_contract_id" "uuid", "p_tenant_slug" "text", "p_user_id" "uuid", "p_typed_name" "text", "p_content_sha256" "text", "p_consent_version" "text", "p_consent_accepted" boolean, "p_signature_path" "text", "p_signature_sha256" "text", "p_signature_bytes" integer, "p_signature_width" integer, "p_signature_height" integer, "p_user_agent" "text", "p_client_ip" "text", "p_client_ip_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_client_list"("p_tenant_id" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_include_archived" boolean DEFAULT false, "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_sort" "text" DEFAULT 'name'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_at timestamptz := now();
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_digits text;
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(p_sort, 'name');
  v_result jsonb;
begin
  perform private.require_staff_of(p_tenant_id);
  if v_query is not null and length(v_query) > 100 then
    raise exception 'list_invalid: the search is too long' using errcode = 'invalid_parameter_value';
  end if;
  if v_sort not in ('name', 'recent') then
    raise exception 'list_invalid: unknown sort' using errcode = 'invalid_parameter_value';
  end if;
  -- A phone search compares digits only, and only once there are enough to mean something.
  v_digits := regexp_replace(coalesce(v_query, ''), '[^0-9]', '', 'g');
  if length(v_digits) < 3 then
    v_digits := null;
  end if;

  with candidates as (
    select c.id, c.name, c.email, c.phone, c.archived_at, c.created_at
    from public.clients c
    where c.tenant_id = p_tenant_id
      and (v_query is null
           or c.name ilike private.contains_pattern(v_query)
           or c.email ilike private.contains_pattern(v_query)
           or (v_digits is not null and regexp_replace(coalesce(c.phone, ''), '[^0-9]', '', 'g') like '%' || v_digits || '%'))
  ),
  matching as (
    select * from candidates where p_include_archived or archived_at is null
  ),
  page as (
    select m.* from matching m
    order by
      case when v_sort = 'recent' then m.created_at end desc,
      lower(m.name), m.email, m.id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'total', (select count(*) from matching),
    'archived_excluded', case when p_include_archived then 0 else (select count(*) from candidates where archived_at is not null) end,
    'tenant_clients', (select count(*) from public.clients c where c.tenant_id = p_tenant_id),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'name', p.name, 'email', p.email, 'phone', p.phone, 'archived', p.archived_at is not null,
               'created_at', p.created_at,
               'events', (select count(*) from public.event_clients ec where ec.tenant_id = p_tenant_id and ec.client_id = p.id),
               'next_event', (
                 select jsonb_build_object('id', e.id, 'title', e.title, 'event_date', e.event_date, 'today', (v_at at time zone e.timezone)::date)
                 from public.event_clients ec join public.events e on e.tenant_id = ec.tenant_id and e.id = ec.event_id
                 where ec.tenant_id = p_tenant_id and ec.client_id = p.id and e.archived_at is null
                   and e.event_date >= (v_at at time zone e.timezone)::date
                 order by e.event_date, e.title limit 1))
             order by
               case when v_sort = 'recent' then p.created_at end desc,
               lower(p.name), p.email, p.id)
      from page p), '[]'::jsonb))
  into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."staff_client_list"("p_tenant_id" "uuid", "p_query" "text", "p_include_archived" boolean, "p_limit" integer, "p_offset" integer, "p_sort" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."staff_client_list"("p_tenant_id" "uuid", "p_query" "text", "p_include_archived" boolean, "p_limit" integer, "p_offset" integer, "p_sort" "text") IS 'One page of a business''s clients for staff: name, email or phone search, archived filter and sort, with event counts. Read-only.';



CREATE OR REPLACE FUNCTION "public"."staff_dashboard"("p_tenant_id" "uuid", "p_upcoming_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_at timestamptz := now();
  v_limit integer := least(greatest(coalesce(p_upcoming_limit, 8), 1), 50);
  v_upcoming jsonb;
  v_more boolean;
  t public.tenants%rowtype;
begin
  perform private.require_staff_of(p_tenant_id);
  select * into t from public.tenants where id = p_tenant_id;

  with upcoming as (
    select e.id, e.title, e.event_date, e.timezone, e.venue_name, e.lifecycle_status, e.booking_source,
           (select c.name from public.event_clients ec join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
            where ec.tenant_id = e.tenant_id and ec.event_id = e.id and ec.is_primary limit 1) as client_name,
           exists (select 1 from public.contracts k where k.tenant_id = e.tenant_id and k.event_id = e.id and k.status = 'signed') as contract_signed,
           (select case when ap.status = 'sent' and ap.expires_at is not null and ap.expires_at <= v_at then 'expired' else ap.status end
            from public.proposals ap where ap.tenant_id = e.tenant_id and ap.id = e.active_proposal_id) as proposal_status,
           exists (select 1 from public.proposals d where d.tenant_id = e.tenant_id and d.event_id = e.id and d.status = 'draft') as proposal_draft,
           (select k.status from public.contracts k
            where k.tenant_id = e.tenant_id and k.event_id = e.id and k.status in ('signed', 'sent', 'draft')
            order by case k.status when 'signed' then 1 when 'sent' then 2 else 3 end limit 1) as contract_status
    from public.events e
    where e.tenant_id = p_tenant_id and e.archived_at is null
      and e.event_date >= (v_at at time zone e.timezone)::date
    order by e.event_date, e.title, e.id
    limit v_limit + 1
  )
  select coalesce(jsonb_agg(to_jsonb(u) order by u.event_date, u.title, u.id), '[]'::jsonb) into v_upcoming from upcoming u;
  v_more := jsonb_array_length(v_upcoming) > v_limit;
  if v_more then
    v_upcoming := v_upcoming - v_limit;
  end if;

  return jsonb_build_object(
    'now', v_at,
    'planning_window_days', 7,
    'upcoming', v_upcoming,
    'upcoming_more', v_more,
    'submitted', coalesce((
      select jsonb_agg(jsonb_build_object(
               'proposal_id', p.id, 'event_id', e.id, 'title', e.title, 'event_date', e.event_date, 'revision', p.revision,
               'submitted_at', (select max(s.submitted_at) from public.proposal_selections s where s.tenant_id = p.tenant_id and s.proposal_id = p.id))
             order by e.event_date, e.title)
      from public.proposals p
      join public.events e on e.tenant_id = p.tenant_id and e.id = p.event_id and e.active_proposal_id = p.id
      where p.tenant_id = p_tenant_id and p.status = 'submitted'
        and e.archived_at is null and e.lifecycle_status not in ('cancelled', 'completed')), '[]'::jsonb),
    'awaiting_deposit', coalesce((
      select jsonb_agg(jsonb_build_object(
               'event_id', e.id, 'title', e.title, 'event_date', e.event_date,
               'currency', s.summary ->> 'currency',
               'deposit_outstanding_cents', (s.summary ->> 'deposit_outstanding_cents')::bigint)
             order by e.event_date, e.title)
      from public.events e
      cross join lateral (select private.event_payment_summary(e.id) as summary) s
      where e.tenant_id = p_tenant_id and e.archived_at is null and e.lifecycle_status = 'awaiting_deposit'), '[]'::jsonb),
    'booking_check', coalesce((
      select jsonb_agg(jsonb_build_object('event_id', e.id, 'title', e.title, 'event_date', e.event_date) order by e.event_date, e.title)
      from public.events e
      where e.tenant_id = p_tenant_id and e.archived_at is null and e.lifecycle_status = 'awaiting_signature'
        and exists (select 1 from public.contracts k where k.tenant_id = e.tenant_id and k.event_id = e.id
                    and k.status = 'signed' and k.booking_policy is null)), '[]'::jsonb),
    'planning', coalesce((
      select jsonb_agg(jsonb_build_object(
               'event_id', x.id, 'title', x.title, 'event_date', x.event_date, 'timezone', x.timezone,
               'state', x.state, 'deadline', x.deadline, 'closes_at', x.closes_at,
               'requirements_met', (x.progress ->> 'requirements_met')::int,
               'requirements_total', (x.progress ->> 'requirements_total')::int)
             order by coalesce(x.closes_at, x.deadline), x.title)
      from (
        select c.*, private.plan_progress(c.plan_id) as progress
        from (
          select e.id, e.title, e.event_date, e.timezone, ep.id as plan_id, d.deadline,
                 private.plan_editing_state(d.deadline, e.planning_override_until, v_at, e.planning_client_closed_at) as state,
                 case private.plan_editing_state(d.deadline, e.planning_override_until, v_at, e.planning_client_closed_at)
                   when 'open' then d.deadline
                   when 'reopened' then e.planning_override_until end as closes_at
          from public.events e
          join public.event_plans ep on ep.tenant_id = e.tenant_id and ep.event_id = e.id
          cross join lateral (select private.plan_deadline(e, ep) as deadline) d
          where e.tenant_id = p_tenant_id and e.archived_at is null
            and (e.lifecycle_status = 'booked' or e.booking_source = 'external')
            and e.event_date >= (v_at at time zone e.timezone)::date
        ) c
        where c.state <> 'open' or c.deadline <= v_at + interval '7 days'
      ) x
      where (x.progress ->> 'requirements_met')::int < (x.progress ->> 'requirements_total')::int), '[]'::jsonb),
    'failed_emails', (select count(*) from public.email_outbox o where o.tenant_id = p_tenant_id and o.status = 'failed'),
    'setup', jsonb_build_object(
      'identity_saved', t.business_address is not null and t.contact_email is not null,
      'tax_categories', coalesce((select jsonb_agg(k order by k) from jsonb_object_keys(t.tax_categories) k), '[]'::jsonb),
      'used_tax_categories', coalesce((
        select jsonb_agg(distinct u.cat)
        from (select g.tax_category as cat from public.gear_items g where g.tenant_id = p_tenant_id and g.active
              union
              select pk.tax_category from public.packages pk where pk.tenant_id = p_tenant_id and pk.active) u), '[]'::jsonb),
      'active_packages', (select count(*) from public.packages pk where pk.tenant_id = p_tenant_id and pk.active),
      'usable_proposal_templates', (
        select count(*) from public.proposal_templates pt
        where pt.tenant_id = p_tenant_id and pt.active
          and (select count(*) from public.proposal_template_packages tp
               join public.packages pk on pk.tenant_id = tp.tenant_id and pk.id = tp.package_id and pk.active
               where tp.tenant_id = pt.tenant_id and tp.template_id = pt.id) = 3),
      'client_use_contract_templates', (
        select count(distinct ct.id) from public.contract_templates ct
        join public.contract_template_versions v on v.tenant_id = ct.tenant_id and v.template_id = ct.id
        where ct.tenant_id = p_tenant_id and ct.active and v.published_at is not null and v.usage = 'client_use')));
end;
$$;


ALTER FUNCTION "public"."staff_dashboard"("p_tenant_id" "uuid", "p_upcoming_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."staff_dashboard"("p_tenant_id" "uuid", "p_upcoming_limit" integer) IS 'Read-only dashboard facts for staff of one business: upcoming events and work needing attention. See the migration header for each rule.';



CREATE OR REPLACE FUNCTION "public"."staff_event_list"("p_tenant_id" "uuid", "p_view" "text" DEFAULT 'upcoming'::"text", "p_status" "text" DEFAULT NULL::"text", "p_query" "text" DEFAULT NULL::"text", "p_include_archived" boolean DEFAULT false, "p_limit" integer DEFAULT 25, "p_offset" integer DEFAULT 0, "p_event_type" "text" DEFAULT NULL::"text", "p_date_from" "date" DEFAULT NULL::"date", "p_date_to" "date" DEFAULT NULL::"date", "p_sort" "text" DEFAULT 'date'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_at timestamptz := now();
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(p_sort, 'date');
  v_result jsonb;
begin
  perform private.require_staff_of(p_tenant_id);
  if p_view is null or p_view not in ('upcoming', 'past', 'all') then
    raise exception 'list_invalid: unknown date view' using errcode = 'invalid_parameter_value';
  end if;
  if p_status is not null and p_status not in ('lead', 'pending_approval', 'awaiting_signature', 'awaiting_deposit', 'booked', 'completed', 'cancelled', 'external') then
    raise exception 'list_invalid: unknown status' using errcode = 'invalid_parameter_value';
  end if;
  if v_query is not null and length(v_query) > 100 then
    raise exception 'list_invalid: the search is too long' using errcode = 'invalid_parameter_value';
  end if;
  if p_event_type is not null and p_event_type !~ '^[a-z][a-z0-9_]{0,39}$' then
    raise exception 'list_invalid: unknown event type' using errcode = 'invalid_parameter_value';
  end if;
  if p_date_from is not null and p_date_to is not null and p_date_from > p_date_to then
    raise exception 'list_invalid: the start date is after the end date' using errcode = 'invalid_parameter_value';
  end if;
  if v_sort not in ('date', 'updated', 'created') then
    raise exception 'list_invalid: unknown sort' using errcode = 'invalid_parameter_value';
  end if;

  with candidates as (
    select e.id, e.title, e.event_type, e.event_date, e.timezone, e.venue_name, e.lifecycle_status, e.booking_source, e.archived_at,
           e.active_proposal_id, e.created_at, e.updated_at, pc.name as client_name
    from public.events e
    left join lateral (
      select c.name, c.email from public.event_clients ec join public.clients c on c.tenant_id = ec.tenant_id and c.id = ec.client_id
      where ec.tenant_id = e.tenant_id and ec.event_id = e.id and ec.is_primary limit 1
    ) pc on true
    where e.tenant_id = p_tenant_id
      and (p_view = 'all'
           or (p_view = 'upcoming' and e.event_date >= (v_at at time zone e.timezone)::date)
           or (p_view = 'past' and e.event_date < (v_at at time zone e.timezone)::date))
      -- "external": booked elsewhere; every other status is a Flux booking stage.
      and (p_status is null
           or (p_status = 'external' and e.booking_source = 'external')
           or (p_status <> 'external' and e.booking_source = 'flux' and e.lifecycle_status = p_status))
      and (p_event_type is null or e.event_type = p_event_type)
      and (p_date_from is null or e.event_date >= p_date_from)
      and (p_date_to is null or e.event_date <= p_date_to)
      and (v_query is null
           or e.title ilike private.contains_pattern(v_query)
           or e.venue_name ilike private.contains_pattern(v_query)
           or pc.name ilike private.contains_pattern(v_query)
           or pc.email ilike private.contains_pattern(v_query))
  ),
  matching as (
    select * from candidates where p_include_archived or archived_at is null
  ),
  page as (
    select m.* from matching m
    order by
      case when v_sort = 'updated' then m.updated_at end desc,
      case when v_sort = 'created' then m.created_at end desc,
      case when v_sort = 'date' and p_view = 'upcoming' then m.event_date end asc,
      case when v_sort = 'date' and p_view <> 'upcoming' then m.event_date end desc,
      m.event_date, m.title, m.id
    limit v_limit offset v_offset
  ),
  described as (
    select p.*,
           (select case when ap.status = 'sent' and ap.expires_at is not null and ap.expires_at <= v_at then 'expired' else ap.status end
            from public.proposals ap where ap.tenant_id = p_tenant_id and ap.id = p.active_proposal_id) as proposal_status,
           exists (select 1 from public.proposals d where d.tenant_id = p_tenant_id and d.event_id = p.id and d.status = 'draft') as proposal_draft,
           (select k.status from public.contracts k
            where k.tenant_id = p_tenant_id and k.event_id = p.id and k.status in ('signed', 'sent', 'draft')
            order by case k.status when 'signed' then 1 when 'sent' then 2 else 3 end limit 1) as contract_status
    from page p
  )
  select jsonb_build_object(
    'total', (select count(*) from matching),
    'archived_excluded', case when p_include_archived then 0 else (select count(*) from candidates where archived_at is not null) end,
    'tenant_events', (select count(*) from public.events e where e.tenant_id = p_tenant_id),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', d.id, 'title', d.title, 'event_type', d.event_type, 'event_date', d.event_date, 'timezone', d.timezone,
               'venue_name', d.venue_name, 'lifecycle_status', d.lifecycle_status, 'booking_source', d.booking_source,
               'archived', d.archived_at is not null,
               'client_name', d.client_name, 'today', (v_at at time zone d.timezone)::date,
               'contract_signed', coalesce(d.contract_status = 'signed', false),
               'proposal_status', d.proposal_status, 'proposal_draft', d.proposal_draft, 'contract_status', d.contract_status,
               'updated_at', d.updated_at, 'created_at', d.created_at)
             order by
               case when v_sort = 'updated' then d.updated_at end desc,
               case when v_sort = 'created' then d.created_at end desc,
               case when v_sort = 'date' and p_view = 'upcoming' then d.event_date end asc,
               case when v_sort = 'date' and p_view <> 'upcoming' then d.event_date end desc,
               d.event_date, d.title, d.id)
      from described d), '[]'::jsonb))
  into v_result;
  return v_result;
end;
$_$;


