CREATE OR REPLACE FUNCTION "public"."staff_invitation_for_token"("p_token_hash" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  i public.staff_invitations%rowtype;
begin
  if (select auth.uid()) is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    return null;
  end if;
  i := private.open_staff_invitation(p_token_hash);
  if i.id is null or private.current_verified_email() is distinct from i.email then
    return null;
  end if;
  return i.id;
end;
$_$;


ALTER FUNCTION "public"."staff_invitation_for_token"("p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_invitation_status"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.staff_invitations%rowtype;
  t public.tenants%rowtype;
  v_uid uuid := (select auth.uid());
  v_email text;
begin
  if v_uid is null then
    return jsonb_build_object('state', 'signed_out');
  end if;
  select * into i from public.staff_invitations where id = p_invitation_id;
  if not found then
    return jsonb_build_object('state', 'invalid');
  end if;
  select * into t from public.tenants where id = i.tenant_id;
  if i.accepted_at is not null then
    if i.accepted_by <> v_uid then
      return jsonb_build_object('state', 'invalid');
    end if;
    return jsonb_build_object('state', 'accepted', 'slug', t.slug, 'display_name', t.display_name,
      'active', exists (select 1 from public.tenant_memberships m where m.id = i.membership_id and m.removed_at is null)
                and t.suspended_at is null and t.archived_at is null);
  end if;
  if i.revoked_at is not null or i.expires_at <= now() then
    return jsonb_build_object('state', 'invalid');
  end if;
  v_email := private.current_verified_email();
  if v_email is null then
    return jsonb_build_object('state', 'unverified');
  end if;
  if v_email <> i.email then
    return jsonb_build_object('state', 'wrong_account', 'signed_in_email', v_email, 'intended_email', private.masked_email(i.email));
  end if;
  if t.suspended_at is not null or t.archived_at is not null then
    return jsonb_build_object('state', 'unavailable');
  end if;
  return jsonb_build_object('state', 'ready', 'email', i.email, 'display_name', t.display_name, 'expires_at', i.expires_at,
    'already_member', exists (select 1 from public.tenant_memberships m
                              where m.tenant_id = i.tenant_id and m.user_id = v_uid and m.removed_at is null));
end;
$$;


ALTER FUNCTION "public"."staff_invitation_status"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_planning_view"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.events%rowtype;
  v_plan public.event_plans%rowtype;
  v_basics record;
begin
  select * into e from public.events where id = p_event_id;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(e.tenant_id);
  select * into v_plan from public.event_plans where tenant_id = e.tenant_id and event_id = e.id;
  if not found then
    return jsonb_build_object('plan', null);
  end if;
  select i.id, r.answers, r.revision, r.updated_by_actor, r.updated_at into v_basics
  from public.event_plan_items i left join public.event_plan_responses r on r.tenant_id = i.tenant_id and r.item_id = i.id
  where i.plan_id = v_plan.id and i.key = 'basics';
  return jsonb_build_object(
    'plan', jsonb_build_object(
      'id', v_plan.id, 'origin', v_plan.origin, 'initialized_via', v_plan.initialized_via, 'created_at', v_plan.created_at,
      'source_template_id', v_plan.source_template_id, 'source_template_name', v_plan.source_template_name,
      'structure_version', v_plan.structure_version),
    'editing', private.plan_staff_editing(e, v_plan),
    'structure', private.plan_structure(v_plan.id, true),
    'basics', jsonb_build_object('item_id', v_basics.id, 'answers', coalesce(v_basics.answers, '{}'::jsonb),
                                 'revision', coalesce(v_basics.revision, 0), 'updated_by', v_basics.updated_by_actor,
                                 'updated_at', v_basics.updated_at),
    'stage_details', private.plan_stage_details(v_plan.id),
    'music', private.plan_music(v_plan.id),
    'moments', private.plan_moment_answers(v_plan.id),
    'event_contacts', private.plan_event_contacts(v_plan.id),
    'timeline_warnings', private.plan_timeline_warnings(v_plan.id),
    'imported', private.plan_latest_import(v_plan.id),
    'progress', private.plan_progress(v_plan.id));
end;
$$;


