CREATE OR REPLACE FUNCTION "public"."staff_team_overview"("p_tenant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_me uuid := private.require_owner_of(p_tenant_id);
begin
  return jsonb_build_object(
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'membership_id', m.id, 'email', lower(u.email), 'role', m.role, 'joined_at', m.created_at,
        'removed_at', m.removed_at, 'is_you', m.id = v_me)
        order by m.removed_at nulls first, (m.role = 'owner') desc, lower(u.email))
      from public.tenant_memberships m join auth.users u on u.id = m.user_id
      where m.tenant_id = p_tenant_id), '[]'::jsonb),
    'invitations', coalesce((
      select jsonb_agg(x.j order by x.open desc, x.created_at desc)
      from (
        select i.created_at, (i.accepted_at is null and i.revoked_at is null) as open,
          jsonb_build_object(
            'id', i.id, 'email', i.email,
            'state', case when i.accepted_at is not null then 'accepted' when i.revoked_at is not null then 'cancelled'
                          when i.expires_at <= now() then 'expired' else 'pending' end,
            'created_at', i.created_at, 'expires_at', i.expires_at, 'last_sent_at', i.last_sent_at, 'send_count', i.send_count,
            'accepted_at', i.accepted_at, 'revoked_at', i.revoked_at,
            'delivery_status', (select o.status from public.email_outbox o
              where o.entity_type = 'staff_invitation' and o.entity_id = i.id and o.event_type = 'staff_invitation'
                and o.payload ->> 'link_id' = i.link_id::text
              order by o.created_at desc limit 1)) as j
        from public.staff_invitations i
        where i.tenant_id = p_tenant_id
          -- Open ones always; closed ones for 30 days, as recent history.
          and ((i.accepted_at is null and i.revoked_at is null) or coalesce(i.accepted_at, i.revoked_at) > now() - interval '30 days')
        order by i.created_at desc
        limit 200
      ) x), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."staff_team_overview"("p_tenant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suspend_workspace"("p_tenant_id" "uuid", "p_expected_version" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  t public.tenants%rowtype;
  v_reason text;
  v_cancelled integer;
begin
  perform private.require_platform_admin();
  v_reason := private.workspace_suspension_reason(p_reason);
  select * into t from public.tenants where id = p_tenant_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if t.suspended_at is not null then
    return jsonb_build_object('status', 'suspended', 'replayed', true, 'version', t.suspension_version, 'suspended_at', t.suspended_at);
  end if;
  if exists (select 1 from public.tenant_memberships m
             where m.tenant_id = t.id and m.user_id = (select auth.uid()) and m.removed_at is null) then
    raise exception 'workspace_own: you belong to this workspace, so it can''t be suspended from your account'
      using errcode = 'invalid_parameter_value';
  end if;
  if p_expected_version is distinct from t.suspension_version then
    raise exception 'workspace suspension was changed elsewhere' using errcode = 'PT409';
  end if;

  perform set_config('flux.workspace_suspension', t.id::text, true);
  update public.tenants set suspended_at = now(), suspension_version = suspension_version + 1
    where id = t.id returning * into t;
  perform set_config('flux.workspace_suspension', '', true);
  -- Undelivered emails are cancelled, so restoration can't send obsolete ones.
  -- One already handed to the provider can't be recalled.
  update public.email_outbox
    set status = 'cancelled', locked_until = null, last_error = 'Cancelled: the workspace was suspended before delivery.'
    where tenant_id = t.id and status in ('pending', 'sending');
  get diagnostics v_cancelled = row_count;
  perform private.platform_audit('workspace', t.id, 'suspended', (select auth.uid()),
    jsonb_build_object('reason', v_reason, 'slug', t.slug, 'version', t.suspension_version, 'cancelled_emails', v_cancelled));
  return jsonb_build_object('status', 'suspended', 'replayed', false, 'version', t.suspension_version,
    'suspended_at', t.suspended_at, 'cancelled_emails', v_cancelled);
end;
$$;


ALTER FUNCTION "public"."suspend_workspace"("p_tenant_id" "uuid", "p_expected_version" integer, "p_reason" "text") OWNER TO "postgres";


