CREATE OR REPLACE FUNCTION "public"."update_booking_policy"("p_tenant_id" "uuid", "p_policy" "text", "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  t public.tenants%rowtype;
begin
  select m.role into v_role from public.tenant_memberships m where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid());
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change the booking policy' using errcode = 'insufficient_privilege';
  end if;
  select * into t from public.tenants where id = p_tenant_id for update;
  if t.archived_at is not null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if p_expected_version is null or t.booking_policy_version <> p_expected_version then
    raise exception 'booking policy was changed elsewhere' using errcode = 'PT409';
  end if;
  if p_policy is null or p_policy not in ('on_deposit', 'on_signature') then
    raise exception 'settings_invalid: choose when bookings are confirmed' using errcode = 'invalid_parameter_value';
  end if;
  update public.tenants set booking_confirmation_policy = p_policy, booking_policy_version = booking_policy_version + 1
  where id = t.id returning * into t;
  perform private.audit(t.id, 'tenant', t.id, 'booking_policy_changed', 'staff', (select auth.uid()), jsonb_build_object('policy', p_policy));
  return t.booking_policy_version;
end;
$$;


ALTER FUNCTION "public"."update_booking_policy"("p_tenant_id" "uuid", "p_policy" "text", "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_business_settings"("p_tenant_id" "uuid", "p_legal_name" "text", "p_business_address" "text", "p_contact_email" "text", "p_deposit_percent" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
begin
  select m.role into v_role from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid());
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change business settings' using errcode = 'insufficient_privilege';
  end if;
  if p_legal_name is null or length(btrim(p_legal_name)) not between 1 and 200 then
    raise exception 'settings_invalid: the legal business name must be 1 to 200 characters' using errcode = 'invalid_parameter_value';
  end if;
  if p_business_address is null or length(btrim(p_business_address)) not between 1 and 500 then
    raise exception 'settings_invalid: the business address must be 1 to 500 characters' using errcode = 'invalid_parameter_value';
  end if;
  if p_contact_email is null or not private.is_valid_email(lower(btrim(p_contact_email))) then
    raise exception 'settings_invalid: enter a valid contact email' using errcode = 'invalid_parameter_value';
  end if;
  if p_deposit_percent is null or p_deposit_percent not between 0 and 100 then
    raise exception 'settings_invalid: the deposit must be a whole percentage from 0 to 100' using errcode = 'invalid_parameter_value';
  end if;
  update public.tenants
    set business_name = btrim(p_legal_name), business_address = btrim(p_business_address),
        contact_email = lower(btrim(p_contact_email)), deposit_percent = p_deposit_percent
    where id = p_tenant_id;
  perform private.audit(p_tenant_id, 'tenant', p_tenant_id, 'business_settings_updated', 'staff', (select auth.uid()),
    jsonb_build_object('deposit_percent', p_deposit_percent));
end;
$$;


ALTER FUNCTION "public"."update_business_settings"("p_tenant_id" "uuid", "p_legal_name" "text", "p_business_address" "text", "p_contact_email" "text", "p_deposit_percent" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_planning_cutoff_days"("p_tenant_id" "uuid", "p_days" integer, "p_expected_version" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  t public.tenants%rowtype;
  v_before integer;
begin
  select m.role into v_role from public.tenant_memberships m where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid());
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change the planning deadline' using errcode = 'insufficient_privilege';
  end if;
  select * into t from public.tenants where id = p_tenant_id for update;
  if t.archived_at is not null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if p_expected_version is null or t.planning_settings_version <> p_expected_version then
    raise exception 'planning settings were changed elsewhere' using errcode = 'PT409';
  end if;
  if p_days is null or p_days < 0 or p_days > 365 then
    raise exception 'settings_invalid: enter a whole number of days from 0 to 365' using errcode = 'invalid_parameter_value';
  end if;
  v_before := t.planning_lock_days;
  update public.tenants set planning_lock_days = p_days, planning_settings_version = planning_settings_version + 1
  where id = t.id returning * into t;
  perform private.audit(t.id, 'tenant', t.id, 'planning_cutoff_days_changed', 'staff', (select auth.uid()),
    jsonb_build_object('before', v_before, 'after', p_days));
  return t.planning_settings_version;
end;
$$;


ALTER FUNCTION "public"."update_planning_cutoff_days"("p_tenant_id" "uuid", "p_days" integer, "p_expected_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_planning_dj_name"("p_tenant_id" "uuid", "p_dj_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  t public.tenants%rowtype;
  v_name text := nullif(btrim(regexp_replace(coalesce(p_dj_name, ''), '\s+', ' ', 'g')), '');
begin
  select m.role into v_role from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid()) and m.removed_at is null;
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change the DJ name' using errcode = 'insufficient_privilege';
  end if;
  select * into t from public.tenants where id = p_tenant_id for update;
  if t.archived_at is not null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if length(v_name) > 80 then
    raise exception 'settings_invalid: keep the DJ name under 80 characters' using errcode = 'invalid_parameter_value';
  end if;
  if v_name is not distinct from t.dj_name then
    return v_name;
  end if;
  update public.tenants set dj_name = v_name where id = t.id;
  perform private.audit(t.id, 'tenant', t.id, 'dj_name_changed', 'staff', (select auth.uid()), jsonb_build_object('set', v_name is not null));
  return v_name;
end;
$$;


ALTER FUNCTION "public"."update_planning_dj_name"("p_tenant_id" "uuid", "p_dj_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_planning_template"("p_template_id" "uuid", "p_expected_version" integer, "p_name" "text", "p_description" "text", "p_default_event_type" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  t public.planning_templates%rowtype;
  d record;
  v_type text := nullif(btrim(coalesce(p_default_event_type, '')), '');
begin
  t := private.lock_planning_template(p_template_id, p_expected_version);
  select * into d from private.planning_template_details(p_name, p_description);
  if v_type is not null and v_type !~ '^[a-z][a-z0-9_]{0,39}$' then
    perform private.planning_error('choose an event type from the list');
  end if;
  if v_type is not null and exists (
    select 1 from public.planning_templates o
    where o.tenant_id = t.tenant_id and o.default_event_type = v_type and o.id <> t.id) then
    perform private.planning_error('another template is already the default for that event type. Clear it there first');
  end if;
  update public.planning_templates
    set name = d.name, description = d.description, default_event_type = v_type, version = version + 1
    where id = t.id returning * into t;
  return t.version;
end;
$_$;


ALTER FUNCTION "public"."update_planning_template"("p_template_id" "uuid", "p_expected_version" integer, "p_name" "text", "p_description" "text", "p_default_event_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_proposal_draft"("p_proposal_id" "uuid", "p_expected_version" integer, "p_offer" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_proposal public.proposals%rowtype;
begin
  select * into v_proposal from public.proposals where id = p_proposal_id for update;
  if not found then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  perform private.require_staff_of(v_proposal.tenant_id);

  if v_proposal.status <> 'draft' or v_proposal.offer_snapshot is not null then
    raise exception 'the offer is frozen and cannot be edited' using errcode = 'invalid_parameter_value';
  end if;
  if v_proposal.draft_version <> p_expected_version then
    raise exception 'draft_version_conflict: expected %, current %', p_expected_version, v_proposal.draft_version
      using errcode = 'PT409';
  end if;
  if not private.is_valid_draft_offer(p_offer) then
    perform private.offer_error('draft offer has an invalid shape');
  end if;
  if private.is_uuid_text(p_offer ->> 'template_id') and not exists (
    select 1 from public.proposal_templates t
    where t.tenant_id = v_proposal.tenant_id and t.id = (p_offer ->> 'template_id')::uuid
  ) then
    perform private.offer_error('template not found');
  end if;

  update public.proposals
    set draft_offer = p_offer,
        draft_version = draft_version + 1,
        source_template_id = case when private.is_uuid_text(p_offer ->> 'template_id') then (p_offer ->> 'template_id')::uuid end
    where id = v_proposal.id;
  return v_proposal.draft_version + 1;
end;
$$;


ALTER FUNCTION "public"."update_proposal_draft"("p_proposal_id" "uuid", "p_expected_version" integer, "p_offer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_reply_to_email"("p_tenant_id" "uuid", "p_reply_to" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  t public.tenants%rowtype;
  v_address text := nullif(lower(btrim(coalesce(p_reply_to, ''))), '');
begin
  select m.role into v_role from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid()) and m.removed_at is null;
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change the reply-to address' using errcode = 'insufficient_privilege';
  end if;
  select * into t from public.tenants where id = p_tenant_id for update;
  if t.archived_at is not null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_address is not null and (length(v_address) > 320 or not coalesce(private.is_valid_email(v_address), false)) then
    raise exception 'settings_invalid: enter a valid reply-to email address' using errcode = 'invalid_parameter_value';
  end if;
  if v_address is not distinct from t.reply_to_email then
    return v_address;
  end if;
  update public.tenants set reply_to_email = v_address where id = t.id;
  perform private.audit(t.id, 'tenant', t.id, 'reply_to_changed', 'staff', (select auth.uid()),
    jsonb_build_object('set', v_address is not null));
  return v_address;
end;
$$;


ALTER FUNCTION "public"."update_reply_to_email"("p_tenant_id" "uuid", "p_reply_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tax_settings"("p_tenant_id" "uuid", "p_expected_version" integer, "p_tax_config" "jsonb", "p_tax_categories" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_role text;
  v_tenant public.tenants%rowtype;
  v_config jsonb;
  v_bad text;
begin
  select m.role into v_role from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid());
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change tax settings' using errcode = 'insufficient_privilege';
  end if;

  select * into v_tenant from public.tenants where id = p_tenant_id for update;
  if v_tenant.archived_at is not null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if p_expected_version is null or v_tenant.tax_settings_version <> p_expected_version then
    raise exception 'tax settings were changed elsewhere' using errcode = 'PT409';
  end if;

  -- Taxes ---------------------------------------------------------------------
  if p_tax_config is null or jsonb_typeof(p_tax_config) <> 'array' then
    raise exception 'settings_invalid: the tax list is malformed' using errcode = 'invalid_parameter_value';
  end if;
  if jsonb_array_length(p_tax_config) > 5 then
    raise exception 'settings_invalid: at most 5 taxes can be configured' using errcode = 'invalid_parameter_value';
  end if;
  select string_agg(coalesce(t.item ->> 'label', '?'), ', ') into v_bad
  from jsonb_array_elements(p_tax_config) t(item)
  where jsonb_typeof(t.item) <> 'object'
     or jsonb_typeof(t.item -> 'code') <> 'string'
     or (t.item ->> 'code') !~ '^[A-Z0-9_]{1,16}$';
  if v_bad is not null then
    raise exception 'settings_invalid: invalid tax code for %', v_bad using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from jsonb_array_elements(p_tax_config) t(item)
             where jsonb_typeof(t.item -> 'label') <> 'string'
                or length(btrim(t.item ->> 'label')) not between 1 and 40) then
    raise exception 'settings_invalid: each tax needs a name of 1 to 40 characters' using errcode = 'invalid_parameter_value';
  end if;
  select string_agg(btrim(t.item ->> 'label'), ', ') into v_bad
  from jsonb_array_elements(p_tax_config) t(item)
  where jsonb_typeof(t.item -> 'rate_ppm') <> 'number'
     or (t.item ->> 'rate_ppm') !~ '^[0-9]+$'
     or (t.item ->> 'rate_ppm')::numeric > 1000000;
  if v_bad is not null then
    raise exception 'settings_invalid: the rate for % must be from 0%% to 100%% with at most 4 decimals', v_bad
      using errcode = 'invalid_parameter_value';
  end if;
  if (select count(distinct t.item ->> 'code') <> count(*) from jsonb_array_elements(p_tax_config) t(item)) then
    raise exception 'settings_invalid: tax codes must be unique' using errcode = 'invalid_parameter_value';
  end if;
  if (select count(distinct lower(btrim(t.item ->> 'label'))) <> count(*) from jsonb_array_elements(p_tax_config) t(item)) then
    raise exception 'settings_invalid: two taxes have the same name' using errcode = 'invalid_parameter_value';
  end if;
  -- Store exactly {code,label,rate_ppm}, labels trimmed, in the given order.
  select coalesce(jsonb_agg(jsonb_build_object(
           'code', t.item ->> 'code', 'label', btrim(t.item ->> 'label'), 'rate_ppm', (t.item ->> 'rate_ppm')::integer)
           order by t.ord), '[]'::jsonb)
    into v_config
  from jsonb_array_elements(p_tax_config) with ordinality t(item, ord);

  -- Categories ------------------------------------------------------------------
  if p_tax_categories is null or jsonb_typeof(p_tax_categories) <> 'object' then
    raise exception 'settings_invalid: the category mapping is malformed' using errcode = 'invalid_parameter_value';
  end if;
  if (select count(*) from jsonb_object_keys(p_tax_categories)) > 20 then
    raise exception 'settings_invalid: at most 20 tax categories can be configured' using errcode = 'invalid_parameter_value';
  end if;
  select string_agg(c.key, ', ') into v_bad
  from jsonb_each(p_tax_categories) c(key, codes)
  where not private.is_valid_key(c.key)
     or jsonb_typeof(c.codes) <> 'array'
     or exists (select 1 from jsonb_array_elements(c.codes) x(code) where jsonb_typeof(x.code) <> 'string')
     or (select count(distinct x.code) <> count(*) from jsonb_array_elements(c.codes) x(code));
  if v_bad is not null then
    raise exception 'settings_invalid: invalid tax category %', v_bad using errcode = 'invalid_parameter_value';
  end if;
  -- Every code a category lists must remain configured.
  select string_agg(distinct c.key || ' (' || (x.code #>> '{}') || ')', ', ') into v_bad
  from jsonb_each(p_tax_categories) c(key, codes), jsonb_array_elements(c.codes) x(code)
  where not exists (select 1 from jsonb_array_elements(v_config) t(item) where t.item ->> 'code' = x.code #>> '{}');
  if v_bad is not null then
    raise exception 'settings_invalid: these categories use a tax that is not configured: %', v_bad
      using errcode = 'invalid_parameter_value';
  end if;
  -- Categories in use by active gear or packages must stay mapped.
  select string_agg(distinct u.cat, ', ') into v_bad
  from (
    select g.tax_category as cat from public.gear_items g where g.tenant_id = p_tenant_id and g.active
    union
    select pk.tax_category from public.packages pk where pk.tenant_id = p_tenant_id and pk.active
  ) u
  where v_tenant.tax_categories ? u.cat and not (p_tax_categories ? u.cat);
  if v_bad is not null then
    raise exception 'settings_invalid: active gear or packages use these categories, so they must stay configured: %', v_bad
      using errcode = 'invalid_parameter_value';
  end if;

  update public.tenants
    set tax_config = v_config, tax_categories = p_tax_categories,
        tax_settings_version = tax_settings_version + 1
    where id = p_tenant_id;
  perform private.audit(p_tenant_id, 'tenant', p_tenant_id, 'tax_settings_updated', 'staff', (select auth.uid()),
    jsonb_build_object('tax_config', v_config, 'tax_categories', p_tax_categories,
                       'tax_settings_version', v_tenant.tax_settings_version + 1));
  return v_tenant.tax_settings_version + 1;
end;
$_$;


ALTER FUNCTION "public"."update_tax_settings"("p_tenant_id" "uuid", "p_expected_version" integer, "p_tax_config" "jsonb", "p_tax_categories" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_branding"("p_tenant_id" "uuid", "p_expected_version" integer, "p_logo_id" "uuid", "p_primary_color" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_role text;
  t public.tenants%rowtype;
  v_path text;
  v_color text := nullif(lower(btrim(coalesce(p_primary_color, ''))), '');
  v_colors jsonb;
begin
  select m.role into v_role from public.tenant_memberships m
  where m.tenant_id = p_tenant_id and m.user_id = (select auth.uid());
  if v_role is null then
    raise exception 'not found' using errcode = 'no_data_found';
  end if;
  if v_role <> 'owner' then
    raise exception 'only the owner can change branding' using errcode = 'insufficient_privilege';
  end if;
  select * into t from public.tenants where id = p_tenant_id for update;
  if t.suspended_at is not null then
    raise exception 'workspace_suspended: this workspace is suspended' using errcode = 'PT423';
  end if;
  if p_expected_version is distinct from t.branding_version then
    raise exception 'branding was changed elsewhere' using errcode = 'PT409';
  end if;
  if v_color is not null and v_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'branding_invalid: the colour must be a hex value like #1a2b3c' using errcode = 'invalid_parameter_value';
  end if;
  if p_logo_id is not null then
    select l.storage_path into v_path from public.tenant_logos l where l.tenant_id = p_tenant_id and l.id = p_logo_id;
    if v_path is null then
      raise exception 'branding_invalid: that logo is not available' using errcode = 'invalid_parameter_value';
    end if;
  end if;
  v_colors := case when v_color is null then t.brand_colors - 'primary' else t.brand_colors || jsonb_build_object('primary', v_color) end;

  update public.tenants
    set logo_storage_path = v_path, brand_colors = v_colors, branding_version = branding_version + 1
    where id = t.id;
  perform private.audit(t.id, 'tenant', t.id, 'branding_updated', 'staff', (select auth.uid()),
    jsonb_build_object('logo_changed', v_path is distinct from t.logo_storage_path, 'logo_storage_path', v_path,
                       'primary_color', v_color, 'version', t.branding_version + 1));
  return t.branding_version + 1;
end;
$_$;


ALTER FUNCTION "public"."update_tenant_branding"("p_tenant_id" "uuid", "p_expected_version" integer, "p_logo_id" "uuid", "p_primary_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_contract"("p_contract_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.contracts%rowtype;
begin
  if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then
    raise exception 'contract_void_invalid: give a reason (up to 500 characters)' using errcode = 'invalid_parameter_value';
  end if;
  c := private.lock_contract_for_staff(p_contract_id);
  if c.status = 'void' then
    return jsonb_build_object('status', 'void', 'replayed', true);
  end if;
  if c.status <> 'sent' then
    raise exception 'contract_void_invalid: only a sent, unsigned contract can be voided (this one is %)', c.status
      using errcode = 'invalid_parameter_value';
  end if;
  update public.contracts set status = 'void', void_reason = btrim(p_reason) where id = c.id;
  perform private.retire_contract_invitations(c.id, 'contract voided');
  perform private.enqueue_contract_void_notice(c.id);
  perform private.audit(c.tenant_id, 'contract', c.id, 'voided', 'staff', (select auth.uid()), jsonb_build_object('reason', btrim(p_reason)));
  return jsonb_build_object('status', 'void', 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."void_contract"("p_contract_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."contract_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    "contract_id" "uuid" NOT NULL,
    "kind" "text" DEFAULT 'signed_contract'::"text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'contract-documents'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "pdf_sha256" "text" NOT NULL,
    "byte_size" integer NOT NULL,
    "content_sha256" "text" NOT NULL,
    "signature_sha256" "text" NOT NULL,
    "renderer" "text" NOT NULL,
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contract_documents_bucket_fixed" CHECK (("storage_bucket" = 'contract-documents'::"text")),
    CONSTRAINT "contract_documents_byte_size_range" CHECK ((("byte_size" >= 1) AND ("byte_size" <= 10485760))),
    CONSTRAINT "contract_documents_content_sha256_format" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contract_documents_kind_valid" CHECK (("kind" = 'signed_contract'::"text")),
    CONSTRAINT "contract_documents_path_format" CHECK (("storage_path" ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.pdf$'::"text")),
    CONSTRAINT "contract_documents_pdf_sha256_format" CHECK (("pdf_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contract_documents_renderer_length" CHECK ((("length"("renderer") >= 1) AND ("length"("renderer") <= 60))),
    CONSTRAINT "contract_documents_signature_sha256_format" CHECK (("signature_sha256" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."contract_documents" OWNER TO "postgres";


COMMENT ON TABLE "public"."contract_documents" IS 'The one canonical signed PDF per signed contract. Immutable; written only by commit_contract_document. Retention is not decided.';



COMMENT ON COLUMN "public"."contract_documents"."pdf_sha256" IS 'SHA-256 of the final PDF file bytes (what is downloaded and attached). Not the contract content hash.';



CREATE OR REPLACE VIEW "private"."contract_document_orphans" AS
 SELECT "name",
    "created_at",
    (("metadata" ->> 'size'::"text"))::bigint AS "size"
   FROM "storage"."objects" "o"
  WHERE (("bucket_id" = 'contract-documents'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."contract_documents" "d"
          WHERE ("d"."storage_path" = "o"."name")))));


ALTER VIEW "private"."contract_document_orphans" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."contract_signatures" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    "contract_id" "uuid" NOT NULL,
    "signer_client_id" "uuid" NOT NULL,
    "signer_user_id" "uuid" NOT NULL,
    "signer_email" "text" NOT NULL,
    "typed_name" "text" NOT NULL,
    "signature_bucket" "text" DEFAULT 'contract-signatures'::"text" NOT NULL,
    "signature_path" "text" NOT NULL,
    "signature_sha256" "text" NOT NULL,
    "signature_bytes" integer NOT NULL,
    "signature_width" integer NOT NULL,
    "signature_height" integer NOT NULL,
    "content_sha256" "text" NOT NULL,
    "consent_version" "text" NOT NULL,
    "consent_text" "text" NOT NULL,
    "signed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_agent" "text",
    "client_ip" "inet",
    "client_ip_source" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "contract_signatures_bucket_fixed" CHECK (("signature_bucket" = 'contract-signatures'::"text")),
    CONSTRAINT "contract_signatures_bytes_range" CHECK ((("signature_bytes" >= 1) AND ("signature_bytes" <= 262144))),
    CONSTRAINT "contract_signatures_consent_text_present" CHECK (("length"("consent_text") > 0)),
    CONSTRAINT "contract_signatures_content_sha256_format" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contract_signatures_email_valid" CHECK ("private"."is_valid_email"("signer_email")),
    CONSTRAINT "contract_signatures_height_range" CHECK ((("signature_height" >= 1) AND ("signature_height" <= 4096))),
    CONSTRAINT "contract_signatures_ip_matches_source" CHECK ((("client_ip" IS NULL) = ("client_ip_source" = 'unavailable'::"text"))),
    CONSTRAINT "contract_signatures_ip_source_valid" CHECK (("client_ip_source" = ANY (ARRAY['vercel'::"text", 'unavailable'::"text"]))),
    CONSTRAINT "contract_signatures_path_format" CHECK (("signature_path" ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.png$'::"text")),
    CONSTRAINT "contract_signatures_sha256_format" CHECK (("signature_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contract_signatures_typed_name_length" CHECK (((("length"("btrim"("typed_name")) >= 1) AND ("length"("btrim"("typed_name")) <= 200)) AND ("typed_name" = "btrim"("typed_name")))),
    CONSTRAINT "contract_signatures_user_agent_length" CHECK ((("length"("user_agent") >= 1) AND ("length"("user_agent") <= 512))),
    CONSTRAINT "contract_signatures_width_range" CHECK ((("signature_width" >= 1) AND ("signature_width" <= 4096)))
);


ALTER TABLE "public"."contract_signatures" OWNER TO "postgres";


COMMENT ON TABLE "public"."contract_signatures" IS 'Immutable signing evidence, one per contract, written only by sign_contract. Retention is not decided; nothing deletes it automatically.';



CREATE OR REPLACE VIEW "private"."contract_signature_orphans" AS
 SELECT "name",
    "created_at",
    (("metadata" ->> 'size'::"text"))::bigint AS "size"
   FROM "storage"."objects" "o"
  WHERE (("bucket_id" = 'contract-signatures'::"text") AND (NOT (EXISTS ( SELECT 1
