CREATE TABLE IF NOT EXISTS "public"."contract_template_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "template_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "title" "text" NOT NULL,
    "sections" "jsonb" NOT NULL,
    "placeholders" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "draft_version" integer DEFAULT 0 NOT NULL,
    "published_at" timestamp with time zone,
    "published_by_membership_id" "uuid",
    "content_sha256" "text",
    "created_by_membership_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "usage" "text",
    "client_use_statement_version" "text",
    "client_use_statement" "text",
    "client_use_confirmed_at" timestamp with time zone,
    "client_use_confirmed_by_user_id" "uuid",
    CONSTRAINT "contract_template_versions_client_use_confirmed" CHECK ((((NOT ("usage" IS DISTINCT FROM 'client_use'::"text")) = ("client_use_confirmed_at" IS NOT NULL)) AND (("client_use_confirmed_at" IS NULL) = ("client_use_statement_version" IS NULL)) AND (("client_use_confirmed_at" IS NULL) = ("client_use_statement" IS NULL)) AND (("client_use_confirmed_at" IS NULL) = ("client_use_confirmed_by_user_id" IS NULL)))),
    CONSTRAINT "contract_template_versions_content_valid" CHECK (("private"."contract_template_problem"("title", "sections") IS NULL)),
    CONSTRAINT "contract_template_versions_draft_version_nonnegative" CHECK (("draft_version" >= 0)),
    CONSTRAINT "contract_template_versions_number_positive" CHECK (("version_number" >= 1)),
    CONSTRAINT "contract_template_versions_published_hash" CHECK ((("published_at" IS NULL) = ("content_sha256" IS NULL))),
    CONSTRAINT "contract_template_versions_sha256_format" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "contract_template_versions_usage_valid" CHECK (("usage" = ANY (ARRAY['demo'::"text", 'client_use'::"text", 'legacy'::"text"]))),
    CONSTRAINT "contract_template_versions_usage_when_published" CHECK ((("published_at" IS NULL) = ("usage" IS NULL)))
);


ALTER TABLE "public"."contract_template_versions" OWNER TO "postgres";


COMMENT ON TABLE "public"."contract_template_versions" IS 'Numbered text versions of a contract template. Drafts are editable; published versions are immutable and never deleted.';



COMMENT ON COLUMN "public"."contract_template_versions"."usage" IS 'demo | client_use | legacy (published before usage modes, not DEMO; contracts cannot be generated from it). Null while a draft.';



COMMENT ON COLUMN "public"."contract_template_versions"."client_use_statement" IS 'The exact statement the owner confirmed when publishing for client use. Flux DJ does not review agreements.';



COMMENT ON COLUMN "public"."contract_template_versions"."client_use_confirmed_at" IS 'Database time of the client-use confirmation (the publish time).';



CREATE TABLE IF NOT EXISTS "public"."contract_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
