CREATE TABLE IF NOT EXISTS "public"."proposal_selection_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "selection_id" "uuid" NOT NULL,
    "line_no" integer NOT NULL,
    "source" "text" NOT NULL,
    "item_key" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "quantity" integer NOT NULL,
    "unit_price_cents" bigint NOT NULL,
    "line_total_cents" bigint NOT NULL,
    "required_quantity" integer DEFAULT 0 NOT NULL,
    "required_reasons" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "tax_category" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "discount_cents" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "proposal_selection_lines_discount_range" CHECK ((("discount_cents" >= 0) AND ("discount_cents" <= "line_total_cents"))),
    CONSTRAINT "proposal_selection_lines_included_free" CHECK ((("source" <> 'included'::"text") OR (("unit_price_cents" = 0) AND ("required_quantity" = 0)))),
    CONSTRAINT "proposal_selection_lines_item_key_valid" CHECK ("private"."is_valid_key"("item_key")),
    CONSTRAINT "proposal_selection_lines_line_no_positive" CHECK (("line_no" >= 1)),
    CONSTRAINT "proposal_selection_lines_name_length" CHECK ((("length"("name") >= 1) AND ("length"("name") <= 200))),
    CONSTRAINT "proposal_selection_lines_optional_shape" CHECK ((("source" <> 'optional'::"text") OR ("required_quantity" = 0))),
    CONSTRAINT "proposal_selection_lines_package_shape" CHECK ((("source" <> 'package'::"text") OR (("quantity" = 1) AND ("required_quantity" = 0)))),
    CONSTRAINT "proposal_selection_lines_quantity_range" CHECK ((("quantity" >= 1) AND ("quantity" <= 10000))),
    CONSTRAINT "proposal_selection_lines_required_nonnegative" CHECK (("required_quantity" >= 0)),
    CONSTRAINT "proposal_selection_lines_required_shape" CHECK ((("source" <> 'required'::"text") OR (("required_quantity" >= 1) AND ("quantity" >= "required_quantity") AND ("cardinality"("required_reasons") >= 1)))),
    CONSTRAINT "proposal_selection_lines_source_valid" CHECK (("source" = ANY (ARRAY['package'::"text", 'included'::"text", 'optional'::"text", 'required'::"text"]))),
    CONSTRAINT "proposal_selection_lines_tax_category_valid" CHECK ("private"."is_valid_key"("tax_category")),
    CONSTRAINT "proposal_selection_lines_total" CHECK (("line_total_cents" = (("quantity")::bigint * "unit_price_cents"))),
    CONSTRAINT "proposal_selection_lines_unit_price_nonnegative" CHECK (("unit_price_cents" >= 0))
);


ALTER TABLE "public"."proposal_selection_lines" OWNER TO "postgres";


COMMENT ON COLUMN "public"."proposal_selection_lines"."discount_cents" IS 'This line''s share of the proposal discount; taxes apply to line_total_cents - discount_cents.';



CREATE TABLE IF NOT EXISTS "public"."proposal_selections" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "proposal_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "package_key" "text" NOT NULL,
    "addon_quantities" "jsonb" NOT NULL,
    "logistics_answers" "jsonb" NOT NULL,
    "subtotal_cents" bigint NOT NULL,
    "tax_cents" bigint NOT NULL,
    "total_cents" bigint NOT NULL,
    "currency" "text" NOT NULL,
    "tax_breakdown" "jsonb" NOT NULL,
    "selection_snapshot" "jsonb" NOT NULL,
    "pricing_version" "text" NOT NULL,
    "offer_sha256" "text" NOT NULL,
    "submitted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "idempotency_key" "text",
    "discount_cents" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "proposal_selections_addons_object" CHECK (("jsonb_typeof"("addon_quantities") = 'object'::"text")),
    CONSTRAINT "proposal_selections_answers_object" CHECK (("jsonb_typeof"("logistics_answers") = 'object'::"text")),
    CONSTRAINT "proposal_selections_currency_valid" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "proposal_selections_discount_range" CHECK ((("discount_cents" >= 0) AND ("discount_cents" <= "subtotal_cents"))),
    CONSTRAINT "proposal_selections_idempotency_key_format" CHECK (("idempotency_key" ~ '^[A-Za-z0-9_-]{16,64}$'::"text")),
    CONSTRAINT "proposal_selections_offer_sha256_format" CHECK (("offer_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "proposal_selections_package_key_valid" CHECK ("private"."is_valid_key"("package_key")),
    CONSTRAINT "proposal_selections_pricing_version_valid" CHECK (("pricing_version" ~ '^[a-z0-9._-]{1,40}$'::"text")),
    CONSTRAINT "proposal_selections_snapshot_object" CHECK (("jsonb_typeof"("selection_snapshot") = 'object'::"text")),
    CONSTRAINT "proposal_selections_submitted" CHECK (("submitted_at" IS NOT NULL)),
    CONSTRAINT "proposal_selections_subtotal_nonnegative" CHECK (("subtotal_cents" >= 0)),
    CONSTRAINT "proposal_selections_tax_breakdown_array" CHECK (("jsonb_typeof"("tax_breakdown") = 'array'::"text")),
    CONSTRAINT "proposal_selections_tax_nonnegative" CHECK (("tax_cents" >= 0)),
    CONSTRAINT "proposal_selections_total_sum" CHECK (("total_cents" = (("subtotal_cents" - "discount_cents") + "tax_cents"))),
    CONSTRAINT "proposal_selections_version_positive" CHECK (("version" >= 1))
);


ALTER TABLE "public"."proposal_selections" OWNER TO "postgres";


COMMENT ON TABLE "public"."proposal_selections" IS 'Immutable, versioned client selection with server-computed pricing. Written only through record_proposal_selection.';



COMMENT ON COLUMN "public"."proposal_selections"."discount_cents" IS 'The proposal discount applied to this selection (0 when the offer has none). total = subtotal - discount + tax.';



