    CONSTRAINT "proposals_draft_offer_valid" CHECK ("private"."is_valid_draft_offer"("draft_offer")),
    CONSTRAINT "proposals_draft_version_nonnegative" CHECK (("draft_version" >= 0)),
    CONSTRAINT "proposals_non_draft_frozen" CHECK ((("status" = 'draft'::"text") OR ("offer_snapshot" IS NOT NULL))),
    CONSTRAINT "proposals_offer_sha256_format" CHECK (("offer_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "proposals_revision_positive" CHECK (("revision" >= 1)),
    CONSTRAINT "proposals_selection_version_nonnegative" CHECK (("current_selection_version" >= 0)),
