    CONSTRAINT "proposals_snapshot_frozen_at_together" CHECK ((("offer_snapshot" IS NULL) = ("offer_frozen_at" IS NULL))),
    CONSTRAINT "proposals_snapshot_hash_together" CHECK ((("offer_snapshot" IS NULL) = ("offer_sha256" IS NULL))),
    CONSTRAINT "proposals_status_valid" CHECK (("status" = ANY (ARRAY['draft'::"text", 'sent'::"text", 'submitted'::"text", 'approved'::"text", 'expired'::"text", 'superseded'::"text", 'declined'::"text"])))
);


