COMMENT ON TABLE "public"."tenant_logos" IS 'Logos verified and re-encoded by the server (PNG). Immutable and never deleted, so frozen proposals keep their logo.';



CREATE TABLE IF NOT EXISTS "public"."tenant_memberships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "role" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "removed_at" timestamp with time zone,
    "removed_by" "uuid",
    CONSTRAINT "tenant_memberships_owner_not_removed" CHECK ((("removed_at" IS NULL) OR ("role" = 'staff'::"text"))),
    CONSTRAINT "tenant_memberships_removed_complete" CHECK ((("removed_at" IS NULL) = ("removed_by" IS NULL))),
    CONSTRAINT "tenant_memberships_role_valid" CHECK (("role" = ANY (ARRAY['owner'::"text", 'staff'::"text"])))
);


ALTER TABLE "public"."tenant_memberships" OWNER TO "postgres";


COMMENT ON TABLE "public"."tenant_memberships" IS 'Staff access to a tenant. Removal sets removed_at (the row stays for attribution); removed rows grant nothing.';



COMMENT ON COLUMN "public"."tenant_memberships"."removed_at" IS 'Set by remove_staff_member. A removed membership grants no access; accept_staff_invitation can restore it.';



CREATE TABLE IF NOT EXISTS "public"."tenants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "slug" "text" NOT NULL,
    "business_name" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "logo_storage_path" "text",
    "brand_colors" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "reply_to_email" "text",
    "timezone" "text" DEFAULT 'America/Toronto'::"text" NOT NULL,
    "currency" "text" DEFAULT 'CAD'::"text" NOT NULL,
    "planning_lock_days" integer DEFAULT 14 NOT NULL,
    "booking_confirmation_policy" "text" DEFAULT 'on_deposit'::"text" NOT NULL,
    "tax_config" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tax_categories" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "business_address" "text",
    "contact_email" "text",
    "deposit_percent" integer DEFAULT 50 NOT NULL,
    "tax_settings_version" integer DEFAULT 1 NOT NULL,
    "booking_policy_version" integer DEFAULT 0 NOT NULL,
    "planning_settings_version" integer DEFAULT 0 NOT NULL,
    "suspended_at" timestamp with time zone,
    "suspension_version" integer DEFAULT 0 NOT NULL,
    "branding_version" integer DEFAULT 0 NOT NULL,
    "dj_name" "text",
    CONSTRAINT "tenants_booking_policy_valid" CHECK (("booking_confirmation_policy" = ANY (ARRAY['on_signature'::"text", 'on_deposit'::"text"]))),
    CONSTRAINT "tenants_booking_policy_version_nonnegative" CHECK (("booking_policy_version" >= 0)),
    CONSTRAINT "tenants_brand_colors_valid" CHECK ("private"."is_valid_brand_colors"("brand_colors")),
    CONSTRAINT "tenants_branding_version_nonnegative" CHECK (("branding_version" >= 0)),
    CONSTRAINT "tenants_business_address_length" CHECK ((("length"("btrim"("business_address")) >= 1) AND ("length"("btrim"("business_address")) <= 500))),
    CONSTRAINT "tenants_business_name_length" CHECK ((("length"("btrim"("business_name")) >= 1) AND ("length"("btrim"("business_name")) <= 200))),
    CONSTRAINT "tenants_contact_email_valid" CHECK ("private"."is_valid_email"("contact_email")),
    CONSTRAINT "tenants_currency_valid" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "tenants_deposit_percent_range" CHECK ((("deposit_percent" >= 0) AND ("deposit_percent" <= 100))),
    CONSTRAINT "tenants_display_name_length" CHECK ((("length"("btrim"("display_name")) >= 1) AND ("length"("btrim"("display_name")) <= 200))),
    CONSTRAINT "tenants_dj_name_length" CHECK ((("dj_name" = "btrim"("dj_name")) AND (("length"("dj_name") >= 1) AND ("length"("dj_name") <= 80)))),
    CONSTRAINT "tenants_logo_path_length" CHECK ((("length"("logo_storage_path") >= 1) AND ("length"("logo_storage_path") <= 1024))),
    CONSTRAINT "tenants_planning_lock_days_range" CHECK ((("planning_lock_days" >= 0) AND ("planning_lock_days" <= 365))),
    CONSTRAINT "tenants_planning_settings_version_nonnegative" CHECK (("planning_settings_version" >= 0)),
    CONSTRAINT "tenants_reply_to_email_valid" CHECK ("private"."is_valid_email"("reply_to_email")),
    CONSTRAINT "tenants_slug_valid" CHECK ("private"."is_valid_tenant_slug"("slug")),
    CONSTRAINT "tenants_suspension_version_nonnegative" CHECK (("suspension_version" >= 0)),
    CONSTRAINT "tenants_tax_categories_valid" CHECK ("private"."is_valid_tax_categories"("tax_config", "tax_categories")),
    CONSTRAINT "tenants_tax_config_valid" CHECK ("private"."is_valid_tax_config"("tax_config")),
    CONSTRAINT "tenants_tax_settings_version_positive" CHECK (("tax_settings_version" >= 1)),
    CONSTRAINT "tenants_timezone_valid" CHECK ("private"."is_valid_timezone"("timezone"))
);


ALTER TABLE "public"."tenants" OWNER TO "postgres";


COMMENT ON TABLE "public"."tenants" IS 'A DJ business. Root of tenant isolation; the only table without tenant_id.';



COMMENT ON COLUMN "public"."tenants"."business_name" IS 'Legal business name used in contracts. display_name is the client-facing brand.';



COMMENT ON COLUMN "public"."tenants"."planning_lock_days" IS 'Calendar days before the event when client planning edits close (0-365, default 14). Copied into each plan when it is set up; owner only, via update_planning_cutoff_days.';



COMMENT ON COLUMN "public"."tenants"."booking_confirmation_policy" IS 'on_deposit (signed + deposit received; default) or on_signature. Frozen into each contract when generated.';



COMMENT ON COLUMN "public"."tenants"."tax_config" IS 'Array of {code,label,rate_ppm}; rate_ppm is parts per million (50000 = 5%).';



COMMENT ON COLUMN "public"."tenants"."tax_categories" IS 'Maps tax category keys (used by gear and packages) to tax codes in tax_config. No implicit default.';



COMMENT ON COLUMN "public"."tenants"."business_address" IS 'Legal business address used in contracts.';



COMMENT ON COLUMN "public"."tenants"."contact_email" IS 'Business contact email used in contracts (separate from reply_to_email routing).';



COMMENT ON COLUMN "public"."tenants"."deposit_percent" IS 'Deposit due on signing, whole percent of the approved total including taxes (0-100).';



COMMENT ON COLUMN "public"."tenants"."tax_settings_version" IS 'Optimistic version for update_tax_settings; increases by one on every tax settings change.';



COMMENT ON COLUMN "public"."tenants"."suspended_at" IS 'Set while a platform administrator has suspended the workspace (see suspend_workspace). The reason is only in platform_audit_events.';



COMMENT ON COLUMN "public"."tenants"."suspension_version" IS 'Optimistic version for suspend_workspace and restore_workspace; increases by one on every change.';



COMMENT ON COLUMN "public"."tenants"."branding_version" IS 'Optimistic version for update_tenant_branding; increases by one on every branding change.';



COMMENT ON COLUMN "public"."tenants"."dj_name" IS 'Optional name of the DJ that planning shows clients ("DJ Boukine (your DJ)"), when no event names its own. Owner only, via update_planning_dj_name.';



